def init_fantasy_data(user_id: int, first_name: str = "", username: str = ""):
    """Ensure a persistent fantasy profile exists for this user."""
    if user_id not in fantasy_data:
        fantasy_data[user_id] = {
            "points": 0,
            "first_name": first_name or "Player",
            "username": username or "",
            "matches_played": 0,
            "best_match_points": 0,
            "title": None,          # currently equipped title key
            "titles_owned": [],     # list of purchased title keys
        }
    else:
        if first_name:
            fantasy_data[user_id]["first_name"] = first_name
        if username:
            fantasy_data[user_id]["username"] = username
        # Backfill any missing keys (e.g. profiles saved before a field existed)
        fantasy_data[user_id].setdefault("points", 0)
        fantasy_data[user_id].setdefault("matches_played", 0)
        fantasy_data[user_id].setdefault("best_match_points", 0)
        fantasy_data[user_id].setdefault("title", None)
        fantasy_data[user_id].setdefault("titles_owned", [])


def get_fantasy_title_info(key: str):
    """Look up a title's display name/price by its key."""
    for t in FANTASY_TITLES:
        if t["key"] == key:
            return t
    return None


def get_fantasy_squad_cap(match: 'Match') -> int:
    """
    Dream III size for this match's combined player pool — max 3 picks,
    Dream11-style but scaled down. Caps at pool size for tiny lobbies.
    """
    pool_size = len(match.team_x.players) + len(match.team_y.players)
    return max(1, min(FANTASY_SQUAD_SIZE, pool_size))


def award_fantasy_wicket(match: 'Match', bowler: 'Player'):
    """Credit +30 fantasy points to every squad owner who picked this bowler."""
    squads = getattr(match, "fantasy_squads", None)
    if not squads:
        return
    for squad in squads.values():
        if bowler.user_id in squad.get("players", []):
            squad["match_points"] = squad.get("match_points", 0) + FANTASY_PTS_PER_WICKET
            squad.setdefault("log", []).append(f"🎯 +{FANTASY_PTS_PER_WICKET} · {bowler.first_name} took a wicket")


def award_fantasy_runs(match: 'Match', striker: 'Player', runs: int):
    """Credit run points (+ six bonus) to every squad owner who picked this batsman."""
    if runs <= 0:
        return
    squads = getattr(match, "fantasy_squads", None)
    if not squads:
        return
    is_six = (runs == 6)
    pts = (runs * FANTASY_PTS_PER_RUN) + (FANTASY_PTS_PER_SIX_BONUS if is_six else 0)
    for squad in squads.values():
        if striker.user_id in squad.get("players", []):
            squad["match_points"] = squad.get("match_points", 0) + pts
            if is_six:
                squad.setdefault("log", []).append(f"🚀 +{pts} · {striker.first_name} smashed a SIX")


# ═══════════════════════════════════════════════════════════════
# RESUMABLE MATCH SYSTEM → /regame <code>
# When a match is force-stopped mid-way (host used /endmatch or /endsolo
# WITHOUT a result/winner being declared), a snapshot is saved to disk for
# 12 hours under a unique 8-char code. The ORIGINAL HOST can bring that
# exact game state back with /regame <code>, in the SAME group only.
# Matches that finished naturally (winner announced) are NEVER snapshotted.
# ═══════════════════════════════════════════════════════════════

RESUMABLE_DIR = "resumable_matches"
RESUMABLE_INDEX_FILE = os.path.join(RESUMABLE_DIR, "resumable_index.json")
RESUMABLE_MATCHES: Dict[str, Dict] = {}   # code -> {group_id, group_name, host_id, file_path, created_at, expires_at}
RESUMABLE_TTL_HOURS = 12

# asyncio Task / lock handles can't be pickled — strip them before saving,
# they get recreated naturally as the resumed match continues.
_RESUME_STRIP_ATTRS = [
    'ball_timeout_task', 'batsman_selection_task', 'bowler_selection_task',
    'join_phase_task', 'solo_timer_task', 'pause_task', 'active_ball_task',
]


def _generate_resume_code(length: int = 8) -> str:
    """8-character alphanumeric code, unambiguous enough for players to type in chat."""
    alphabet = string.ascii_letters + string.digits
    return ''.join(secrets.choice(alphabet) for _ in range(length))


def _save_resumable_index():
    """Persist the resumable-match code index to disk so it survives restarts."""
    try:
        os.makedirs(RESUMABLE_DIR, exist_ok=True)
        with open(RESUMABLE_INDEX_FILE, "w") as f:
            json.dump(RESUMABLE_MATCHES, f, indent=2)
    except Exception as e:
        logger.error(f"Failed to save resumable match index: {e}")


def _load_resumable_index():
    """Load the resumable-match code index on startup."""
    global RESUMABLE_MATCHES
    try:
        if os.path.exists(RESUMABLE_INDEX_FILE):
            with open(RESUMABLE_INDEX_FILE, "r") as f:
                RESUMABLE_MATCHES = json.load(f)
            logger.info(f"✅ Loaded {len(RESUMABLE_MATCHES)} resumable match entries")
    except Exception as e:
        logger.error(f"Failed to load resumable match index: {e}")


def _discard_resumable(code: str):
    """Remove a resumable snapshot (used, or expired) from disk + index."""
    meta = RESUMABLE_MATCHES.pop(code, None)
    if meta:
        try:
            fp = meta.get("file_path")
            if fp and os.path.exists(fp):
                os.remove(fp)
        except Exception as e:
            logger.error(f"Failed to remove resumable snapshot file for {code}: {e}")
    _save_resumable_index()


def save_match_for_resume(match, group_id: int, group_name: str, host_id: int) -> Optional[str]:
    """
    Snapshot a mid-game-stopped match (NO result declared) to disk so
    /regame <code> can restore it within RESUME_TTL_HOURS. Reuses the code
    that was already assigned to this match at creation time (match.resume_code)
    so the same code shown at match-start still works at match-end.
    """
    try:
        os.makedirs(RESUMABLE_DIR, exist_ok=True)

        code = getattr(match, 'resume_code', None) or _generate_resume_code()
        while code in RESUMABLE_MATCHES:
            code = _generate_resume_code()

        # Strip un-picklable live asyncio Task handles before pickling.
        stripped = {}
        for attr in _RESUME_STRIP_ATTRS:
            if hasattr(match, attr):
                stripped[attr] = getattr(match, attr)
                setattr(match, attr, None)

        file_path = os.path.join(RESUMABLE_DIR, f"resume_{code}.pkl")
        try:
            with open(file_path, "wb") as f:
                pickle.dump(match, f, protocol=pickle.HIGHEST_PROTOCOL)
        finally:
            for attr, val in stripped.items():
                setattr(match, attr, val)

        expires_at = (datetime.now() + timedelta(hours=RESUMABLE_TTL_HOURS)).isoformat()
        RESUMABLE_MATCHES[code] = {
            "group_id": group_id,
            "group_name": group_name,
            "host_id": host_id,
            "file_path": file_path,
            "created_at": datetime.now().isoformat(),
            "expires_at": expires_at,
        }
        _save_resumable_index()
        logger.info(f"💾 Saved resumable snapshot for group {group_id} → code {code}")
        return code
    except Exception as e:
        logger.error(f"Failed to save resumable match snapshot: {e}")
        return None


async def announce_resume_code(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match):
    """Send the resume code to the group right after a match starts."""
    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=(
                f"🔑 <b>Resume Code:</b> <code>{match.resume_code}</code>\n"
                f"If this match gets force-stopped mid-way, the host can bring it "
                f"back exactly where it left off with <code>/regame {match.resume_code}</code> "
                f"— valid for {RESUMABLE_TTL_HOURS} hours."
            ),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        logger.debug(f"Could not announce resume code: {e}")


async def resumable_cleanup_job(context: ContextTypes.DEFAULT_TYPE):
    """Background job: delete resumable snapshots older than RESUMABLE_TTL_HOURS."""
    try:
        now = datetime.now()
        expired = []
        for code, meta in list(RESUMABLE_MATCHES.items()):
            try:
                expires_at = datetime.fromisoformat(meta["expires_at"])
            except Exception:
                expires_at = now - timedelta(seconds=1)
            if now > expires_at:
                expired.append(code)
        for code in expired:
            _discard_resumable(code)
        if expired:
            logger.info(f"🧹 Auto-deleted {len(expired)} expired resumable match snapshot(s)")
    except Exception as e:
        logger.error(f"Error in resumable_cleanup_job: {e}")


class Player:
    """Represents a player in the match"""
    def __init__(self, user_id: int, username: str, first_name: str):
        self.user_id = user_id
        self.username = username
        self.first_name = first_name
        self.runs = 0
        self.balls_faced = 0
        self.wickets = 0
        self.balls_bowled = 0
        self.runs_conceded = 0
        self.consecutive_wickets = 0  # Track consecutive wickets for hat-trick
        self.has_hat_trick = False     # Flag to celebrate hat-trick only once
        self.is_out = False
        self.dismissal_type = None
        self.dismissal_fielder_name = None  # 🧤 who caught/stumped this batsman (if any)
        self.catches = 0     # 🧤 catches taken this match
        self.stumpings = 0   # 🧤 stumpings this match (used to infer Wicket-Keeper role)
        self.dot_balls_faced = 0
        self.dot_balls_bowled = 0
        self.boundaries = 0
        self.sixes = 0
        self.ducks = 0  # 🦆 number of times out on 0
        self.dots = 0  # Track dot balls
        self.overs_bowled = 0
        self.maiden_overs = 0
        self.no_balls = 0
        self.wides = 0
        self.has_bowled_this_over = False
        self.batting_timeouts = 0
        self.bowling_timeouts = 0
        self.is_bowling_banned = False
    
    def get_strike_rate(self) -> float:
        """Calculate batting strike rate"""
        if self.balls_faced == 0:
            return 0.0
        return round((self.runs / self.balls_faced) * 100, 2)
    
    def get_economy(self) -> float:
        """Calculate bowling economy rate"""
        if self.balls_bowled == 0:
            return 0.0
        overs = self.balls_bowled / 6
        if overs == 0:
            return 0.0
        return round(self.runs_conceded / overs, 2)
    
    def get_bowling_average(self) -> float:
        """Calculate bowling average"""
        if self.wickets == 0:
            return 0.0
        return round(self.runs_conceded / self.wickets, 2)

# Team class
class Team:
    """Represents a team in the match - COMPLETE VERSION"""
    def __init__(self, name: str):
        self.name = name
        self.players: List[Player] = []
        self.captain_id: Optional[int] = None
        self.captain_name: str = ""
        
        # Score tracking
        self.score = 0
        self.wickets = 0
        self.overs = 0.0
        self.balls = 0
        self.balls_faced = 0  # CRITICAL: Add this
        
        # Extras
        self.extras = 0
        self.extras_wide = 0   # CRITICAL: Add this
        self.extras_noball = 0  # CRITICAL: Add this
        
        # Game state
        self.drs_remaining = 1
        self.all_out = False
        
        # Batting order
        self.batting_order: List[int] = []
        self.striker_id: Optional[int] = None
        self.non_striker_id: Optional[int] = None

        # ✅ FIX: Frozen squad size at innings start — used for the "all out" check
        # so that removing a player mid-game doesn't corrupt/prematurely-end or hang the innings.
        self.innings_start_squad_size: Optional[int] = None
        
        # Current batsmen
        self.current_batsman_idx: Optional[int] = None
        self.current_non_striker_idx: Optional[int] = None
        self.out_players_indices = set()
        
        # Bowling
        self.current_bowler_idx: Optional[int] = None
        self.current_bowler_name: str = ""
        self.penalty_runs = 0
        self.penalty_runs_history: List[int] = []  # per-over penalty run tracking for worm graph
        self.bowler_history: List[int] = []
        
        # Player stats tracking
        self.player_stats: Dict[int, Dict] = {}

    def is_all_out(self):
        return (len(self.players) - len(self.out_players_indices)) < 2

    def swap_batsmen(self):
        if self.current_batsman_idx is not None and self.current_non_striker_idx is not None:
            self.current_batsman_idx, self.current_non_striker_idx = \
                self.current_non_striker_idx, self.current_batsman_idx

    def add_player(self, player: Player):
        self.players.append(player)
        # Initialize player stats
        if player.user_id not in self.player_stats:
            self.player_stats[player.user_id] = {
                "runs": 0,
                "balls": 0,
                "fours": 0,
                "sixes": 0,
                "wickets": 0,
                "runs_conceded": 0,
                "balls_bowled": 0,
                "dismissal": "not out"
            }
    
    def remove_player(self, user_id: int) -> bool:
        for i, player in enumerate(self.players):
            if player.user_id == user_id:
                self.players.pop(i)
                # ✅ Fix indices so match doesn't break after mid-match removal
                # Adjust current_batsman_idx
                if self.current_batsman_idx is not None:
                    if self.current_batsman_idx == i:
                        self.current_batsman_idx = None  # Need new batsman
                    elif self.current_batsman_idx > i:
                        self.current_batsman_idx -= 1
                # Adjust current_non_striker_idx
                if self.current_non_striker_idx is not None:
                    if self.current_non_striker_idx == i:
                        self.current_non_striker_idx = None
                    elif self.current_non_striker_idx > i:
                        self.current_non_striker_idx -= 1
                # Adjust current_bowler_idx
                if self.current_bowler_idx is not None:
                    if self.current_bowler_idx == i:
                        self.current_bowler_idx = None  # Need new bowler
                    elif self.current_bowler_idx > i:
                        self.current_bowler_idx -= 1
                # Adjust bowler_history indices
                self.bowler_history = [
                    (h - 1 if h > i else h)
                    for h in self.bowler_history if h != i
                ]
                # 🔧 GLITCH FIX: out_players_indices was never shifted here, so removing
                # a player whose index came before an already-out player's index left
                # that set pointing at the WRONG player — corrupting all-out detection
                # and the "who's available to bat" list after any add-then-remove.
                self.out_players_indices = {
                    (idx - 1 if idx > i else idx)
                    for idx in self.out_players_indices if idx != i
                }
                return True
        return False
    
    def get_player(self, user_id: int) -> Optional[Player]:
        for player in self.players:
            if player.user_id == user_id:
                return player
        return None
    
    def get_player_by_serial(self, serial: int) -> Optional[Player]:
        if 1 <= serial <= len(self.players):
            return self.players[serial - 1]
        return None
    
    def get_available_bowlers(self) -> List[Player]:
        available = []
        last_bowler_idx = self.bowler_history[-1] if self.bowler_history else None
    
        for i, player in enumerate(self.players):
            if not player.is_bowling_banned and i != last_bowler_idx:
                available.append(player)
        return available
    
    def update_overs(self):
        """Update overs display"""
        complete_overs = self.balls // 6
        balls_in_over = self.balls % 6
        self.overs = complete_overs + (balls_in_over / 10)
        # Also update balls_faced for compatibility
        self.balls_faced = self.balls
    
    def get_current_over_balls(self) -> int:
        """Returns balls in current over (0-5)"""
        return self.balls % 6
    
    def complete_over(self):
        """Complete the current over - NOTE: over tracking is handled in check_over_complete, not here"""
        remaining_balls = 6 - (self.balls % 6)
        if remaining_balls < 6:
            self.balls += remaining_balls
        self.update_overs()

# Match class - Core game engine
class Match:
    """Main match class that handles all game logic"""
    def __init__(self, group_id: int, group_name: str):
        self.group_id = group_id
        self.group_name = group_name
        self.phase = GamePhase.TEAM_JOINING
        self.match_id = f"{group_id}_{int(time.time())}"
        self.created_at = datetime.now()
        self.last_activity = time.time()  # Track last move time
        self.team_x_over_runs = [] # List to store runs per over for Team X
        self.team_y_over_runs = []
        self.current_over_runs = 0
        
        # Teams
        self.team_x = Team("Team X")
        self.team_y = Team("Team Y")
        self.editing_team: Optional[str] = None  # 'X' ya 'Y' store karega
        
        # Match settings
        self.host_id: Optional[int] = None
        self.total_overs = 0
        self.toss_winner: Optional[Team] = None
        self.batting_first: Optional[Team] = None
        self.bowling_first: Optional[Team] = None
        self.current_batting_team: Optional[Team] = None
        self.current_bowling_team: Optional[Team] = None
        
        # Match state
        self.innings = 1
        self.target = 0
        self.is_free_hit = False
        self.last_wicket_ball = None
        self.drs_in_progress = False
        self.team_x_timeout_used = False
        self.team_y_timeout_used = False
        self.is_paused = False          # ⏸️ Timeout pause flag
        self.pause_until: float = 0.0   # epoch time when pause ends
        self.pause_task: Optional[asyncio.Task] = None
        
        # Timers and messages
        self.team_join_end_time: Optional[float] = None
        self.main_message_id: Optional[int] = None
        self.join_phase_task: Optional[asyncio.Task] = None
        
        # Ball tracking
        self.current_ball_data: Dict = {}
        self.ball_timeout_task: Optional[asyncio.Task] = None
        self.batsman_selection_task: Optional[asyncio.Task] = None
        self.bowler_selection_task: Optional[asyncio.Task] = None
        # 🔧 GLITCH FIX: tracks the currently-running ball/turn processing
        # coroutine (execute_ball / process_ball_result / process_solo_turn_result)
        # so /endmatch and /endall can forcefully cancel it too, instead of just
        # cancelling the scheduled timers and leaving this one running to completion.
        self.active_ball_task: Optional[asyncio.Task] = None
        
        self.solo_players: List[Player] = [] # List of Player objects
        self.current_solo_bat_idx = 0
        self.current_solo_bowl_idx = 0
        self.solo_balls_this_spell = 0 # To track 3 ball rotation
        self.solo_join_end_time = 0
        self.host_change_votes = {}
        self.team_x_impact_count = 0  # Track number of substitutions used
        self.team_y_impact_count = 0
        self.team_x_impact_history = []  # List of (old_player_name, new_player_name)
        self.team_y_impact_history = []

        # Waiting states
        # Waiting states (FIXED: Added for batsman/bowler selection)
        self.waiting_for_batsman = False
        self.waiting_for_bowler = False
        self.batsman_selection_time: Optional[float] = None
        self.bowler_selection_time: Optional[float] = None
        self.pending_over_complete = False

        # Game mode (for TEAM/SOLO distinction, default TEAM)
        self.game_mode = "TEAM"

        # ── RESUME / /regame FEATURE ──
        # Unique 8-char code assigned at match creation. If the match gets
        # force-stopped mid-way (no result declared), this same code is used
        # to save a 12h-resumable snapshot. Shown to players at start & end.
        self.resume_code: str = _generate_resume_code()

        # 🆕 Mid-game /join requests — user_ids who have already sent /join this
        # match, so spamming /join repeatedly is ignored after the first request.
        self.mid_game_join_requests: Set[int] = set()

        # 🔒 Re-entrancy guard for end_innings() — prevents a duplicate ball event
        # from triggering the innings-end / Super Over flow twice in a row.
        self.innings_ending_lock = False
        
        # Super over
        self.is_super_over = False
        self.super_over_batting_team: Optional[Team] = None
        self.super_over_first_score: Optional[int] = None
        self.super_over_first_wickets: int = 0
        self.super_over_first_boundaries: int = 0
        
        # Match log
        self.ball_by_ball_log: List[Dict] = []
        self.match_events: List[str] = []
        self.strike_zones = {
            'team_x': defaultdict(int),  # {zone: runs}
            'team_y': defaultdict(int)
        }
        self.momentum_history = []  # List of (balls, momentum_score)
        self.current_momentum = 0  # Range: -100 to +100
        self.last_6_balls = []  # Track last 6 balls for momentum
        # Partnership tracking
        self.current_partnership_runs = 0
        self.current_partnership_balls = 0
        self.partnership_history = []
        self.longest_partnership_this_match = 0
        # Over wicket tracking
        self.team_x_over_wickets = []
        self.team_y_over_wickets = []
        self.current_over_wickets = 0

        # ── DECLARE feature ──
        self.declare_pending = False          # Batting cap requested declare
        self.declare_message_id: Optional[int] = None

        # ── RETIRE HURT feature ──
        self.retire_hurt_pending = False      # A batsman requested retire hurt
        self.retire_hurt_batsman_id: Optional[int] = None   # who wants to retire
        self.retire_hurt_message_id: Optional[int] = None

        # ── FANTASY DREAM XI feature (TEAM / TOURNAMENT only) ──
        self.fantasy_squads: Dict[int, Dict] = {}   # {owner_user_id: {"name", "players":[...], "match_points", "log":[...]}}
        self.fantasy_window_open = False            # True only while picking is allowed (TOSS phase)
        self.fantasy_announce_message_id: Optional[int] = None
    
    def get_team_by_name(self, name: str) -> Optional[Team]:
        """Get team by name"""
        if name == "Team X":
            return self.team_x
        elif name == "Team Y":
            return self.team_y
        return None
    
    def get_other_team(self, team: Team) -> Team:
        """Get the opposing team"""
        if team == self.team_x:
            return self.team_y
        return self.team_x
    
    def get_captain(self, team: Team) -> Optional[Player]:
        """Get team captain"""
        if team.captain_id:
            return team.get_player(team.captain_id)
        return None
    
    def add_event(self, event: str):
        """Add event to match log"""
        timestamp = datetime.now().strftime("%H:%M:%S")
        self.match_events.append(f"[{timestamp}] {event}")
    
    def get_required_run_rate(self) -> float:
        """Calculate required run rate for chasing team"""
        if self.innings != 2 or not self.current_batting_team:
            return 0.0
        
        runs_needed = self.target - self.current_batting_team.score
        balls_remaining = (self.total_overs * 6) - self.current_batting_team.balls
        
        if balls_remaining <= 0:
            return 0.0
        
        overs_remaining = balls_remaining / 6
        return round(runs_needed / overs_remaining, 2)
    
    def is_innings_complete(self) -> bool:
        """Check if current innings is complete"""
        if not self.current_batting_team or not self.current_bowling_team:
            return False
        
        # All out — use the squad size FROZEN at innings start (not the live list length),
        # so removing a player mid-game can't cause a premature end or a stuck/incorrect state.
        squad_size = self.current_batting_team.innings_start_squad_size
        if squad_size is None:
            squad_size = len(self.current_batting_team.players)
        if self.current_batting_team.wickets >= squad_size - 1:
            return True
        
        # Overs complete
        if self.current_batting_team.balls >= self.total_overs * 6:
            return True
        
        # Target chased in second innings
        if self.innings == 2 and self.current_batting_team.score >= self.target:
            return True
        
        return False
    
    def get_match_summary(self) -> str:
        """Generate detailed match summary"""
        summary_lines = []
        summary_lines.append("=" * 40)
        summary_lines.append("MATCH SUMMARY")
        summary_lines.append("=" * 40)
        summary_lines.append("")
        
        # First innings
        first_team = self.batting_first
        if first_team:
            summary_lines.append(f"{first_team.name}: {first_team.score}/{first_team.wickets}")
            summary_lines.append(f"Overs: {first_team.overs}")
            summary_lines.append("")
        
        # Second innings
        if self.innings >= 2:
            second_team = self.get_other_team(first_team)
            summary_lines.append(f"{second_team.name}: {second_team.score}/{second_team.wickets}")
            summary_lines.append(f"Overs: {second_team.overs}")
            summary_lines.append("")
        
        summary_lines.append("=" * 40)
        return "\n".join(summary_lines)

# Utility functions
def update_over_stats(match):
    """Calculates runs scored in the just-concluded over and saves them."""
    
    # 1. Determine which team is currently batting
    bat_team = match.current_batting_team
    if bat_team is None:
        return
    if bat_team == match.team_x:
        already_accounted = sum(match.team_x_over_runs)
        runs_in_this_over = bat_team.score - already_accounted
        match.team_x_over_runs.append(max(0, runs_in_this_over))
    else:
        already_accounted = sum(match.team_y_over_runs)
        runs_in_this_over = bat_team.score - already_accounted
        match.team_y_over_runs.append(max(0, runs_in_this_over))

def get_random_gif(event: MatchEvent) -> str:
    """Get random GIF for an event"""
    gifs = GIFS.get(event, [])
    if gifs:
        return random.choice(gifs)
    return ""

def get_random_commentary(event_type: str) -> str:
    """Get random commentary for an event"""
    comments = COMMENTARY.get(event_type, [])
    if comments:
        return random.choice(comments)
    return ""


def generate_mini_scorecard(match: Match, wicket_mode: bool = False) -> str:
    """
    Generate Mini Scorecard with Current Stats
    Shows after: Wicket, Over Complete

    wicket_mode=True → uses the new text-only "MATCH CENTRE" template
    (no photo/chart attached, "Waiting for Striker" shown when the new
    batsman hasn't been selected yet).
    """
    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    # Get Current Batsmen
    striker = None
    non_striker = None
    if bat_team.current_batsman_idx is not None:
        striker = bat_team.players[bat_team.current_batsman_idx]
    if bat_team.current_non_striker_idx is not None:
        non_striker = bat_team.players[bat_team.current_non_striker_idx]
    
    # Get Last Bowler (Most Recent)
    last_bowler = None
    if bowl_team.current_bowler_idx is not None:
        last_bowler = bowl_team.players[bowl_team.current_bowler_idx]
    elif bowl_team.bowler_history:
        last_bowler_idx = bowl_team.bowler_history[-1]
        last_bowler = bowl_team.players[last_bowler_idx]
    
    # Striker stats
    csr = round((striker.runs / striker.balls_faced) * 100, 2) if striker and striker.balls_faced > 0 else 0.0
    striker_runs = striker.runs if striker else 0
    striker_balls = striker.balls_faced if striker else 0

    # Calculate current over deliveries dynamically from ball_by_ball_log
    team_balls = [
        b for b in match.ball_by_ball_log
        if b.get("batting_team") == bat_team.name
    ]
    cur_over_parts = []
    legal_count = 0
    target_legal = bat_team.balls % 6
    if target_legal == 0 and bat_team.balls > 0:
        target_legal = 6
    
    for b in reversed(team_balls):
        is_legal = not (b.get('wide') or b.get('noball'))
        if b.get('wicket') or b.get('is_wicket'):
            cur_over_parts.insert(0, 'W')
        elif b.get('noball'):
            cur_over_parts.insert(0, 'NB')
        elif b.get('wide'):
            cur_over_parts.insert(0, 'WD')
        else:
            cur_over_parts.insert(0, str(b.get('runs', 0)))
            
        if is_legal:
            legal_count += 1
            if legal_count == target_legal:
                break
    over_sep = " • " if wicket_mode else ", "
    over_str = over_sep.join(cur_over_parts) if cur_over_parts else "-"

    # Build player tags (clickable mentions)
    striker_tag = f'<a href="tg://user?id={striker.user_id}">{html.escape(striker.first_name)}</a>' if striker else None
    non_striker_tag = f'<a href="tg://user?id={non_striker.user_id}">{html.escape(non_striker.first_name)}</a>' if non_striker else "—"
    bowler_tag = f'<a href="tg://user?id={last_bowler.user_id}">{html.escape(last_bowler.first_name)}</a>' if last_bowler else "—"
    ns_csr = round((non_striker.runs / non_striker.balls_faced) * 100, 2) if non_striker and non_striker.balls_faced > 0 else 0.0
    ns_runs = non_striker.runs if non_striker else 0
    ns_balls = non_striker.balls_faced if non_striker else 0

    tx = match.team_x
    ty = match.team_y
    tx_overs = format_overs(tx.balls)
    tx_rr = round(tx.score / max(tx.balls / 6, 0.1), 2) if tx.balls > 0 else 0.0
    ty_overs = format_overs(ty.balls)
    ty_rr = round(ty.score / max(ty.balls / 6, 0.1), 2) if ty.balls > 0 else 0.0

    if wicket_mode:
        msg = "📺 𝗠𝗔𝗧𝗖𝗛 𝗖𝗘𝗡𝗧𝗥𝗘\n"
        msg += "───────────────────\n"
        msg += "🏏 𝗟𝗜𝗩𝗘 𝗕𝗔𝗧𝗧𝗜𝗡𝗚\n"
        msg += "┌───────────────────\n"
        if striker_tag:
            msg += f"├ 👤 {striker_tag} ➔ {striker_runs} ({striker_balls}b)\n"
            msg += f"├ 📊 SR: {csr:.2f}\n"
        else:
            msg += "├ 👤 Waiting for Striker *\n"
            msg += "├ 📊 SR: -\n"
        msg += "│\n"
        if non_striker:
            msg += f"├ 👤 {non_striker_tag} ➔ {ns_runs} ({ns_balls}b)\n"
            msg += f"├ 📊 SR: {ns_csr:.2f}\n"
        else:
            msg += "├ 👤 - ➔ 0 (0b)\n"
            msg += "├ 📊 SR: -\n"
        msg += "└───────────────────\n"

        msg += "🎯 𝗟𝗜𝗩𝗘 𝗕𝗢𝗪𝗟𝗜𝗡𝗚\n"
        msg += "┌───────────────────\n"
        msg += f"├ 👤 {bowler_tag}\n"
        msg += f"├ 🍿 Over:  {over_str}\n"
        msg += "└───────────────────\n"

        msg += "📊 𝗠𝗔𝗧𝗖𝗛 𝗦𝗖𝗢𝗥𝗘𝗕𝗢𝗔𝗥𝗗\n"
        msg += "┌───────────────────\n"
        msg += f"├ 🔹 {html.escape(tx.name)}: {tx.score}/{tx.wickets} ({tx_overs} ov)\n"
        msg += f"├ ↳ CRR: {tx_rr:.2f}\n"
        msg += "│\n"
        msg += f"├ 🔸 {html.escape(ty.name)}: {ty.score}/{ty.wickets} ({ty_overs} ov)\n"
        msg += f"├ ↳ CRR: {ty_rr:.2f}\n"
        msg += "└───────────────────\n"

        if match.innings == 2:
            runs_needed = match.target - bat_team.score
            balls_left = (match.total_overs * 6) - bat_team.balls
            rrr = round((runs_needed / balls_left) * 6, 2) if balls_left > 0 else 0
            msg += f"\n⚠️ Target: Need {max(runs_needed,0)} runs in {max(balls_left,0)} balls (RRR: {rrr})"

        return msg

    striker_tag = striker_tag or "—"
    partnership = getattr(match, "current_partnership_runs", 0)
    partnership_balls = getattr(match, "current_partnership_balls", 0)
    msg = f"🏏 𝗟𝗜𝗩𝗘 𝗕𝗔𝗧𝗧𝗜𝗡𝗚 \n"
    msg += f"┌─────────────────── \n"
    msg += f"├ 👤 {striker_tag} ➔ {striker_runs} ({striker_balls}) \n"
    msg += f"├ 📈 𝗖𝗦𝗥: {csr:.2f} \n"
    msg += f"├ \n"
    if non_striker:
        msg += f"├ 👤 {non_striker_tag} ➔ {ns_runs} ({ns_balls}) \n"
        msg += f"├ 📈 𝗖𝗦𝗥: {ns_csr:.2f} \n"
    else:
        msg += f"├ 👤 - ➔ 0 (0) \n"
        msg += f"├ 📈 𝗖𝗦𝗥: 0.00 \n"
    msg += f"├ \n"
    msg += f"├ 🤝 𝗣𝗮𝗿𝘁𝗻𝗲𝗿𝘀𝗵𝗶𝗽 ➔ {partnership} ({partnership_balls}) \n"
    msg += f"└─────────────────── \n"
    
    msg += f"🥎 𝗟𝗜𝗩𝗘 𝗕𝗢𝗪𝗟𝗜𝗡𝗚 \n"
    msg += f"┌─────────────────── \n"
    msg += f"├ 👤 {bowler_tag} \n"
    msg += f"├ 📊 𝗧𝗵𝗶𝘀 𝗢𝘃𝗲𝗿: {over_str} \n"
    msg += f"└─────────────────── \n"
    
    msg += f" 🏆 𝗦𝗖𝗢𝗥𝗘𝗕𝗢𝗔𝗥𝗗\n"
    msg += f"┌─────────────────── \n"
    msg += f"├ 🔹 𝗧𝗘𝗔𝗠 {html.escape(tx.name)}: {tx.score}/{tx.wickets} ({tx_overs} ov) \n"
    msg += f"├ ↳ 𝗖𝗥𝗥: {tx_rr:.2f} \n"
    msg += f"├ \n"
    msg += f"├ 🔸 𝗧𝗘𝗔𝗠 {html.escape(ty.name)}: {ty.score}/{ty.wickets} ({ty_overs} ov) \n"
    msg += f"├ ↳ 𝗖𝗥𝗥: {ty_rr:.2f} \n"
    msg += f"└───────────────────\n"

    if match.innings == 2:
        runs_needed = match.target - bat_team.score
        balls_left = (match.total_overs * 6) - bat_team.balls
        rrr = round((runs_needed / balls_left) * 6, 2) if balls_left > 0 else 0
        msg += f"\n🎯 Need <b>{runs_needed}</b> off <b>{balls_left}</b> balls (RRR {rrr})"

    return msg
def format_overs(balls: int) -> str:
    """
    ✅ FIXED: Format balls to overs correctly
    🥚 0 balls = 0.0
    🏏 1 ball = 0.1
    📦 6 balls = 1.0
    🔄 7 balls = 1.1
    """
    if balls == 0:
        return "0.0"
    
    # 🔢 Calculate complete overs and remaining balls
    complete_overs = balls // 6
    balls_in_over = balls % 6
    
    return f"{complete_overs}.{balls_in_over}"


def balls_to_float_overs(balls: int) -> float:
    """Convert balls to float overs"""
    return balls // 6 + (balls % 6) / 10


# --- AUTO-EXECUTE ON START ---

def get_commentary(event_type: str, group_id: int = None, user_id: int = None, striker: str = "Batsman", bowler: str = "Bowler", fielder: str = "Fielder") -> str:
    """Get commentary based on GROUP setting formatted with player names."""
    group_style = None
    if group_id and group_id in gc_settings:
        group_style = gc_settings[group_id].get("commentary_style")
    if not group_style and group_id and group_id in registered_groups:
        group_style = registered_groups[group_id].get("commentary_style")
    
    user_style = None
    if user_id and user_id in user_data:
        user_style = user_data[user_id].get("commentary_style")
    
    style = "english"
    if group_style:
        style = group_style
    elif user_style:
        style = user_style
    
    dict_to_use = HINGLISH_COMMENTARY if style == "hinglish" else COMMENTARY
    comments = dict_to_use.get(event_type, [])
    if not comments:
        comments = COMMENTARY.get(event_type, ["Great shot by {striker}!"])
    
    tmpl = random.choice(comments)
    try:
        return tmpl.format(striker=html.escape(striker), bowler=html.escape(bowler), fielder=html.escape(fielder))
    except Exception:
        return tmpl

