def _solo_pad(s, w):
    s = html.escape(str(s))
    return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))


def _solo_rpad(s, w):
    s = str(s)
    return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s


def _build_solo_scorecard_html(match) -> str:
    """Real <table> version of the solo scorecard for sendRichMessage
    (Bot API 10.1+) — same pattern as build_new_scorecard_html."""
    players = match.solo_players

    bat_rows = ""
    sno = 0
    for i, p in enumerate(players):
        if p.balls_faced <= 0 and not p.is_out and i != match.current_solo_bat_idx:
            continue
        sno += 1
        status = "*" if p.is_out else (" (batting)" if i == match.current_solo_bat_idx else "")
        name = html.escape(f"{p.first_name}{status}")
        bat_rows += (
            f"<tr><td align='center'>{sno}</td><td>{name}</td><td align='right'>{p.runs}</td>"
            f"<td align='right'>{p.balls_faced}</td><td align='right'>{p.get_strike_rate()}</td>"
            f"<td align='right'>{p.sixes}</td><td align='right'>{p.boundaries}</td></tr>"
        )
    if not bat_rows:
        bat_rows = "<tr><td colspan='7' align='center'>No batters yet</td></tr>"
    bat_table = (
        "<table bordered striped>"
        "<tr><th>#️⃣</th><th>🧢Name</th><th>🏏Runs</th><th>⚪Balls</th><th>⚡S.R</th><th>🚀6s</th><th>🔥4s</th></tr>"
        f"{bat_rows}</table>"
    )

    bowl_rows = ""
    sno = 0
    for p in players:
        if p.balls_bowled <= 0:
            continue
        sno += 1
        extras = getattr(p, "wides", 0) + getattr(p, "no_balls", 0)
        name = html.escape(p.first_name)
        bowl_rows += (
            f"<tr><td align='center'>{sno}</td><td>{name}</td><td align='right'>{format_overs(p.balls_bowled)}</td>"
            f"<td align='right'>{p.runs_conceded}</td><td align='right'>{p.wickets}</td>"
            f"<td align='right'>{p.get_economy()}</td><td align='right'>{extras}</td></tr>"
        )
    if not bowl_rows:
        bowl_rows = "<tr><td colspan='7' align='center'>No bowling yet</td></tr>"
    bowl_table = (
        "<table bordered striped>"
        "<tr><th>#️⃣</th><th>🎯Name</th><th>⏱️Ovr</th><th>🏏Runs</th><th>🎳Wkt</th><th>💰Eco</th><th>➕Extra</th></tr>"
        f"{bowl_rows}</table>"
    )

    return f"<h3>🏏 SOLO SCORECARD</h3><p><b>Batting</b></p>{bat_table}<p><b>Bowling</b></p>{bowl_table}<footer>📟 SOLO SCORECARD 🎮</footer>"


def _build_solo_scorecard(match):
    """Build the standalone Solo Scorecard message: Batting table + Bowling
    table, with Refresh/Back buttons. Returns (text, InlineKeyboardMarkup)."""
    players = match.solo_players

    bat_header = f"{_solo_pad('#️⃣', 4)}{_solo_pad('🧢Name', 14)}{_solo_rpad('🏏R', 5)}{_solo_rpad('⚪B', 4)}{_solo_rpad('🔥4s', 5)}{_solo_rpad('🚀6s', 5)}{_solo_rpad('⚡S.R', 7)}\n"
    bat_table = bat_header + ("─" * 44) + "\n"
    sno = 0
    for i, p in enumerate(players):
        if p.balls_faced <= 0 and not p.is_out and i != match.current_solo_bat_idx:
            continue
        sno += 1
        status = ""
        if p.is_out:
            status = "*"
        elif i == match.current_solo_bat_idx:
            status = " (batting)"
        name = f"{p.first_name}{status}"
        bat_table += f"{_solo_pad(sno, 4)}{_solo_pad(name, 14)}{_solo_rpad(p.runs, 5)}{_solo_rpad(p.balls_faced, 4)}{_solo_rpad(p.boundaries, 5)}{_solo_rpad(p.sixes, 5)}{_solo_rpad(p.get_strike_rate(), 7)}\n"
    if sno == 0:
        bat_table += "  No batters yet\n"

    bowl_header = f"{_solo_pad('#️⃣', 4)}{_solo_pad('🎯Name', 14)}{_solo_rpad('⏱️Ovr', 6)}{_solo_rpad('🏏Run', 5)}{_solo_rpad('🎳Wkt', 5)}{_solo_rpad('💰Eco', 6)}{_solo_rpad('➕Ext', 5)}\n"
    bowl_table = bowl_header + ("─" * 45) + "\n"
    any_bowled = False
    sno = 0
    for i, p in enumerate(players):
        if p.balls_bowled <= 0:
            continue
        sno += 1
        any_bowled = True
        extras = getattr(p, "wides", 0) + getattr(p, "no_balls", 0)
        bowl_table += f"{_solo_pad(sno, 4)}{_solo_pad(p.first_name, 14)}{_solo_rpad(format_overs(p.balls_bowled), 6)}{_solo_rpad(p.runs_conceded, 5)}{_solo_rpad(p.wickets, 5)}{_solo_rpad(p.get_economy(), 6)}{_solo_rpad(extras, 5)}\n"
    if not any_bowled:
        bowl_table += "  No bowling yet\n"

    text = "🏏 <b>SOLO SCORECARD</b>\n─────────────────\n"
    text += "Batting\n"
    text += f"<pre>{bat_table}</pre>"
    text += "Bowling\n"
    text += f"<pre>{bowl_table}</pre>"
    text += "\n📟 SOLO SCORECARD 🎮"

    group_id = getattr(match, "group_id", None) or getattr(match, "chat_id", None)
    kb = InlineKeyboardMarkup([[
        styled_button("🔄 Refresh", callback_data=f"soloscore_refresh_{group_id}"),
        styled_button("◀ Back", callback_data=f"soloscore_back_{group_id}"),
    ]])
    return text, kb


async def soloscore_refresh_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Refresh button on the standalone Solo Scorecard message."""
    query = update.callback_query
    await query.answer()
    try:
        group_id = int(query.data[len("soloscore_refresh_"):])
    except ValueError:
        return
    match = active_matches.get(group_id)
    if not match:
        await query.answer("Match ended!", show_alert=True)
        return
    text, kb = _build_solo_scorecard(match)
    try:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.error(f"soloscore_refresh_callback edit error: {e}")


async def soloscore_back_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Back button on the standalone Solo Scorecard message → show the solo leaderboard."""
    query = update.callback_query
    await query.answer()
    try:
        group_id = int(query.data[len("soloscore_back_"):])
    except ValueError:
        return
    match = active_matches.get(group_id)
    if not match:
        await query.answer("Match ended!", show_alert=True)
        return

    sorted_players = sorted(match.solo_players, key=lambda x: x.runs, reverse=True)
    msg = "🏆 <b>SOLO BATTLE LEADERBOARD</b>\n─────────────────\n\n"
    for i, p in enumerate(sorted_players, 1):
        rank = f"<b>{i}.</b>"
        status = ""
        if p.is_out: status = " (out)"
        elif (i-1) == match.current_solo_bat_idx: status = " (batting)"
        elif (i-1) == match.current_solo_bowl_idx: status = " (bowling)"
        sr = round((p.runs / max(p.balls_faced, 1)) * 100, 1)
        msg += f"{rank} <b>{html.escape(p.first_name)}</b>{status}\n"
        msg += f"   {p.runs} runs ({p.balls_faced} balls)  SR: {sr}\n\n"
    msg += "─────────────────"

    kb = InlineKeyboardMarkup([[styled_button("✅ Table", callback_data=f"soloscore_refresh_{group_id}")]])
    try:
        await query.edit_message_text(msg, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.error(f"soloscore_back_callback edit error: {e}")


async def scorecard_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Enhanced scorecard → auto-detects Team/Solo mode"""
    group_id = update.effective_chat.id
    match = active_matches.get(group_id)

    if not match:
        await update.message.reply_text("🏏 No active match! Use /game to begin")
        return

    # ── SOLO MODE: standalone Batting/Bowling table scorecard ──
    if getattr(match, 'game_mode', None) in ["SOLO", "MAGICBALL"] or match.phase in [GamePhase.SOLO_JOINING, GamePhase.SOLO_MATCH]:
        text, kb = _build_solo_scorecard(match)
        try:
            html_solo = _build_solo_scorecard_html(match)
            ok = await _tg_send_rich_message(group_id, html_solo)
        except Exception as solo_rt_e:
            logger.warning(f"Solo scorecard rich table error: {solo_rt_e}")
            ok = False
        if ok:
            await update.message.reply_text(
                "🔄 Refresh / ◀ Back", reply_markup=kb, disable_notification=True
            )
        else:
            await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
        return

    # ── Image cooldown check ──
    if update.effective_chat.type != "private":
        remaining = check_image_cooldown(group_id)
        if remaining is not None:
            await send_cooldown_warning(update, remaining)
            return
        # ── Full scorecard 2-minute cooldown ──
        sc_remaining = check_scorecard_cooldown(group_id)
        if sc_remaining is not None:
            secs = math.ceil(sc_remaining)
            mins = secs // 60
            sec_part = secs % 60
            warn_msg = await update.message.reply_text(
                f"⏳ <b>Scorecard Cooldown</b>\n"
                f"Wait <b>{mins}m {sec_part}s</b> before using /scorecard again.\n"
                f"<i>Cooldown prevents spam (2 min per group).</i>",
                parse_mode=ParseMode.HTML
            )
            asyncio.get_event_loop().call_later(
                sc_remaining + 1,
                lambda: asyncio.ensure_future(warn_msg.delete())
            )
            return
        set_scorecard_cooldown(group_id)

    # ── New-style (TEAM-X/TEAM-Y, per-player drop-down) scorecard — capped
    # at MAX_NEW_SCORECARD_USES manual uses per match ──
    used = NEW_SCORECARD_USE_COUNT.get(group_id, 0)
    if used >= MAX_NEW_SCORECARD_USES:
        await update.message.reply_text(
            f"⚠️ Scorecard limit reached — used {used}/{MAX_NEW_SCORECARD_USES} times this match."
        )
    else:
        NEW_SCORECARD_USE_COUNT[group_id] = used + 1
        try:
            await send_new_scorecard(update.message, group_id, match)
        except Exception as nsc_e:
            logger.error(f"New-style scorecard error: {nsc_e}")

    # NOTE: /scorecard now sends exactly ONE message — the new-style table
    # scorecard above. It used to also auto-send a worm-graph photo here,
    # which is why the card visually appeared "twice". The worm graph is
    # still available on demand via its own refresh/worm button
    # (scorecard_worm_callback) instead of being force-sent every time.

async def cleanup_inactive_matches(context: ContextTypes.DEFAULT_TYPE):
    """Auto-end matches inactive for > 10 minutes"""
    current_time = time.time()
    inactive_threshold = 10 * 60  # 10 Minutes in seconds
    chats_to_remove = []

    # Check all active matches
    for chat_id, match in active_matches.items():
        if current_time - match.last_activity > inactive_threshold:
            chats_to_remove.append(chat_id)
            try:
                # Send Time Out Message
                await context.bot.send_message(
                    chat_id=chat_id,
                    text="⏰ <b>MATCH TIMEOUT!</b>\nGame auto-ended after 10 minutes of inactivity (no response recorded).",
                    parse_mode=ParseMode.HTML
                )
                # Unpin message
                if match.main_message_id:
                    await context.bot.unpin_chat_message(chat_id=chat_id, message_id=match.main_message_id)
            except Exception as e:
                logger.error(f"Error ending inactive match {chat_id}: {e}")

    # Remove from memory
    for chat_id in chats_to_remove:
        if chat_id in active_matches:
            del active_matches[chat_id]

async def game_timer(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, player_type: str, player_name: str):
    """Handles 45s timer with Penalties & Disqualification"""
    try:
        # Wait 30 seconds
        await asyncio.sleep(30)
        
        # Warning
        await context.bot.send_message(group_id, f"╭━━ ⏳ HURRY UP! ━━━━━━⚡\n┃ ⚠️ {html.escape(player_name)}, only 15s left!\n┃ ⚙ Play your ball now!\n╰━━━━━━━━", parse_mode=ParseMode.HTML)
        
        # Wait remaining 15 seconds
        await asyncio.sleep(15)
        
        # --- TIMEOUT HAPPENED ---
        await handle_timeout_penalties(context, group_id, match, player_type)
            
    except asyncio.CancelledError:
        pass # Timer stopped safely because player played

async def handle_timeout_penalties(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, player_type: str):
    """Process Penalties for Timeouts"""
    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    # --- BOWLER TIMEOUT ---
    if player_type == "bowler":
        bowler = bowl_team.players[bowl_team.current_bowler_idx]
        bowler.bowling_timeouts += 1
        
        # Case A: Disqualification (3 Timeouts)
        if bowler.bowling_timeouts >= 2:
            msg = f"🚫 <b>DISQUALIFIED!</b> {bowler.first_name} timed out 2 times!\n"
            msg += "⚠️ <b>The over will RESTART with a new bowler.</b>"
            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            # Reset Balls for this over (Over restart logic)
            # Example: If balls were 3.2 (20 balls), reset to 3.0 (18 balls)
            current_over_balls = bat_team.get_current_over_balls()
            bat_team.balls -= current_over_balls
            bat_team.update_overs()
            
            # Remove bowler from attack
            bowl_team.current_bowler_idx = None
            # bowler.is_bowling_banned kept False — can bowl again next over
            
            # Request New Bowler (bowler NOT permanently banned - only this over is restarted)
            match.current_ball_data = {} # Clear ball data
            bowler.is_bowling_banned = False  # ✅ Not permanently banned, just rotated out
            await request_bowler_selection(context, group_id, match)
            return

        # Case B: No Ball (Standard Timeout)
        else:
            bat_team.score += 1 # Penalty Run
            bat_team.extras += 1
            match.is_free_hit = True # Activate Free Hit
            
            msg = f"⏰ <b>BOWLER TIMEOUT!</b> ({bowler.bowling_timeouts}/2)\n"
            msg += "─────────────────\n"
            msg += "🚫 <b>Result:</b> NO BALL! (+1 Run)\n"
            msg += "⚡ <b>Next ball is a FREE HIT!</b>\n"

            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            # Reset inputs to allow re-bowl (No ball doesn't count legal ball)
            match.current_ball_data = {}

            # Re-send the bowling prompt to group (Bug 2 fix: always show bowling message after every delivery)
            # and retry DM to bowler; timer is restarted inside execute_ball (Bug 3 fix: timer keeps running)
            await execute_ball(context, group_id, match)

    # --- BATSMAN TIMEOUT ---
    elif player_type == "batsman":
        striker = bat_team.players[bat_team.current_batsman_idx]
        striker.batting_timeouts += 1
        
        # Case A: Hit Wicket (3 Timeouts)
        if striker.batting_timeouts >= 2:
            msg = f"🚫 <b>DISMISSED!</b> {striker.first_name} timed out 2 times.\n"
            msg += "❌ <b>Result:</b> HIT WICKET (OUT)!"
            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            # Trigger Wicket Logic Manually
            match.current_ball_data["batsman_number"] = match.current_ball_data["bowler_number"] # Force match numbers to trigger out
            await process_ball_result(context, group_id, match)
            
        # Case B: Penalty Runs (-6 Runs)
        else:
            bat_team.score -= 6
            bat_team.score = max(0, bat_team.score) # Score negative nahi jayega
            # Update current_over_runs for graph accuracy
            match.current_over_runs = max(0, getattr(match, 'current_over_runs', 0) - 6)
            
            msg = f"⏰ <b>BATSMAN TIMEOUT!</b> ({striker.batting_timeouts}/2)\n"
            msg += "─────────────────\n"
            msg += "📉 <b>Penalty:</b> -6 Runs!\n"
            msg += f"📊 <b>Score:</b> {bat_team.score}/{bat_team.wickets}\n"

            await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
            
            # Count ball but no runs (Treat as Dot Ball)
            bat_team.balls += 1
            bat_team.update_overs()
            match.current_ball_data = {} # Reset
            
            if bat_team.get_current_over_balls() == 0:
                await check_over_complete(context, group_id, match)
            else:
                await execute_ball(context, group_id, match)

