async def teamcreate_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Create a tournament team: /teamcreate [team name]"""
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("Use this command in a group!")
        return

    group_id = chat.id

    # Check approval → silently ignore unapproved groups
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return

    # Admin check
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only group admins can create teams!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamcreate [team name]</code>\nExample: <code>/teamcreate Team Alpha</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    team_name = " ".join(context.args).strip()
    
    if team_name in tournament_teams[group_id]:
        await update.message.reply_text(f"⚠️ Team '<b>{team_name}</b>' already exists!", parse_mode=ParseMode.HTML)
        return
    
    tournament_teams[group_id][team_name] = {"players": [], "captain": None}
    save_tour_state(group_id)  # ✅ persist immediately so a restart doesn't lose the team
    
    await update.message.reply_text(
        f"✅ <b>Team Created!</b>\n"
        f"─────────────────\n"
        f"🏏 <b>Team:</b> {team_name}\n\n"
        f"Now add players:\n"
        f"<code>/teamadd {team_name} @username @username2...</code>",
        parse_mode=ParseMode.HTML
    )


async def teamadd_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Add players to tournament team: /teamadd [team] @user @user2...
    Also supports reply to add single user, or user IDs."""
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.type == "private":
        await update.message.reply_text("Use this command in a group!")
        return
    
    group_id = chat.id
    
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return
    
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only admins can add players!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamadd [team name] @user @user2...</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Parse: first arg(s) might be multi-word team name, then @mentions
    args = context.args
    teams = tournament_teams.get(group_id, {})
    
    # Find team name (try progressively longer phrases)
    team_name = None
    player_args_start = 0
    for i in range(len(args), 0, -1):
        potential = " ".join(args[:i])
        if potential in teams:
            team_name = potential
            player_args_start = i
            break
    
    if not team_name:
        team_list = ", ".join(teams.keys()) if teams else "None"
        await update.message.reply_text(
            f"⚠️ Team not found!\nAvailable teams: {team_list}",
            parse_mode=ParseMode.HTML
        )
        return
    
    player_args = args[player_args_start:]
    added = []
    failed = []
    
    # Parse mentions and user IDs
    entities = update.message.entities or []
    mentioned_users = []
    for entity in entities:
        if entity.type == "mention":
            username = update.message.text[entity.offset+1:entity.offset+entity.length]
            try:
                chat_member = await context.bot.get_chat_member(group_id, f"@{username}")
                mentioned_users.append({
                    "user_id": chat_member.user.id,
                    "username": chat_member.user.username or "",
                    "first_name": chat_member.user.first_name
                })
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 5650)")
                failed.append(f"@{username}")
        elif entity.type == "text_mention" and entity.user:
            mentioned_users.append({
                "user_id": entity.user.id,
                "username": entity.user.username or "",
                "first_name": entity.user.first_name
            })
    
    # Also check numeric user IDs in args
    for arg in player_args:
        if arg.isdigit():
            try:
                cm = await context.bot.get_chat_member(group_id, int(arg))
                mentioned_users.append({
                    "user_id": cm.user.id,
                    "username": cm.user.username or "",
                    "first_name": cm.user.first_name
                })
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 5669)")
                failed.append(arg)
    
    team_data = tournament_teams[group_id][team_name]
    existing_ids = {p["user_id"] for p in team_data["players"]}
    
    not_started = []  # Users who haven't started the bot
    for p in mentioned_users:
        if p["user_id"] not in existing_ids:
            # ✅ Check if player has started the bot before adding
            started = await check_user_started_bot(context.bot, p["user_id"])
            if not started:
                not_started.append(p["first_name"])
                # Still add them — but warn the admin
            team_data["players"].append(p)
            existing_ids.add(p["user_id"])
            added.append(p["first_name"])
    
    bot_username = context.bot.username
    if added:
        save_tour_state(group_id)  # ✅ persist immediately so a restart doesn't lose the roster
    msg = f"✅ <b>Players Added to {team_name}</b>\n─────────────────\n"
    if added:
        msg += f"✅ Added: {', '.join(added)}\n"
    if failed:
        msg += f"⚠️ Not found in group: {', '.join(failed)}\n"
    if not_started:
        msg += (
            f"\n⚠️ <b>Hasn't started bot:</b> {', '.join(not_started)}\n"
            f"👉 Ask them to start: <a href='https://t.me/{bot_username}'>@{bot_username}</a>\n"
            f"<i>They won't receive bowl/bat DMs until they do!</i>\n"
        )
    msg += f"\n📊 <b>Team size:</b> {len(team_data['players'])} players"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, disable_web_page_preview=True)


async def teamremove_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Remove player(s) from tournament team: /teamremove [team] @user @user2..."""
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.type == "private":
        return
    
    group_id = chat.id
    
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return
    
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only admins can remove players!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamremove [team name] @user @user2...</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    args = context.args
    teams = tournament_teams.get(group_id, {})
    
    team_name = None
    player_args_start = 0
    for i in range(len(args), 0, -1):
        potential = " ".join(args[:i])
        if potential in teams:
            team_name = potential
            player_args_start = i
            break
    
    if not team_name:
        await update.message.reply_text("⚠️ Team not found!")
        return
    
    # Collect IDs to remove
    ids_to_remove = set()
    entities = update.message.entities or []
    for entity in entities:
        if entity.type == "mention":
            username = update.message.text[entity.offset+1:entity.offset+entity.length]
            try:
                cm = await context.bot.get_chat_member(group_id, f"@{username}")
                ids_to_remove.add(cm.user.id)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 5756)")
                pass
        elif entity.type == "text_mention" and entity.user:
            ids_to_remove.add(entity.user.id)
    
    for arg in context.args[player_args_start:]:
        if arg.isdigit():
            ids_to_remove.add(int(arg))
    
    team_data = tournament_teams[group_id][team_name]
    before = len(team_data["players"])
    team_data["players"] = [p for p in team_data["players"] if p["user_id"] not in ids_to_remove]
    after = len(team_data["players"])
    removed = before - after

    if removed:
        save_tour_state(group_id)  # ✅ persist immediately so a restart doesn't lose the change

    await update.message.reply_text(
        f"✅ <b>Removed {removed} player(s) from {team_name}</b>\n"
        f"📊 <b>Team size:</b> {after} players",
        parse_mode=ParseMode.HTML
    )


async def teamdelete_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Dissolve a tournament team/franchise: /teamdelete [team name]"""
    chat = update.effective_chat
    user = update.effective_user

    if chat.type == "private":
        await update.message.reply_text("Use this command in a group!")
        return

    group_id = chat.id

    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return

    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only group admins can delete teams!")
        return

    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/teamdelete [team name]</code>\nExample: <code>/teamdelete Team Alpha</code>",
            parse_mode=ParseMode.HTML
        )
        return

    args = context.args
    teams = tournament_teams.get(group_id, {})

    # Find team name (progressively longer phrases, same logic as /teamadd)
    team_name = None
    for i in range(len(args), 0, -1):
        potential = " ".join(args[:i])
        if potential in teams:
            team_name = potential
            break

    if not team_name:
        team_list = ", ".join(teams.keys()) if teams else "None"
        await update.message.reply_text(
            f"⚠️ Team not found!\nAvailable teams: {team_list}",
            parse_mode=ParseMode.HTML
        )
        return

    # Confirm if this team has already played matches (points table entry exists)
    pts_row = tournament_points.get(group_id, {}).get(team_name)
    has_history = bool(pts_row and pts_row.get("played", 0) > 0)

    del tournament_teams[group_id][team_name]

    # Remove any *unplayed* fixtures involving this team (played ones are left as history)
    fixtures = tournament_fixtures.get(group_id, [])
    tournament_fixtures[group_id] = [
        f for f in fixtures
        if f.get("result") is not None or (f.get("team1") != team_name and f.get("team2") != team_name)
    ]

    save_tour_state(group_id)  # ✅ persist immediately

    warn = ""
    if has_history:
        warn = (
            f"\n\n⚠️ <b>Note:</b> This team already had match results recorded "
            f"(P{pts_row['played']} W{pts_row['won']} L{pts_row['lost']}, NRR {pts_row.get('nrr', 0):+.2f}).\n"
            f"That record is kept in the points table. If you create a <b>new</b> team with the "
            f"<u>exact same name</u> later, it will inherit this old record — use a different name "
            f"if you want a clean slate."
        )

    await update.message.reply_text(
        f"🗑️ <b>Team Dissolved!</b>\n"
        f"─────────────────\n"
        f"🏏 <b>Team:</b> {team_name}\n"
        f"Removed from tournament + any unplayed fixtures cleared."
        f"{warn}",
        parse_mode=ParseMode.HTML
    )


def _default_team_stats():
    """Default points-table row for a team, including NRR tracking fields."""
    return {
        "played": 0, "won": 0, "lost": 0, "tied": 0, "pts": 0, "nrr": 0.0,
        "runs_for": 0.0, "overs_for": 0.0, "runs_against": 0.0, "overs_against": 0.0,
    }


def _effective_overs(team, allotted_overs: float) -> float:
    """Standard NRR rule: if a team is bowled all out before using its full quota of
    overs, the FULL allotted overs are used for run-rate purposes. Otherwise the
    actual overs faced/bowled are used."""
    actual_overs = (team.balls or 0) / 6.0
    if getattr(team, "all_out", False):
        return float(allotted_overs)
    return actual_overs


def _update_team_nrr(pts_row: dict, runs_for: float, overs_for: float, runs_against: float, overs_against: float):
    """Add this match's runs/overs into a team's running NRR totals and recompute NRR."""
    pts_row["runs_for"] = pts_row.get("runs_for", 0.0) + runs_for
    pts_row["overs_for"] = pts_row.get("overs_for", 0.0) + overs_for
    pts_row["runs_against"] = pts_row.get("runs_against", 0.0) + runs_against
    pts_row["overs_against"] = pts_row.get("overs_against", 0.0) + overs_against
    rr_for = pts_row["runs_for"] / pts_row["overs_for"] if pts_row["overs_for"] > 0 else 0.0
    rr_against = pts_row["runs_against"] / pts_row["overs_against"] if pts_row["overs_against"] > 0 else 0.0
    pts_row["nrr"] = round(rr_for - rr_against, 3)


async def record_tour_match_result(context, group_id: int, match, winner, loser):
    """Auto-capture player stats + result for a TOURNAMENT-mode match the moment it ends.
    This runs automatically when any tournament match finishes, so /tourresult becomes
    optional — points table, fixtures, NRR, and top-scorer stats (runs/wickets/sixes/fours/MVP)
    are saved right away instead of depending on an admin typing the result manually."""
    try:
        mid = getattr(match, "tournament_match_id", None)
        if mid is None or group_id not in pending_tour_match:
            return  # Not a tournament match, nothing to do

        t1 = match.team_x.name
        t2 = match.team_y.name

        player_runs, player_wkts, player_sixes, player_fours = {}, {}, {}, {}
        best_player, best_score = None, -1
        for p in match.team_x.players + match.team_y.players:
            if p.runs:
                player_runs[p.first_name] = player_runs.get(p.first_name, 0) + p.runs
            if p.wickets:
                player_wkts[p.first_name] = player_wkts.get(p.first_name, 0) + p.wickets
            if p.sixes:
                player_sixes[p.first_name] = player_sixes.get(p.first_name, 0) + p.sixes
            if p.boundaries:
                player_fours[p.first_name] = player_fours.get(p.first_name, 0) + p.boundaries
            impact = p.runs + (p.wickets * 20)
            if impact > best_score:
                best_score, best_player = impact, p.first_name

        tour_match_stats[group_id][mid] = {
            "team1": t1, "team2": t2,
            "player_runs": player_runs,
            "player_wickets": player_wkts,
            "player_sixes": player_sixes,
            "player_fours": player_fours,
            "mvp": best_player,
        }

        # Auto-update points table
        pts = tournament_points[group_id]
        for tn in [t1, t2]:
            if tn not in pts:
                pts[tn] = _default_team_stats()

        if winner is None:
            pts[t1]["played"] += 1; pts[t2]["played"] += 1
            pts[t1]["tied"] += 1; pts[t2]["tied"] += 1
            pts[t1]["pts"] += 1; pts[t2]["pts"] += 1
            result_str = "Tie"
        else:
            winner_name, loser_name = winner.name, loser.name
            pts.setdefault(winner_name, _default_team_stats())
            pts.setdefault(loser_name, _default_team_stats())
            pts[winner_name]["played"] += 1; pts[loser_name]["played"] += 1
            pts[winner_name]["won"] += 1; pts[loser_name]["lost"] += 1
            pts[winner_name]["pts"] += 2
            result_str = f"{winner_name} won"

        # ✅ Update Net Run Rate for both teams (standard "all-out = full overs" rule)
        allotted = float(getattr(match, "total_overs", 0) or 0)
        x_overs = _effective_overs(match.team_x, allotted)
        y_overs = _effective_overs(match.team_y, allotted)
        _update_team_nrr(pts[t1], match.team_x.score, x_overs, match.team_y.score, y_overs)
        _update_team_nrr(pts[t2], match.team_y.score, y_overs, match.team_x.score, x_overs)

        # Update the matching fixture + clear the pending-match session
        for fix in tournament_fixtures.get(group_id, []):
            if fix.get("match_id") == mid:
                fix["result"] = result_str
                break

        pending_tour_match.pop(group_id, None)
        save_tour_state(group_id)  # ✅ persist immediately so a crash/restart can't lose it

        try:
            await context.bot.send_message(
                group_id,
                f"🏆 <b>Tournament stats saved!</b>\n{result_str} • Points table, NRR & top-scorer stats updated automatically.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
    except Exception as e:
        logger.error(f"❌ Error auto-recording tour match result: {e}")


# ═══════════════════════════════════════════════════════════════
# MANUAL RESULT ENTRY — /addresult
# Owner + Powered users only. Flow:
# Team X → Team Y → Overs → Winner → Margin (runs text / wickets buttons)
# → per-player stats (runs/wkts/4s/6s, Skip = didn't play).
# ═══════════════════════════════════════════════════════════════

def _is_result_admin(user_id: int) -> bool:
    """Only the bot owner or 'powered' users may use /addresult."""
    return user_id == OWNER_ID or user_id in POWERED_USERS


def _mres_squad(group_id: int, team1: str, team2: str) -> List[Tuple[int, str, str]]:
    """Combined (user_id, first_name, team_name) list for both teams, pulled
    from tournament_teams — this is what lets the bot know the full playing
    pool. Whoever gets ⏭ Skipped in the stats loop is treated as 'didn't
    play' (no stats added for them at all)."""
    squad = []
    teams = tournament_teams.get(group_id, {})
    for tn in (team1, team2):
        for pd in teams.get(tn, {}).get("players", []):
            squad.append((pd["user_id"], pd.get("first_name", "Player"), tn))
    return squad


def _mres_overs_keyboard(mid) -> InlineKeyboardMarkup:
    rows = []
    for start in range(1, 21, 5):
        rows.append([styled_button(str(o), callback_data=f"mres_overs_{o}") for o in range(start, min(start + 5, 21))])
    return InlineKeyboardMarkup(rows)


def _mres_wkts_keyboard() -> InlineKeyboardMarkup:
    rows = []
    for start in range(0, 20, 5):
        rows.append([styled_button(str(w), callback_data=f"mres_wktmargin_{w}") for w in range(start, min(start + 5, 20))])
    return InlineKeyboardMarkup(rows)


def _mres_stats_prompt_text(session: Dict) -> str:
    idx = session["idx"]
    squad = session["squad"]
    uid, name, team = squad[idx]
    return (
        f"🧮 <b>Player stats</b> ({idx + 1}/{len(squad)})\n"
        f"─────────────────\n"
        f"👤 <b>{html.escape(name)}</b> ({html.escape(team)})\n\n"
        f"Reply with: <code>runs wickets sixes fours</code>\n"
        f"e.g. <code>41 0 2 3</code> for 41 runs, 0 wkts, 2 sixes, 3 fours.\n\n"
        f"Didn't play this match? Tap ⏭ Skip — no stats will be added for them."
    )


def _mres_stats_keyboard() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [styled_button("⏭ Skip (didn't play)", callback_data="mres_playerskip")],
        [styled_button("✅ Finish & Save now", callback_data="mres_playerdone")],
        [styled_button("❌ Cancel", callback_data="mres_cancel")],
    ])


async def _mres_advance_to_stats(query_or_msg, context, group_id: int, edit: bool):
    session = manual_result_sessions[group_id]
    if session["idx"] >= len(session["squad"]):
        await _mres_finalize(query_or_msg, context, group_id)
        return
    text = _mres_stats_prompt_text(session)
    kb = _mres_stats_keyboard()
    try:
        if edit:
            await query_or_msg.edit_message_text(text, reply_markup=kb, parse_mode=ParseMode.HTML)
        else:
            await query_or_msg.reply_text(text, reply_markup=kb, parse_mode=ParseMode.HTML)
    except Exception:
        await context.bot.send_message(group_id, text, reply_markup=kb, parse_mode=ParseMode.HTML)


async def _mres_finalize(query_or_msg, context, group_id: int):
    session = manual_result_sessions.pop(group_id, None)
    if not session:
        return

    t1, t2 = session["team1"], session["team2"]
    winner = session["winner"]
    margin_text = session.get("margin_text", "")
    mid = session["mid"]

    pts = tournament_points[group_id]
    for tn in (t1, t2):
        pts.setdefault(tn, _default_team_stats())

    if winner is None:
        pts[t1]["played"] += 1; pts[t2]["played"] += 1
        pts[t1]["tied"] += 1; pts[t2]["tied"] += 1
        pts[t1]["pts"] += 1; pts[t2]["pts"] += 1
        result_str = "Tie"
    else:
        loser = t2 if winner == t1 else t1
        pts[winner]["played"] += 1; pts[loser]["played"] += 1
        pts[winner]["won"] += 1; pts[loser]["lost"] += 1
        pts[winner]["pts"] += 2
        result_str = f"{winner} won" + (f" {margin_text}" if margin_text else "")

    for fix in tournament_fixtures.get(group_id, []):
        if fix.get("match_id") == mid:
            fix["result"] = result_str
            break

    player_runs, player_wkts, player_sixes, player_fours = {}, {}, {}, {}
    best_player, best_score = None, -1
    for uid, name, team in session["squad"]:
        s = session["stats"].get(uid)
        if not s:
            continue  # skipped → did not play, no stats at all
        if s["runs"]:
            player_runs[name] = player_runs.get(name, 0) + s["runs"]
        if s["wkts"]:
            player_wkts[name] = player_wkts.get(name, 0) + s["wkts"]
        if s["sixes"]:
            player_sixes[name] = player_sixes.get(name, 0) + s["sixes"]
        if s["fours"]:
            player_fours[name] = player_fours.get(name, 0) + s["fours"]
        impact = s["runs"] + (s["wkts"] * 20)
        if impact > best_score:
            best_score, best_player = impact, name

    tour_match_stats[group_id][mid] = {
        "team1": t1, "team2": t2,
        "player_runs": player_runs,
        "player_wickets": player_wkts,
        "player_sixes": player_sixes,
        "player_fours": player_fours,
        "mvp": best_player,
        "manual_entry": True,
    }

    pending_tour_match.pop(group_id, None)
    save_tour_state(group_id)

    text = (
        f"✅ <b>MANUAL RESULT SAVED!</b>\n"
        f"─────────────────\n"
        f"⚔️ <b>{t1}</b> vs <b>{t2}</b>\n"
        f"🎯 <b>Overs:</b> {session.get('overs')}\n"
        f"🏆 <b>Result:</b> {result_str}\n"
        f"👑 <b>MVP:</b> {html.escape(best_player) if best_player else '—'}\n\n"
        f"Points table, fixture result & player stats have been updated."
    )
    try:
        await query_or_msg.edit_message_text(text, parse_mode=ParseMode.HTML)
    except Exception:
        try:
            await query_or_msg.reply_text(text, parse_mode=ParseMode.HTML)
        except Exception:
            await context.bot.send_message(group_id, text, parse_mode=ParseMode.HTML)


async def addresult_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/addresult — owner/powered-only manual result + player-stats entry.
    Flow: Team X -> Team Y -> Overs -> Winner -> Margin -> player stats."""
    chat = update.effective_chat
    user = update.effective_user
    if chat.type == "private":
        await update.message.reply_text("Use this inside the tournament group.")
        return

    group_id = chat.id
    if not _is_result_admin(user.id):
        await update.message.reply_text("🚫 Only the bot owner or powered users can use this.")
        return

    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        await update.message.reply_text("⚠️ This group isn't tournament-approved.")
        return

    all_teams = list(tournament_teams.get(group_id, {}).keys())
    if len(all_teams) < 2:
        await update.message.reply_text("⚠️ Need at least 2 registered tournament teams first.")
        return

    mid = f"manual_{int(time.time())}"
    manual_result_sessions[group_id] = {
        "user_id": user.id, "mid": mid, "team1": None, "team2": None,
        "overs": None, "winner": None, "margin_text": "",
        "squad": [], "idx": 0, "stats": {}, "stage": "team_x",
    }

    kb = [[styled_button(tn, callback_data=f"mres_tx_{tn}")] for tn in all_teams]
    kb.append([styled_button("❌ Cancel", callback_data="mres_cancel")])
    await update.message.reply_text(
        "🏆 <b>Manual Result Entry</b>\n─────────────────\n🔵 Select <b>Team X</b>:",
        reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
    )


async def mres_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    user = query.from_user
    group_id = query.message.chat.id
    data = query.data

    if not _is_result_admin(user.id):
        await query.answer("🚫 Not authorized.", show_alert=True)
        return

    session = manual_result_sessions.get(group_id)
    if not session or session["user_id"] != user.id:
        if data != "mres_cancel":
            await query.answer("No active session for you here. Run /addresult again.", show_alert=True)
            return

    if data == "mres_cancel":
        manual_result_sessions.pop(group_id, None)
        await query.edit_message_text("❌ Manual result entry cancelled.")
        await query.answer()
        return

    # ── Team X ──
    if data.startswith("mres_tx_"):
        tx = data[len("mres_tx_"):]
        session["team1"] = tx
        all_teams = [t for t in tournament_teams.get(group_id, {}).keys() if t != tx]
        kb = [[styled_button(tn, callback_data=f"mres_ty_{tn}")] for tn in all_teams]
        kb.append([styled_button("❌ Cancel", callback_data="mres_cancel")])
        await query.edit_message_text(
            f"✅ Team X = <b>{html.escape(tx)}</b>\n─────────────────\n🔴 Select <b>Team Y</b>:",
            reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Team Y ──
    if data.startswith("mres_ty_"):
        ty = data[len("mres_ty_"):]
        session["team2"] = ty
        session["squad"] = _mres_squad(group_id, session["team1"], session["team2"])
        session["stage"] = "overs"
        await query.edit_message_text(
            f"✅ <b>{html.escape(session['team1'])}</b> vs <b>{html.escape(ty)}</b>\n"
            f"─────────────────\n🔢 Select number of overs:",
            reply_markup=_mres_overs_keyboard(session["mid"]), parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Overs ──
    if data.startswith("mres_overs_"):
        overs = int(data.split("_")[2])
        session["overs"] = overs
        session["stage"] = "winner"
        t1, t2 = session["team1"], session["team2"]
        kb = [
            [styled_button(t1, callback_data="mres_win_t1")],
            [styled_button(t2, callback_data="mres_win_t2")],
            [styled_button("🤝 Tie", callback_data="mres_win_tie")],
            [styled_button("❌ Cancel", callback_data="mres_cancel")],
        ]
        await query.edit_message_text(
            f"✅ <b>{overs} overs</b>\n─────────────────\n⚔️ <b>{t1}</b> vs <b>{t2}</b>\n\n🏆 Who won?",
            reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Winner ──
    if data.startswith("mres_win_"):
        choice = data.split("_")[2]
        session["winner"] = {"t1": session["team1"], "t2": session["team2"], "tie": None}[choice]
        session["stage"] = "margin_type"
        if session["winner"] is None:
            session["margin_text"] = ""
            session["stage"] = "player_stats"
            await query.answer()
            await _mres_advance_to_stats(query, context, group_id, edit=True)
            return
        kb = [
            [styled_button("🏃 By Runs", callback_data="mres_margintype_runs")],
            [styled_button("🎯 By Wickets", callback_data="mres_margintype_wkts")],
            [styled_button("⏭ Skip margin", callback_data="mres_margintype_skip")],
        ]
        await query.edit_message_text(
            f"✅ Result: <b>{session['winner']} won</b>\n\n📏 Winning margin?",
            reply_markup=InlineKeyboardMarkup(kb), parse_mode=ParseMode.HTML,
        )
        await query.answer()
        return

    # ── Margin type ──
    if data.startswith("mres_margintype_"):
        kind = data.split("_")[2]
        if kind == "skip":
            session["margin_text"] = ""
            session["stage"] = "player_stats"
            await query.answer()
            await _mres_advance_to_stats(query, context, group_id, edit=True)
        elif kind == "wkts":
            session["stage"] = "margin_wkts"
            await query.edit_message_text(
                "🎯 Select wicket margin:", reply_markup=_mres_wkts_keyboard()
            )
            await query.answer()
        else:  # runs — bigger range, ask as text
            session["stage"] = "margin_runs_text"
            await query.edit_message_text("✏️ Reply with the winning run margin, e.g. 20")
            await query.answer()
        return

    # ── Wicket margin button (0-19) ──
    if data.startswith("mres_wktmargin_"):
        w = int(data.split("_")[2])
        session["margin_text"] = f"by {w} wicket{'s' if w != 1 else ''}"
        session["stage"] = "player_stats"
        await query.answer()
        await _mres_advance_to_stats(query, context, group_id, edit=True)
        return

    if data == "mres_playerskip":
        session["idx"] += 1
        await query.answer()
        await _mres_advance_to_stats(query, context, group_id, edit=True)
        return

    if data == "mres_playerdone":
        await query.answer()
        await _mres_finalize(query, context, group_id)
        return


async def handle_manual_result_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """Call this FIRST inside handle_group_input. Returns True if the message
    was consumed as part of an /addresult session (runs margin or player stats)."""
    if update.effective_chat.type == "private" or not update.message or not update.message.text:
        return False

    group_id = update.effective_chat.id
    user = update.effective_user
    session = manual_result_sessions.get(group_id)
    if not session or session["user_id"] != user.id:
        return False

    text = update.message.text.strip()

    if session["stage"] == "margin_runs_text":
        try:
            n = int(text)
        except ValueError:
            await update.message.reply_text("⚠️ Send a number, e.g. 20")
            return True
        session["margin_text"] = f"by {n} run{'s' if n != 1 else ''}"
        session["stage"] = "player_stats"
        await _mres_advance_to_stats(update.message, context, group_id, edit=False)
        return True

    if session["stage"] == "player_stats":
        parts = text.split()
        try:
            vals = [int(p) for p in parts]
        except ValueError:
            await update.message.reply_text("⚠️ Format: runs wickets sixes fours — e.g. 41 0 2 3")
            return True
        vals += [0] * (4 - len(vals))
        runs, wkts, sixes, fours = vals[:4]
        uid = session["squad"][session["idx"]][0]
        session["stats"][uid] = {"runs": runs, "wkts": wkts, "sixes": sixes, "fours": fours}
        session["idx"] += 1
        await _mres_advance_to_stats(update.message, context, group_id, edit=False)
        return True

    return False


async def tourresult_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Record tournament match result: /tourresult [winning_team]"""
    chat = update.effective_chat
    user = update.effective_user
    group_id = chat.id
    
    if chat.type == "private":
        return
    
    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return
    
    member = await context.bot.get_chat_member(group_id, user.id)
    if member.status not in ["administrator", "creator"]:
        await update.message.reply_text("🚫 Only admins can record results!")
        return
    
    if group_id not in pending_tour_match:
        await update.message.reply_text("⚠️ No active tournament match found!")
        return
    
    if not context.args:
        await update.message.reply_text(
            "📋 Usage: <code>/tourresult [winning team name]</code>\nOr <code>/tourresult tie</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    tm = pending_tour_match[group_id]
    t1 = tm["team1"]
    t2 = tm["team2"]
    match_id = tm["match_id"]
    winner_arg = " ".join(context.args).strip().lower()
    
    pts = tournament_points[group_id]
    for tn in [t1, t2]:
        if tn not in pts:
            pts[tn] = _default_team_stats()
    
    if winner_arg == "tie":
        pts[t1]["played"] += 1
        pts[t2]["played"] += 1
        pts[t1]["tied"] += 1
        pts[t2]["tied"] += 1
        pts[t1]["pts"] += 1
        pts[t2]["pts"] += 1
        result_str = "Tie"
    else:
        # Match team name
        winner = None
        for tn in [t1, t2]:
            if tn.lower() == winner_arg or winner_arg in tn.lower():
                winner = tn
                break
        
        if not winner:
            await update.message.reply_text(f"⚠️ Team not found! Valid teams: {t1}, {t2}")
            return
        
        loser = t2 if winner == t1 else t1
        pts[winner]["played"] += 1
        pts[loser]["played"] += 1
        pts[winner]["won"] += 1
        pts[loser]["lost"] += 1
        pts[winner]["pts"] += 2
        result_str = f"{winner} won"
    
    # Update fixture
    for fix in tournament_fixtures[group_id]:
        if fix["match_id"] == match_id:
            fix["result"] = result_str
            break
    
    del pending_tour_match[group_id]

    save_tour_state(group_id)  # ✅ persist points/fixtures so restart doesn't lose them

    await update.message.reply_text(
        f"✅ <b>RESULT RECORDED!</b>\n"
        f"─────────────────\n"
        f"⚔️ <b>{t1}</b> vs <b>{t2}</b>\n"
        f"🏆 <b>Result:</b> {result_str}\n\n"
        f"Points table has been updated!",
        parse_mode=ParseMode.HTML
    )


async def tourlb_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Tournament leaderboard: /tourlb → attractive paginated image version"""
    chat = update.effective_chat
    user = update.effective_user
    group_id = chat.id

    if chat.type == "private":
        await update.message.reply_text("Use in a group!")
        return

    if group_id not in TOURNAMENT_APPROVED_GROUPS:
        return

    # Build category text
    def _pname(pid):
        """🔧 FIX: leaderboard used to show raw numeric user_ids as the name
        (setdefault froze name=str(pid) forever). Resolve the real first_name
        from user_data instead, falling back to the id only if truly unknown."""
        return user_data.get(pid, {}).get("first_name") or str(pid)

    def _pad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    def _rpad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s

    def _tourlb_text(group_id: int, metric: str = "runs") -> str:
        all_runs = {}
        all_wickets = {}
        all_sixes = {}
        all_fours = {}

        for match_id, stats in tour_match_stats.get(group_id, {}).items():
            for pid, val in stats.get("player_runs", {}).items():
                all_runs.setdefault(pid, {"name": _pname(pid), "total": 0})["total"] += val
            for pid, val in stats.get("player_wickets", {}).items():
                all_wickets.setdefault(pid, {"name": _pname(pid), "total": 0})["total"] += val
            for pid, val in stats.get("player_sixes", {}).items():
                all_sixes.setdefault(pid, {"name": _pname(pid), "total": 0})["total"] += val
            for pid, val in stats.get("player_fours", {}).items():
                all_fours.setdefault(pid, {"name": _pname(pid), "total": 0})["total"] += val

        medals = ["🥇", "🥈", "🥉", "4", "5", "6", "7", "8", "9", "10"]

        if metric == "runs":
            title, unit = "🏃 TOP RUN SCORERS", "R"
            data = sorted(all_runs.values(), key=lambda x: -x["total"])
        elif metric == "wickets":
            title, unit = "⚾ TOP WICKET TAKERS", "W"
            data = sorted(all_wickets.values(), key=lambda x: -x["total"])
        elif metric == "sixes":
            title, unit = "🚀 MOST SIXES", "6s"
            data = sorted(all_sixes.values(), key=lambda x: -x["total"])
        elif metric == "fours":
            title, unit = "4️⃣ MOST FOURS", "4s"
            data = sorted(all_fours.values(), key=lambda x: -x["total"])
        else:
            title, unit = "🏃 TOP RUN SCORERS", "R"
            data = []

        total_matches = len(tour_match_stats.get(group_id, {}))
        text = f"🏆 <b>TOURNAMENT LEADERBOARD</b>\n"
        text += f"📊 {total_matches} match(es) played\n\n"
        text += f"<b>{title}</b>\n"

        if data[:10]:
            table = f"{_pad('#', 3)}{_pad('Player', 16)}{_rpad(unit, 6)}\n" + ("─" * 25) + "\n"
            for i, d in enumerate(data[:10]):
                table += f"{_pad(medals[i], 3)}{_pad(d['name'][:15], 16)}{_rpad(d['total'], 6)}\n"
            text += f"<pre>{table}</pre>"
        else:
            text += "<i>No data yet → complete some matches!</i>"
        return text

    metric = "runs"
    text = _tourlb_text(group_id, metric)
    kb = InlineKeyboardMarkup([
        [styled_button("🏃 Runs",    callback_data=f"tourlb_{group_id}_runs"),
         styled_button("⚾ Wickets", callback_data=f"tourlb_{group_id}_wickets")],
        [styled_button("🚀 Sixes",   callback_data=f"tourlb_{group_id}_sixes"),
         styled_button("4️⃣ Fours",   callback_data=f"tourlb_{group_id}_fours")],
    ])

    # Try generate image
    try:
        img_bio = await asyncio.to_thread(generate_tour_leaderboard_image, group_id)
    except Exception:
        img_bio = None

    try:
        if img_bio:
            await update.message.reply_photo(photo=img_bio, caption=text, parse_mode=ParseMode.HTML, reply_markup=kb)
        else:
            photo = MEDIA_ASSETS.get("tournament_mode")
            await update.message.reply_photo(photo=photo, caption=text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 6530)")
        await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)


def _solo_board_render(match):
    """Builds the (text, keyboard) pair for the solo joining board."""
    count = len(match.solo_players)
    
    # Time Calc
    remaining = int(match.solo_join_end_time - time.time())
    if remaining < 0: remaining = 0
    mins, secs = divmod(remaining, 60)
    
    # Generate Host Tag
    if match.host_id and match.host_name:
        host_tag = f'<a href=\"tg://user?id={match.host_id}\">{match.host_name}</a>'
    else:
        host_tag = "Unknown"
    
    SOLO_LINEUP_SIZE = 11
    number_emojis = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]

    msg = "🏏 𝗧𝗛𝗘 𝗚𝗥𝗔𝗡𝗗 𝗠𝗔𝗧𝗖𝗛 🏏\n"
    msg += "─────────────────────────\n"
    msg += f"🏟️ 𝗛𝗼𝘀𝘁: {host_tag}\n"
    msg += f"⏳ 𝗧𝗶𝗺𝗲 𝗟𝗲𝗳𝘁: {mins:02d}:{secs:02d}\n"
    msg += f"👥 𝗣𝗹𝗮𝘆𝗲𝗿𝘀 𝗜𝗻 𝗗𝘂𝗴𝗼𝘂𝘁: {count}\n"
    msg += "─────────────────────────\n"
    msg += f"🏏 𝗟𝗜𝗡𝗘-𝗨𝗣 (𝗣𝗟𝗔𝗬𝗜𝗡𝗚 𝗫𝗜) ➔ {count}/{SOLO_LINEUP_SIZE}\n"
    msg += "┌───────────────────────\n"
    if match.solo_players:
        for i, p in enumerate(match.solo_players, 1):
            jnum = jersey_number_prefix(p.user_id)
            ptag = f'<a href=\"tg://user?id={p.user_id}\">{jnum}{p.first_name}</a>'
            crown = " 👑" if match.host_id and p.user_id == match.host_id else ""
            emoji = number_emojis[i-1] if i <= len(number_emojis) else f"{i}."
            msg += f"├ {emoji} {ptag}{crown}\n"
    else:
        msg += "├ <i>Waiting for players...</i>\n"
    msg += "└───────────────────────"
    
    # Buttons
    keyboard = [
        [styled_button("✅ Join Battle", callback_data="solo_join"),
         styled_button("🚪 Leave", callback_data="solo_leave")]
    ]
    
    # Show START button if enough players
    if count >= 2:
        keyboard.append([styled_button("🚀 START MATCH", callback_data="solo_start_game")])

    return msg, keyboard


async def bump_solo_board(context, chat_id, match):
    """Deletes and resends the solo joining board so it resurfaces at the
    bottom of the chat instead of staying buried above newer messages."""
    msg, keyboard = _solo_board_render(match)
    await refresh_game_message(context, chat_id, match, msg, InlineKeyboardMarkup(keyboard), media_key="joining")


async def update_solo_board(context, chat_id, match, _force=False):
    """
    Updates the Solo Joining List in place, IMMEDIATELY (no throttle) so
    joins/leaves show up in the group the moment someone taps a button.
    Bumping the message back to the bottom of the chat is handled
    separately (see bump_solo_board / solo_join_countdown), every 30s.
    """
    if not match.main_message_id:
        # No message yet — send the first one.
        msg, keyboard = _solo_board_render(match)
        await refresh_game_message(context, chat_id, match, msg, InlineKeyboardMarkup(keyboard), media_key="joining")
        return

    msg, keyboard = _solo_board_render(match)
    reply_markup = InlineKeyboardMarkup(keyboard)

    try:
        await context.bot.edit_message_caption(
            chat_id=chat_id,
            message_id=match.main_message_id,
            caption=msg,
            reply_markup=reply_markup,
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        error_str = str(e).lower()
        if "message is not modified" in error_str:
            return
        try:
            await context.bot.edit_message_text(
                chat_id=chat_id,
                message_id=match.main_message_id,
                text=msg,
                reply_markup=reply_markup,
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass

async def start_team_mode(query, context: ContextTypes.DEFAULT_TYPE, chat, user):
    """Initialize team mode with Fancy Image"""
    # Create new match
    match = Match(chat.id, chat.title)
    active_matches[chat.id] = match
    try:
        await notify_group_game_started(context, chat.id, chat.title)
    except Exception:
        pass
    
    # Track lobby creator — only they can force-start the match early
    match.host_id = user.id
    match.host_name = user.first_name
    
    # Set time (2 minutes)
    match.team_join_end_time = time.time() + get_gc_setting(match.group_id, "lobby_time", 120)
    
    # Buttons
    keyboard = [
        [styled_button("🧊 Join Team X", callback_data="join_team_x"),
         styled_button("🔥 Join Team Y", callback_data="join_team_y")],
        [styled_button("🚪 Leave Team", callback_data="leave_team")],
        [styled_button("🚀 Start Now (Host)", callback_data="team_start_now")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    # Fancy Text
    text = get_team_join_message(match)
    
    # Send using Master Function (With Image)
    await refresh_game_message(context, chat.id, match, text, reply_markup, media_key="joining")
    
    # Start Timer
    match.join_phase_task = asyncio.create_task(
        team_join_countdown(context, chat.id, match)
    )

def get_team_join_message(match: Match) -> str:
    """Generate Professional Joining List"""
    remaining = max(0, int(match.team_join_end_time - time.time()))
    minutes = remaining // 60
    seconds = remaining % 60
    
    total_p = len(match.team_x.players) + len(match.team_y.players)
    
    # Mode label
    mode_label = ""
    if getattr(match, "magic_ball_mode", False) or getattr(match, "game_mode", "") == "MAGICBALL":
        mode_label = "  🔮 <i>Magic Ball Mode!</i>"
    
    msg = "🏟️ <b>𝗖𝗥𝗜𝗖𝗢𝗩𝗘𝗥𝗦𝗘 𝗧𝗘𝗔𝗠 𝗔𝗥𝗘𝗡𝗔</b>\n"
    msg += "┌──────────────────\n"
    msg += f"├ ⏱️ <b>Time Remaining:</b> <code>{minutes:02d}:{seconds:02d}</code>\n"
    msg += f"├ 👥 <b>Players Joined:</b> <code>{total_p}</code>{mode_label}\n"
    msg += "└──────────────────\n\n"

    # Team X List
    msg += "❄️ <b>TEAM ALPHA (X)</b>"
    if match.team_x.captain_id:
        cap = match.team_x.get_player(match.team_x.captain_id)
        if cap:
            msg += f"  👑 <i>{cap.first_name}</i>"
    msg += "\n┌──────────────────\n"
    if match.team_x.players:
        for i, p in enumerate(match.team_x.players, 1):
            crown = "👑" if p.user_id == match.team_x.captain_id else "🔹"
            jnum = jersey_number_prefix(p.user_id)
            ptag = f'<a href=\"tg://user?id={p.user_id}\">{jnum}{html.escape(p.first_name)}</a>'
            msg += f"├ {crown} <b>{i}.</b> {ptag}\n"
    else:
        msg += "├ ⏳ <i>Waiting for players...</i>\n"
    msg += "└──────────────────\n"

    # Team Y List
    msg += "\n🔥 <b>TEAM BETA (Y)</b>"
    if match.team_y.captain_id:
        cap = match.team_y.get_player(match.team_y.captain_id)
        if cap:
            msg += f"  👑 <i>{cap.first_name}</i>"
    msg += "\n┌──────────────────\n"
    if match.team_y.players:
        for i, p in enumerate(match.team_y.players, 1):
            crown = "👑" if p.user_id == match.team_y.captain_id else "🔸"
            jnum = jersey_number_prefix(p.user_id)
            ptag = f'<a href=\"tg://user?id={p.user_id}\">{jnum}{html.escape(p.first_name)}</a>'
            msg += f"├ {crown} <b>{i}.</b> {ptag}\n"
    else:
        msg += "├ ⏳ <i>Waiting for players...</i>\n"
    msg += "└──────────────────\n"

    msg += "\n📢 <i>Tap the buttons below to lock in your squad!</i>"

    return msg


async def _build_not_approved_notice(context: ContextTypes.DEFAULT_TYPE, chat_id: int):
    """Owner + group-admins tagged notice for premium-only features (Registration/Auction/Tournament).
    Returns (text, reply_markup) — reply_markup has a direct 'Contact Owner' button."""
    owner_tag = f'<a href=\"tg://user?id={OWNER_ID}\">Owner</a>'
    admin_tags = []
    try:
        admins = await context.bot.get_chat_administrators(chat_id)
        for a in admins:
            if a.user.is_bot or a.user.id == OWNER_ID:
                continue
            admin_tags.append(f'<a href=\"tg://user?id={a.user.id}\">{html.escape(a.user.first_name)}</a>')
    except Exception:
        pass

    who = owner_tag
    if admin_tags:
        who += " or " + ", ".join(admin_tags)

    text = (
        f"👋 <b>Hey there!</b>\n"
        f"─────────────────\n\n"
        f"This group doesn't have premium authorization yet.\n\n"
        f"Please ask {who} to give me the authorization to use this feature.\n\n"
        f"─────────────────"
    )
    keyboard = InlineKeyboardMarkup([[styled_button("📩 Contact Owner", url=f"tg://user?id={OWNER_ID}")]])
    return text, keyboard


async def _is_host_or_admin(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match, user_id: int) -> bool:
    """True if the user is the lobby host OR a group admin/creator."""
    if match.host_id and user_id == match.host_id:
        return True
    try:
        member = await context.bot.get_chat_member(chat_id, user_id)
        return member.status in ("administrator", "creator")
    except Exception as e:
        logger.error(f"Admin check failed: {e}")
        return False


async def team_start_now_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🚀 Host or a group admin force-starts the team lobby early (with confirmation)."""
    query = update.callback_query
    chat_id = query.message.chat.id
    match = active_matches.get(chat_id)

    if not match or match.phase != GamePhase.TEAM_JOINING:
        await query.answer("⚠️ No active joining lobby!", show_alert=True)
        return

    if not await _is_host_or_admin(context, chat_id, match, query.from_user.id):
        await query.answer("🚫 Only the host or a group admin can force-start!", show_alert=True)
        return

    total_players = len(match.team_x.players) + len(match.team_y.players)
    if total_players < 4:
        await query.answer("⚠️ Need at least 4 players (2 per team) to start!", show_alert=True)
        return

    await query.answer()

    # Ask for explicit Yes/No confirmation before force-starting
    confirm_keyboard = InlineKeyboardMarkup([
        [styled_button("✅ Yes, Force Start", callback_data="team_start_confirm_yes"),
         styled_button("❌ No, Cancel", callback_data="team_start_confirm_no")]
    ])
    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=(f"⚠️ <b>{html.escape(query.from_user.first_name)}</b> wants to force-start the match now, "
                  f"skipping the rest of the join timer.\n\n"
                  f"👥 <b>Players:</b> <code>{total_players}</code>\n\n"
                  f"❓ Force start now?"),
            parse_mode=ParseMode.HTML,
            reply_markup=confirm_keyboard
        )
    except Exception as e:
        logger.error(f"Failed to send force-start confirmation: {e}")


async def team_start_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles Yes/No confirmation for force-starting the team lobby."""
    query = update.callback_query
    chat_id = query.message.chat.id
    match = active_matches.get(chat_id)
    choice = query.data  # "team_start_confirm_yes" or "team_start_confirm_no"

    if not match or match.phase != GamePhase.TEAM_JOINING:
        await query.answer("⚠️ This lobby is no longer active!", show_alert=True)
        try:
            await query.edit_message_text("⚠️ This confirmation has expired — the lobby is no longer active.")
        except Exception:
            pass
        return

    if not await _is_host_or_admin(context, chat_id, match, query.from_user.id):
        await query.answer("🚫 Only the host or a group admin can confirm this!", show_alert=True)
        return

    if choice == "team_start_confirm_no":
        await query.answer("❌ Force-start cancelled.")
        try:
            await query.edit_message_text("❌ <b>Force-start cancelled.</b> The lobby will continue normally.",
                                           parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return

    total_players = len(match.team_x.players) + len(match.team_y.players)
    if total_players < 4:
        await query.answer("⚠️ Need at least 4 players (2 per team) to start!", show_alert=True)
        return

    await query.answer("🚀 Starting now!")
    try:
        await query.edit_message_text("🚀 <b>Force-start confirmed!</b> Closing registration now...",
                                       parse_mode=ParseMode.HTML)
    except Exception:
        pass

    if match.join_phase_task:
        match.join_phase_task.cancel()
    await end_team_join_phase(context, chat_id, match)


async def team_join_countdown(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Countdown timer that updates the board and auto-ends the lobby when time is up."""
    try:
        warning_sent = False
        last_bump = time.time()
        while True:
            # Stop the timer if we've left the joining phase (e.g. force-started)
            if match.phase != GamePhase.TEAM_JOINING:
                break

            remaining = match.team_join_end_time - time.time()

            # 30 Seconds Warning
            if remaining <= 30 and remaining > 20 and not warning_sent:
                await context.bot.send_message(
                    group_id,
                    "⏰ <b>LAST CALL!</b> 30 seconds left to join!\n─────────────────\n👇 Tap below NOW → hurry up! 🏏",
                    parse_mode=ParseMode.HTML
                )
                warning_sent = True

            if remaining <= 0:
                await end_team_join_phase(context, group_id, match)
                break

            # Wait up to 10 seconds, but don't overshoot the deadline
            await asyncio.sleep(min(10, max(1, remaining)))

            # Re-check phase before touching the board
            if match.phase == GamePhase.TEAM_JOINING:
                # Every 30s: delete + resend so the board resurfaces at the
                # bottom of the chat (won't get buried under new messages).
                if time.time() - last_bump >= 30:
                    await bump_team_board(context, group_id, match)
                    last_bump = time.time()
                else:
                    await update_joining_board(context, group_id, match)

    except asyncio.CancelledError:
        pass
    except Exception as e:
        logger.error(f"Timer error: {e}")

async def end_team_join_phase(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """End joining phase and start Host Selection"""
    total_players = len(match.team_x.players) + len(match.team_y.players)
    
    # Min 4 Players Check
    if total_players < 4:
        await context.bot.send_message(
            chat_id=group_id,
            text="❌ <b>Match Cancelled!</b>\nYou need at least 4 players (2 per team) to start.",
            parse_mode=ParseMode.HTML
        )
        try: await context.bot.unpin_chat_message(group_id, match.main_message_id)
        except: pass
        del active_matches[group_id]
        return
    
    match.phase = GamePhase.HOST_SELECTION

    # Reset host_id — the lobby creator's host_id was only used for force-start
    # permissions during joining. Clear it now so "Become Host" actually works.
    match.host_id = None
    match.host_name = None

    keyboard = [[styled_button("🙋‍♂️ I Want to be Host", callback_data="become_host")]]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    host_text = f"🚨 <b>REGISTRATION CLOSED</b> 🚨\n"
    host_text += "─────────────────\n"
    host_text += f"👥 <b>Locked In:</b> <code>{total_players} Players</code>\n\n"
    host_text += "🎙️ <b>Lobby Host Selection:</b>\n"
    host_text += "<i>• The Host controls match settings, overs, and team edits.</i>\n"
    host_text += "<i>• Step up if you are ready to moderate this match!</i>\n\n"
    host_text += "─────────────────\n"
    host_text += "👇 <i>Tap below to claim the Host seat:</i>"

    
    # Send with Host Image and Pin
    await refresh_game_message(context, group_id, match, host_text, reply_markup, media_key="host")

# Team join/leave callback handlers
async def team_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle team join/leave with tagging alerts & Auto-Update"""
    query = update.callback_query

    chat = query.message.chat
    user = query.from_user

    if chat.id not in active_matches:
        await query.answer()
        return

    match = active_matches[chat.id]

    if match.phase != GamePhase.TEAM_JOINING:
        await query.answer("⚠️ Joining phase has ended!", show_alert=True)
        return

    # Initialize User Data
    if user.id not in user_data:
        user_data[user.id] = {
            "user_id": user.id,
            "username": user.username or "",
            "first_name": user.first_name,
            "started_at": datetime.now().isoformat(),
            "total_matches": 0
        }
        init_player_stats(user.id)
        save_data()

    user_tag = f'<a href=\"tg://user?id={user.id}\">{user.first_name}</a>'
    alert_msg = ""
    popup_msg = ""
    updated = False

    # JOIN LOGIC
    if query.data == "join_team_x":
        if not match.team_x.get_player(user.id):
            if match.team_y.get_player(user.id):
                match.team_y.remove_player(user.id)

            player = Player(user.id, user.username or "", user.first_name)
            match.team_x.add_player(player)
            alert_msg = f"✅ {user_tag} joined <b>Team X</b>!"
            popup_msg = "✅ You joined Team X!"
            updated = True
        else:
            popup_msg = "⚠️ You're already in Team X!"

    elif query.data == "join_team_y":
        if not match.team_y.get_player(user.id):
            if match.team_x.get_player(user.id):
                match.team_x.remove_player(user.id)

            player = Player(user.id, user.username or "", user.first_name)
            match.team_y.add_player(player)
            alert_msg = f"✅ {user_tag} joined <b>Team Y</b>!"
            popup_msg = "✅ You joined Team Y!"
            updated = True
        else:
            popup_msg = "⚠️ You're already in Team Y!"

    elif query.data == "leave_team":
        if match.team_x.remove_player(user.id) or match.team_y.remove_player(user.id):
            alert_msg = f"👋 {user_tag} left the team."
            popup_msg = "👋 You left the team."
            updated = True
        else:
            popup_msg = "⚠️ You're not in any team!"

    # Popup alert to the player who tapped the button (no group spam)
    await query.answer(popup_msg, show_alert=True)

    # Update the Board (Agar change hua hai)
    if updated:
        await update_joining_board(context, chat.id, match)

# Extend command (Admins only) → auto-detects Team/Solo mode
# Host selection callback
async def host_selection_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Host Selection safely with 4-20 Overs"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        return
        
    match = active_matches[chat.id]
    
    # Check if someone is already host
    if match.host_id is not None:
        await query.answer("Host already selected!", show_alert=True)
        return

    # Set Host
    match.host_id = user.id
    match.host_name = user.first_name
    match.last_activity = time.time()  # Reset timer
    
    match.phase = GamePhase.OVER_SELECTION
    
    # --- LOGIC FOR 1 TO 20 OVERS ---
    keyboard = []
    row = []
    # Loop from 1 to 20 (inclusive)
    for i in range(1, 21):
        # Add button to current row
        row.append(styled_button(f"{i}", callback_data=f"overs_{i}"))
        
        # If row has 5 buttons, add it to keyboard and start new row
        if len(row) == 5:
            keyboard.append(row)
            row = []
            
    # Add any remaining buttons
    if row:
        keyboard.append(row)
    
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    # --- FIX: Generate User Tag ---
    user_tag = get_user_tag(user)
    
    msg = f"🎙 <b>HOST: {user_tag}</b>\n"
    msg += "─────────────────\n"
    msg += "Host, please select the number of overs for this match.\n"
    msg += "Range: <b>1 to 20 Overs</b>"
    
    # Use Safe Refresh Function
    await refresh_game_message(context, chat.id, match, msg, reply_markup, media_key="host")

# Captain selection callback
async def open_fantasy_squad_window(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    🏆 Announce + open the Pre-Match Fantasy Dream III picking window.
    Anyone in the group can tap player buttons below to build a fantasy
    squad (max 3 players) during the 30-second window right after captain
    selection — the toss starts automatically once the window closes.
    """
    if match.game_mode not in ("TEAM", "TOURNAMENT"):
        return

    pool = match.team_x.players + match.team_y.players
    if len(pool) < 4:
        return  # Not enough players for a meaningful fantasy contest

    match.fantasy_squads = {}
    match.fantasy_window_open = True
    match.phase = GamePhase.FANTASY_PICK

    cap = get_fantasy_squad_cap(match)

    lines = [
        f"⚡Tap players below to pick your top {cap} squad!",
        f"📈 Points System: +1 pt/Run • +{FANTASY_PTS_PER_SIX_BONUS}/Six • +{FANTASY_PTS_PER_WICKET}/Wicket",
        f"⏳ Deadline: {FANTASY_PICK_WINDOW_SECONDS} seconds left before the Toss!",
        f"📊 Tap My Squad anytime to review your playing {cap}.",
    ]
    msg = themed("🏆 FANTASY LEAGUE ", lines, "")
    msg += "\n📢 Open for everyone in the group — Jump in now!"

    keyboard = []
    row = []
    for p in pool:
        team_emoji = "🧊" if p in match.team_x.players else "🔥"
        btn_style = "primary" if p in match.team_x.players else "danger"
        row.append(styled_button(f"{team_emoji} {p.first_name}", callback_data=f"fpick_{group_id}_{p.user_id}", style=btn_style))
        if len(row) == 2:
            keyboard.append(row)
            row = []
    if row:
        keyboard.append(row)
    keyboard.append([styled_button("📋 My Squad", callback_data=f"fmysquad_{group_id}", emoji_key="trophy")])

    try:
        fantasy_photo = MEDIA_ASSETS.get("fantasy") or MEDIA_ASSETS.get("squads")
        if fantasy_photo:
            sent = await context.bot.send_photo(
                chat_id=group_id,
                photo=fantasy_photo,
                caption=msg,
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(keyboard)
            )
        else:
            sent = await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(keyboard))
        match.fantasy_announce_message_id = sent.message_id
    except Exception as e:
        logger.error(f"Error sending fantasy squad window: {e}")

    # ⏰ Auto-close the Dream III window after the pick window and move to toss
    asyncio.create_task(fantasy_window_timeout(context, group_id, match))


async def fantasy_window_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """After the Dream III pick window expires, lock picks and start the toss."""
    await asyncio.sleep(FANTASY_PICK_WINDOW_SECONDS)

    if match.phase != GamePhase.FANTASY_PICK:
        return  # Match moved on (cancelled / ended) before the timer fired

    match.fantasy_window_open = False

    try:
        squad_count = len([s for s in match.fantasy_squads.values() if s.get("players")])
        await context.bot.send_message(
            group_id,
            f"🔒 <b>Dream III squads locked!</b> {squad_count} squad(s) submitted.\n🪙 Toss time now...",
            parse_mode=ParseMode.HTML,
        )
    except Exception as e:
        logger.error(f"Error sending fantasy lock message: {e}")

    match.phase = GamePhase.TOSS
    await start_toss(None, context, match)


async def captain_selection_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Captain Selection and move to Toss safely"""
    query = update.callback_query
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    # Check Phase
    if match.phase != GamePhase.CAPTAIN_SELECTION:
        await query.answer("Captain selection phase has ended.", show_alert=True)
        return
    
    # Logic for Team X
    if query.data == "captain_team_x":
        if not match.team_x.get_player(user.id):
            await query.answer("You must be in Team X!", show_alert=True)
            return
        if match.team_x.captain_id:
            await query.answer("Team X already has a captain.", show_alert=True)
            return
        match.team_x.captain_id = user.id
        await query.answer("You are Captain of Team X!")
    
    # Logic for Team Y
    elif query.data == "captain_team_y":
        if not match.team_y.get_player(user.id):
            await query.answer("You must be in Team Y!", show_alert=True)
            return
        if match.team_y.captain_id:
            await query.answer("Team Y already has a captain.", show_alert=True)
            return
        match.team_y.captain_id = user.id
        await query.answer("You are Captain of Team Y!")
    
    # Check if BOTH are selected
    if match.team_x.captain_id and match.team_y.captain_id:
        # ✅ FLOW FIX: Captains ke baad Fantasy Dream III (30s) → phir Toss
        try:
            await open_fantasy_squad_window(context, chat.id, match)
        except Exception as e:
            logger.error(f"Error opening fantasy squad window: {e}")

        if match.phase != GamePhase.FANTASY_PICK:
            # Not enough players for fantasy (e.g. <4) — go straight to toss
            match.phase = GamePhase.TOSS
            await start_toss(query, context, match)

    else:
        # Update Message (Show who is selected)
        captain_x = match.team_x.get_player(match.team_x.captain_id)
        captain_y = match.team_y.get_player(match.team_y.captain_id)
        
        cap_x_name = captain_x.first_name if captain_x else "Not Selected"
        cap_y_name = captain_y.first_name if captain_y else "Not Selected"
        
        keyboard = [
            [styled_button("Become Captain - Team X", callback_data="captain_team_x", emoji_key="captain")],
            [styled_button("Become Captain - Team Y", callback_data="captain_team_y", emoji_key="captain")]
        ]
        reply_markup = InlineKeyboardMarkup(keyboard)
        
        msg = "🧢 <b>CAPTAIN SELECTION</b>\n"
        msg += "─────────────────\n"
        msg += f"🧊 <b>Team X:</b> {cap_x_name}\n"
        msg += f"🔥 <b>Team Y:</b> {cap_y_name}\n\n"
        msg += "<i>Waiting for both captains...</i>"
        
        # ✅ FIX: Use refresh_game_message instead of risky edits
        await refresh_game_message(context, chat.id, match, msg, reply_markup, media_key="squads")

async def start_team_edit_phase(query, context: ContextTypes.DEFAULT_TYPE, match: Match):
    """Start team edit phase with Safety Checks"""
    match.phase = GamePhase.TEAM_EDIT
    
    # Safe Host Fetch
    host = match.team_x.get_player(match.host_id) or match.team_y.get_player(match.host_id)
    host_name = host.first_name if host else "Unknown"
    
    # Safe Captain Fetch
    captain_x = match.team_x.get_player(match.team_x.captain_id)
    captain_y = match.team_y.get_player(match.team_y.captain_id)
    
    cap_x_name = captain_x.first_name if captain_x else "Not Selected"
    cap_y_name = captain_y.first_name if captain_y else "Not Selected"
    
    keyboard = [
        [styled_button("Edit Team X", callback_data="edit_team_x")],
        [styled_button("Edit Team Y", callback_data="edit_team_y")],
        [styled_button("✅ Done - Proceed", callback_data="team_edit_done")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    edit_text = "⚙️ <b>LOBBY MANAGEMENT & TEAM EDITING</b>\n"
    edit_text += "─────────────────\n"
    edit_text += f"🎙️ <b>Host:</b> {host_name}\n"
    edit_text += f"🧊 <b>Team X Captain:</b> <code>{cap_x_name}</code>\n"
    edit_text += f"🔥 <b>Team Y Captain:</b> <code>{cap_y_name}</code>\n"
    edit_text += "─────────────────\n\n"
    
    edit_text += "🧊 <b>TEAM X SQUAD:</b>\n"
    edit_text += "──────────────────────\n"
    for i, player in enumerate(match.team_x.players, 1):
        role = " 👑" if player.user_id == match.team_x.captain_id else "🔹"
        edit_text += f"{role} <b>{i}.</b> {player.first_name}\n"
    
    edit_text += "\n🔥 <b>TEAM Y SQUAD:</b>\n"
    edit_text += "──────────────────────\n"
    for i, player in enumerate(match.team_y.players, 1):
        role = " 👑" if player.user_id == match.team_y.captain_id else "🔸"
        edit_text += f"{role} <b>{i}.</b> {player.first_name}\n"
    
    edit_text += "\n─────────────────\n"
    edit_text += "🛠️ <b>Host Admin Panel:</b>\n"
    edit_text += "• Reply to a user with <code>/add</code> to recruit them.\n"
    edit_text += "• Reply to a user with <code>/remove</code> to bench them.\n"
    edit_text += "• Tap <b>Done</b> below when squads are balanced and ready!"

    
    # Use Master Function (Corrected Call)
    chat_id = query.message.chat.id
    await refresh_game_message(context, chat_id, match, edit_text, reply_markup=reply_markup, media_key="squads")


# ═══════════════════════════════════════════════════════════════
# 🆕 MID-GAME /join — request to join a match that's already running
# ═══════════════════════════════════════════════════════════════
async def join_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    🙋 Mid-game join request.
    Works while a TEAM or SOLO match is already in progress. Sends a request
    to the host, tagging them, with buttons to accept into Team X / Team Y
    (or just Accept for solo) or Reject. Spam-proofed: a user can only send
    one pending /join request per match — repeats are silently ignored.
    """
    chat = update.effective_chat
    user = update.effective_user

    if chat.id not in active_matches:
        await update.message.reply_text("⚠️ No active match here to join.")
        return

    match = active_matches[chat.id]

    if match.phase not in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SOLO_MATCH, GamePhase.SUPER_OVER):
        await update.message.reply_text("⚠️ No match is currently in progress to join.")
        return

    # Already playing?
    if match.game_mode == "TEAM":
        if match.team_x.get_player(user.id) or match.team_y.get_player(user.id):
            await update.message.reply_text("🏏 You're already in this match!")
            return
    else:
        if any(p.user_id == user.id for p in match.solo_players):
            await update.message.reply_text("🏏 You're already in this match!")
            return

    # 🔁 One request per user per match — ignore repeat /join spam
    if user.id in match.mid_game_join_requests:
        return

    match.mid_game_join_requests.add(user.id)

    if not match.host_id:
        await update.message.reply_text("⚠️ This match has no host to approve join requests.")
        return

    host_tag = get_user_tag_by_id(match.host_id) if "get_user_tag_by_id" in globals() else f'<a href="tg://user?id={match.host_id}">Host</a>'
    requester_tag = get_user_tag(user)

    if match.game_mode == "TEAM":
        keyboard = [
            [
                styled_button("🧊 Team X", callback_data=f"midjoin_x_{user.id}"),
                styled_button("🔥 Team Y", callback_data=f"midjoin_y_{user.id}")
            ],
            [styled_button("❌ Reject", callback_data=f"midjoin_reject_{user.id}")]
        ]
    else:
        keyboard = [
            [styled_button("✅ Accept", callback_data=f"midjoin_solo_{user.id}")],
            [styled_button("❌ Reject", callback_data=f"midjoin_reject_{user.id}")]
        ]

    msg = (
        f"🙋 <b>Join Request</b>\n"
        f"─────────────────\n"
        f"👤 {requester_tag} wants to join the match!\n\n"
        f"🧢 {host_tag}, please respond:"
    )

    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(keyboard))


async def mid_game_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handles Team X / Team Y / Solo Accept / Reject buttons on a mid-game join request."""
    query = update.callback_query
    data = query.data  # midjoin_x_<uid> | midjoin_y_<uid> | midjoin_solo_<uid> | midjoin_reject_<uid>
    chat = query.message.chat

    if chat.id not in active_matches:
        await query.answer("⚠️ Match no longer active.", show_alert=True)
        return

    match = active_matches[chat.id]

    # Only the host can decide
    if query.from_user.id != match.host_id:
        await query.answer("🚫 Only the host can respond to this!", show_alert=True)
        return

    parts = data.split("_")
    action = parts[1]  # x / y / solo / reject
    target_id = int(parts[2])

    await query.answer()

    try:
        target_chat = await context.bot.get_chat(target_id)
        target_name = target_chat.first_name
        target_username = target_chat.username or ""
    except Exception:
        target_name = user_data.get(target_id, {}).get("first_name", "Player")
        target_username = user_data.get(target_id, {}).get("username", "")

    if action == "reject":
        await query.edit_message_text(
            f"❌ <b>{target_name}</b>'s join request was rejected by the host.",
            parse_mode=ParseMode.HTML
        )
        return

    # Double-check they haven't already joined by some other route
    already_in = False
    if match.game_mode == "TEAM":
        already_in = bool(match.team_x.get_player(target_id) or match.team_y.get_player(target_id))
    else:
        already_in = any(p.user_id == target_id for p in match.solo_players)

    if already_in:
        await query.edit_message_text(f"ℹ️ <b>{target_name}</b> is already in the match.", parse_mode=ParseMode.HTML)
        return

    new_player = Player(target_id, target_username, target_name)

    if action == "x":
        match.team_x.add_player(new_player)
        team_label = "🧊 Team X"
        joined_team = match.team_x
    elif action == "y":
        match.team_y.add_player(new_player)
        team_label = "🔥 Team Y"
        joined_team = match.team_y
    elif action == "solo":
        match.solo_players.append(new_player)
        team_label = "the match"
        joined_team = None
    else:
        return

    # 🕐 Tell them exactly when they'll actually get to play, instead of a vague
    # "welcome" — this was ambiguous before (mid-innings vs next innings).
    timing_note = ""
    if joined_team is not None:
        if joined_team is match.current_batting_team:
            timing_note = (
                "\n🏏 You've been added to the <b>end of the batting order</b> — "
                "you'll come in once the players ahead of you are out, still <b>this innings</b>."
            )
        elif joined_team is match.current_bowling_team:
            timing_note = (
                "\n⚾ You've joined the <b>bowling squad</b> — you'll be eligible to bowl "
                "from the <b>next over</b> onward."
            )
        else:
            timing_note = "\n📋 You've been added to the squad and will play from the <b>next innings</b>."

    await query.edit_message_text(
        f"✅ <b>{target_name}</b> has joined {team_label}! Welcome aboard 🏏{timing_note}",
        parse_mode=ParseMode.HTML
    )



# Add/Remove player commands (Host only)
async def add_player_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ BULK ADD: Add multiple players at once
    Usage:
    - Reply: /add
    - Multiple: /add @user1 @user2 @user3
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_matches:
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TEAM_EDIT:
        await update.message.reply_text("⚠️ Team editing inactive.")
        return
    
    # Check if Host
    if user.id != match.host_id:
        await update.message.reply_text("⚠️ Only Host can add.")
        return
    
    # Check if mode is set
    if not match.editing_team:
        await update.message.reply_text("⚠️ Please click 'Edit Team X' or 'Edit Team Y' button first!")
        return
    
    target_users = []  # List of user objects to add
    
    # Method 1: Reply to message
    if update.message.reply_to_message:
        target_users.append(update.message.reply_to_message.from_user)
    
    # Method 2: Parse mentions and IDs from command
    if update.message.entities or context.args:
        # Extract all mentions
        if update.message.entities:
            for entity in update.message.entities:
                if entity.type == "mention":
                    username = update.message.text[entity.offset:entity.offset + entity.length].replace("@", "")
                    # Find in user_data
                    for uid, data in user_data.items():
                        if data.get("username", "").lower() == username.lower():
                            try:
                                target_user = await context.bot.get_chat(uid)
                                target_users.append(target_user)
                            except Exception as e:
                                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 7564)")
                                pass
                            break
                elif entity.type == "text_mention":
                    target_users.append(entity.user)
        
        # Extract all User IDs from arguments
        if context.args:
            for arg in context.args:
                if arg.isdigit():
                    try:
                        user_id = int(arg)
                        target_user = await context.bot.get_chat(user_id)
                        target_users.append(target_user)
                    except Exception as e:
                        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 7578)")
                        pass
    
    if not target_users:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b>\n"
            "Reply: <code>/add</code>\n"
            "Single: <code>/add @username</code>\n"
            "Multiple: <code>/add @user1 @user2 @user3</code>\n"
            "ID: <code>/add 123456789</code>\n"
            "Mixed: <code>/add @user1 123456 @user2</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Determine which team to add to
    if match.editing_team == "X":
        team = match.team_x
        t_name = "Team X"
    else:
        team = match.team_y
        t_name = "Team Y"
    
    # Process each user
    added_users = []
    skipped_users = []
    failed_users = []
    not_started_users = []
    
    for target_user in target_users:
        try:
            # Check duplicate
            if match.team_x.get_player(target_user.id) or match.team_y.get_player(target_user.id):
                skipped_users.append(target_user.first_name)
                continue
            
            # ✅ Check if player has started the bot
            started = await check_user_started_bot(context.bot, target_user.id)
            if not started:
                not_started_users.append(target_user.first_name)
                # Still add but flag below

            # Initialize if new
            if target_user.id not in user_data:
                user_data[target_user.id] = {
                    "user_id": target_user.id,
                    "username": target_user.username or "",
                    "first_name": target_user.first_name,
                    "started_at": datetime.now().isoformat(),
                    "total_matches": 0
                }
                init_player_stats(target_user.id)
                save_data()
            
            # Add Player
            p = Player(target_user.id, target_user.username or "", target_user.first_name)
            team.add_player(p)
            added_users.append(get_user_tag(target_user))
            
        except Exception as e:
            logger.error(f"Failed to add {target_user.id}: {e}")
            failed_users.append(target_user.first_name if hasattr(target_user, 'first_name') else str(target_user.id))
    
    # Build response message
    bot_username = context.bot.username
    msg = f"📊 <b>ADD RESULT - {t_name}</b>\n"
    msg += "────────────────────\n"
    
    if added_users:
        msg += f"✅ <b>Added ({len(added_users)}):</b>\n"
        for user_tag in added_users:
            msg += f"  • {user_tag}\n"
        msg += "\n"
    
    if skipped_users:
        msg += f"⚠️ <b>Skipped ({len(skipped_users)}):</b>\n"
        for name in skipped_users:
            msg += f"  • {name} (Already in a team)\n"
        msg += "\n"
    
    if failed_users:
        msg += f"❌ <b>Failed ({len(failed_users)}):</b>\n"
        for name in failed_users:
            msg += f"  • {name} (Error fetching user)\n"
        msg += "\n"
    
    if not_started_users:
        msg += (
            f"⚠️ <b>Bot not started ({len(not_started_users)}):</b>\n"
        )
        for name in not_started_users:
            msg += f"  • {name}\n"
        msg += (
            f"👉 Ask them to start: <a href='https://t.me/{bot_username}'>@{bot_username}</a>\n"
            f"<i>They can't receive bowl/bat DMs until they do!</i>\n\n"
        )
    
    msg += "────────────────────\n"
    msg += f"📈 <b>Total {t_name} Players:</b> {len(team.players)}"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
    
    # Update team edit board
    await update_team_edit_message(context, chat.id, match)

async def remove_player_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ BULK REMOVE: Remove multiple players at once
    Usage:
    - Reply: /remove
    - Username: /remove @username
    - Multiple: /remove @user1 @user2 @user3
    - ID: /remove 123456789
    - Serial: /remove 1 2 3 4
    - Mixed: /remove @user1 2 @user2 123456
    """
    chat = update.effective_chat
    user = update.effective_user
    
    if chat.id not in active_matches:
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TEAM_EDIT:
        return
    
    if user.id != match.host_id:
        await update.message.reply_text("⚠️ Only Host can remove players.")
        return
    
    if not match.editing_team:
        await update.message.reply_text("⚠️ First Click on 'Edit Team X' or 'Edit Team Y' button")
        return
    
    target_user_ids = []  # List of user IDs to remove
    
    # Get current team
    if match.editing_team == "X":
        team = match.team_x
        team_name = "Team X"
    else:
        team = match.team_y
        team_name = "Team Y"
    
    # Method 1: Reply to message
    if update.message.reply_to_message:
        target_user_ids.append(update.message.reply_to_message.from_user.id)
    
    # Method 2: Parse mentions, IDs, and serials from command
    if update.message.entities or context.args:
        # Extract all mentions
        if update.message.entities:
            for entity in update.message.entities:
                if entity.type == "mention":
                    username = update.message.text[entity.offset:entity.offset + entity.length].replace("@", "")
                    # Find in user_data
                    for uid, data in user_data.items():
                        if data.get("username", "").lower() == username.lower():
                            target_user_ids.append(uid)
                            break
                elif entity.type == "text_mention":
                    target_user_ids.append(entity.user.id)
        
        # Extract all IDs and Serials from arguments
        if context.args:
            for arg in context.args:
                if arg.isdigit():
                    num = int(arg)
                    
                    # Check if it's a serial number (1-20 range typically)
                    if 1 <= num <= len(team.players):
                        target_player = team.get_player_by_serial(num)
                        if target_player:
                            target_user_ids.append(target_player.user_id)
                    else:
                        # Treat as User ID
                        target_user_ids.append(num)
    
    if not target_user_ids:
        await update.message.reply_text(
            "⚠️ <b>Usage:</b>\n"
            "Reply: <code>/remove</code>\n"
            "Single: <code>/remove @username</code>\n"
            "Multiple: <code>/remove @user1 @user2 @user3</code>\n"
            "ID: <code>/remove 123456789</code>\n"
            "Serial: <code>/remove 1 2 3</code>\n"
            "Mixed: <code>/remove @user1 2 123456</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Remove duplicates from target list
    target_user_ids = list(set(target_user_ids))
    
    # Process each user
    removed_users = []
    not_found_users = []
    
    for target_id in target_user_ids:
        # Get player name before removing
        player = team.get_player(target_id)
        if player:
            player_name = player.first_name
        else:
            # Try to get name from user_data
            player_name = user_data.get(target_id, {}).get("first_name", f"User {target_id}")
        
        # Try to remove
        if team.remove_player(target_id):
            removed_users.append(player_name)
        else:
            not_found_users.append(player_name)
    
    # Build response message
    msg = f"📊 <b>REMOVE RESULT - {team_name}</b>\n"
    msg += "────────────────────\n"
    if removed_users:
        msg += f"✅ <b>Removed ({len(removed_users)}):</b>\n"
        for name in removed_users:
            msg += f"  • {name}\n"
        msg += "\n"
    
    if not_found_users:
        msg += f"⚠️ <b>Not Found ({len(not_found_users)}):</b>\n"
        for name in not_found_users:
            msg += f"  • {name} (Not in {team_name})\n"
        msg += "\n"
    msg += "────────────────────\n"
    msg += f"📈 <b>Remaining {team_name} Players:</b> {len(team.players)}"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
    
    # Update team edit board
    await update_team_edit_message(context, chat.id, match)



# Team edit done callback
async def team_edit_done_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Finish Team Edit and start Captain Selection"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches: return
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TEAM_EDIT:
        await query.answer("Team edit phase has ended.", show_alert=True)
        return
    
    if user.id != match.host_id:
        await query.answer("Only the Host can proceed.", show_alert=True)
        return
    
    # Validate teams
    if len(match.team_x.players) == 0 or len(match.team_y.players) == 0:
        await query.answer("Both teams need at least one player.", show_alert=True)
        return
    
    # ✅ FLOW FIX: Team Edit ke baad ab Captain Selection aayega
    match.phase = GamePhase.CAPTAIN_SELECTION
    
    # Prepare Captain Selection Message
    captain_x = match.team_x.get_player(match.team_x.captain_id)
    captain_y = match.team_y.get_player(match.team_y.captain_id)
    
    cap_x_name = captain_x.first_name if captain_x else "Not Selected"
    cap_y_name = captain_y.first_name if captain_y else "Not Selected"
    
    keyboard = [
        [styled_button("Become Captain - Team X", callback_data="captain_team_x")],
        [styled_button("Become Captain - Team Y", callback_data="captain_team_y")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    msg = "🧢 <b>CAPTAIN SELECTION</b>\n"
    msg += "─────────────────\n"
    msg += f"🧊 <b>Team X:</b> {cap_x_name}\n"
    msg += f"🔥 <b>Team Y:</b> {cap_y_name}\n\n"
    msg += "<i>Click below to lead your team!</i>"
    
    # Update Board (Using Refresh function to be safe)
    await refresh_game_message(context, chat.id, match, msg, reply_markup, media_key="squads")

# Over selection callback
async def over_selection_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle over selection and move to Team Edit"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match found.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.OVER_SELECTION:
        await query.answer("Over selection phase has ended.", show_alert=True)
        return
    
    if user.id != match.host_id:
        await query.answer("Only the Host can select overs.", show_alert=True)
        return
    
    # --- LOGIC ---
    try:
        data_parts = query.data.split("_")
        if len(data_parts) != 2: return
        overs_selected = int(data_parts[1])
        
        if 1 <= overs_selected <= 20:
            match.total_overs = overs_selected
            
            # ✅ FLOW FIX: Overs ke baad ab Team Edit Mode aayega
            match.phase = GamePhase.TEAM_EDIT
            await start_team_edit_phase(query, context, match)
            
        else:
            await query.answer("Overs must be between 1 and 20.", show_alert=True)
    except ValueError:
        await query.answer("Invalid format.", show_alert=True)

async def start_toss(query, context: ContextTypes.DEFAULT_TYPE, match: Match):
    """Start the toss phase safely"""
    # Try to fetch Team X Captain safely
    captain_x = match.team_x.get_player(match.team_x.captain_id)
    cap_x_name = captain_x.first_name if captain_x else "Team X Captain"
    
    keyboard = [
        [styled_button("🪙 Heads", callback_data="toss_heads")],
        [styled_button("🪙 Tails", callback_data="toss_tails")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    toss_text = f"╭━━ 🪙 TOSS TIME ━━━━━━🏏\n"
    toss_text += f"┃ 🏏 Format: {match.total_overs} Overs\n"
    toss_text += f"┃ ⏱ Timer: 30 seconds to decide\n"
    toss_text += f"┃\n"
    toss_text += f"┃ 👑 {cap_x_name} → it's your call!\n"
    toss_text += f"┃ ⚙ Choose Heads or Tails below:\n"
    toss_text += f"╰━━━━━━━━"
    
    # ✅ FIX: Always use refresh_game_message to switch images safely
    chat_id = match.group_id
    await refresh_game_message(context, chat_id, match, toss_text, reply_markup, media_key="toss")

# Toss callback
async def toss_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle toss selection safely"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match found.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TOSS:
        await query.answer("Toss phase has ended.", show_alert=True)
        return
    
    # Only Team X captain can call toss
    if user.id != match.team_x.captain_id:
        await query.answer("Only Team X Captain can call the toss.", show_alert=True)
        return
    
    # Determine toss result
    toss_result = random.choice(["heads", "tails"])
    captain_call = "heads" if query.data == "toss_heads" else "tails"
    
    if toss_result == captain_call:
        match.toss_winner = match.team_x
        winner_captain = match.team_x.get_player(match.team_x.captain_id)
    else:
        match.toss_winner = match.team_y
        winner_captain = match.team_y.get_player(match.team_y.captain_id)
    
    # Ask winner to choose bat or bowl
    keyboard = [
        [styled_button("🏏 Bat First", callback_data="toss_decision_bat")],
        [styled_button("⚾ Bowl First", callback_data="toss_decision_bowl")]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    decision_text = f"╭━━ 🪙 TOSS OUTCOME ━━━━━━🏆\n"
    decision_text += f"┃ 🎉 {match.toss_winner.name} won the toss!\n"
    decision_text += f"┃ 🟡 Landed on: {toss_result.upper()}\n"
    decision_text += f"┃\n"
    decision_text += f"┃ 👑 Captain {winner_captain.first_name}, choose!\n"
    decision_text += f"┃ ⏱ Decision Time: 30 seconds\n"
    decision_text += f"╰━━━━━━━━"

    
    # ✅ FIX: Use refresh_game_message instead of edit_message_text
    await refresh_game_message(context, chat.id, match, decision_text, reply_markup, media_key="toss")
    
    # Set timeout for decision
    asyncio.create_task(toss_decision_timeout(context, chat.id, match))

async def toss_decision_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle toss decision timeout"""
    await asyncio.sleep(30)
    
    if match.phase != GamePhase.TOSS:
        return
    
    # Auto select bat if no decision made
    match.batting_first = match.toss_winner
    match.bowling_first = match.get_other_team(match.toss_winner)
    
    await start_match(context, group_id, match, auto_decision=True)

# Toss decision callback
async def toss_decision_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle bat/bowl decision"""
    query = update.callback_query
    await query.answer()
    
    chat = query.message.chat
    user = query.from_user
    
    if chat.id not in active_matches:
        await query.answer("No active match found.", show_alert=True)
        return
    
    match = active_matches[chat.id]
    
    if match.phase != GamePhase.TOSS:
        await query.answer("Toss phase has ended.", show_alert=True)
        return
    
    # Only toss winner captain can decide
    winner_captain = match.get_captain(match.toss_winner)
    if user.id != winner_captain.user_id:
        await query.answer("Only the toss winner captain can decide.", show_alert=True)
        return
    
    if query.data == "toss_decision_bat":
        match.batting_first = match.toss_winner
        match.bowling_first = match.get_other_team(match.toss_winner)
    else:
        match.bowling_first = match.toss_winner
        match.batting_first = match.get_other_team(match.toss_winner)
    
    await start_match(context, chat.id, match, auto_decision=False)

async def start_match(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, auto_decision: bool):
    """Start the actual match with prediction poll - FIXED WORKFLOW"""
    match.phase = GamePhase.MATCH_IN_PROGRESS
    match.current_batting_team = match.batting_first
    match.current_bowling_team = match.bowling_first
    match.innings = 1
    match.current_batting_team.innings_start_squad_size = len(match.current_batting_team.players)
    match.fantasy_window_open = False
    
    # ✅ CRITICAL: Reset Batsmen & Bowler indices to None (Fresh Start)
    match.current_batting_team.current_batsman_idx = None
    match.current_batting_team.current_non_striker_idx = None
    match.current_bowling_team.current_bowler_idx = None
    
    # ✅ Enable Waiting Flags
    match.waiting_for_batsman = True
    match.waiting_for_bowler = False 

    # Cleanup the Toss Board
    if match.main_message_id:
        try:
            await context.bot.unpin_chat_message(chat_id=group_id, message_id=match.main_message_id)
        except: pass

    # 🔕 "MATCH HAS BEGUN" text message removed per request — go straight to the prediction poll.
    # ✅ CREATE PREDICTION POLL
    await create_prediction_poll(context, group_id, match)
    
    # Wait 3 seconds for effect
    await asyncio.sleep(3)
    
    # ✅ REQUEST STRIKER ONLY (Step 1)
    captain = match.get_captain(match.current_batting_team)
    if not captain:
        await context.bot.send_message(group_id, "⚠️ No captain found!", parse_mode=ParseMode.HTML)
        return
    
    captain_tag = get_user_tag(captain)
    
    opener_lines = [
        f"{captain_tag}, select your opening batsman:",
        f"Use <code>/batting [number]</code> to select.",
        f"Squad Pool: {len(match.current_batting_team.players)} players available",
    ]
    msg = themed("SELECT OPENING BATSMAN", opener_lines, "")

    
    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
    
    # Start selection timer
    match.batsman_selection_time = time.time()
    match.batsman_selection_task = asyncio.create_task(
        batsman_selection_timeout(context, group_id, match)
    )

async def request_batsman_selection(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match):
    """Prompt captain for new batsman after wicket"""
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if is_match_stale(chat_id, match):
        logger.info("⛔ request_batsman_selection aborted — match already ended.")
        return

    # ── Check batting queue first ──
    bat_team = match.current_batting_team
    queued_idx = _pop_next_batsman(chat_id, bat_team)
    if queued_idx is not None:
        bat_team.current_batsman_idx = queued_idx
        match.waiting_for_batsman = False
        queued_player = bat_team.players[queued_idx]
        player_tag = get_user_tag(queued_player)
        await context.bot.send_message(
            chat_id,
            f"🏏 <b>NEXT BATSMAN (from queue):</b> {player_tag} walks in!",
            parse_mode=ParseMode.HTML
        )
        logger.info(f"✅ Auto-selected queued batsman: {queued_player.first_name}")
        await asyncio.sleep(1)
        if match.current_bowling_team.current_bowler_idx is not None:
            await execute_ball(context, chat_id, match)
        return

    captain = match.get_captain(bat_team)
    if not captain:
        await context.bot.send_message(
            chat_id,
            f"⚠️ No batting captain set! 👑 Host (<code>{match.host_id}</code>) can send <code>/batting [number]</code> to continue.",
            parse_mode=ParseMode.HTML
        )
        return

    captain_tag = get_user_tag(captain)
    
    # Count available batsmen for display
    available_batsmen_count = len([
        p for i, p in enumerate(bat_team.players)
        if i not in bat_team.out_players_indices
        and i != bat_team.current_non_striker_idx
        and i != bat_team.current_batsman_idx
    ])
    
    bat_msg_lines = [
        f"🏏 {captain_tag} ➔ Send in your next batsman!",
        f"⚙ Use: <code>/batting [number]</code>",
        f"🛟 Host can also send this if the captain's away",
    ]
    msg = themed("SELECT BATSMAN", bat_msg_lines, "🏏")
    
    await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
    
    # Start 30s timer for selection
    match.batsman_selection_time = time.time() + 30
    match.batsman_selection_task = asyncio.create_task(
        selection_timer(context, chat_id, match, "batsman", captain.first_name)
    )

async def selection_timer(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match, selection_type: str, name: str):
    """Timeout for batsman/bowler selection (30s)"""
    await asyncio.sleep(30)
    if (selection_type == "batsman" and match.waiting_for_batsman and 
        time.time() >= match.batsman_selection_time) or \
       (selection_type == "bowler" and match.waiting_for_bowler and 
        time.time() >= match.bowler_selection_time):
        msg = f"⏰ <b>{name}</b> timed out on {selection_type} selection! Random selected."
        await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        await auto_select_player(context, chat_id, match, selection_type)

async def auto_select_player(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match, selection_type: str):
    """Randomly select player on timeout"""
    if selection_type == "batsman":
        team = match.current_batting_team
        available = [p for idx, p in enumerate(team.players) if idx not in team.out_players_indices and 
                     idx != team.current_batsman_idx and idx != team.current_non_striker_idx]
        if available:
            random_idx = random.choice([i for i in range(len(team.players)) if i not in team.out_players_indices and 
                                        i != team.current_batsman_idx and i != team.current_non_striker_idx])
            team.current_batsman_idx = random_idx  # New striker
            match.waiting_for_batsman = False
            await resume_after_selection(context, chat_id, match)
    elif selection_type == "bowler":
        team = match.current_bowling_team
        available = team.get_available_bowlers()
        if available:
            new_bowler = random.choice(available)
            team.current_bowler_idx = team.players.index(new_bowler)
            team.bowler_history.append(team.current_bowler_idx)
            match.waiting_for_bowler = False
            await execute_ball(context, chat_id, match)  # Resume next ball

async def resume_after_selection(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match):
    """Resume game after batsman selection (e.g., next ball)"""
    # Cancel timer
    if match.batsman_selection_task:
        match.batsman_selection_task.cancel()
    match.waiting_for_batsman = False
    
    # If mid-over, bowler already set — just resume the next ball
    if match.current_bowling_team.current_bowler_idx is not None:
        await execute_ball(context, chat_id, match)
    else:
        # Edge: Start over or something→log
        logger.warning("Resume called without bowler")

async def batting_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    ✅ COMPLETE BATTING COMMAND - FIXED: Proper flow after selection
    """
    chat = update.effective_chat
    user = update.effective_user
    
    logger.info(f"🏏 /batting command from {user.first_name} (ID: {user.id})")
    
    if chat.id not in active_matches:
        logger.warning(f"⚠️ No active match in chat {chat.id}")
        return
    
    match = active_matches[chat.id]

    # 🏏 Super Over uses its own batting lineup selection too, so allow that phase here —
    # previously only MATCH_IN_PROGRESS was accepted, which made /batting wrongly say
    # "Match is not in progress" during a Super Over.
    if match.phase not in (GamePhase.MATCH_IN_PROGRESS, GamePhase.SUPER_OVER):
        logger.warning(f"⚠️ Match not in progress, phase={match.phase}")
        await update.message.reply_text("⚠️ Match is not in progress!")
        return

    bat_team = match.current_batting_team
    
    # Captain OR host can select → silently reject & delete everyone else's messages
    is_captain = bool(bat_team.captain_id and user.id == bat_team.captain_id)
    is_host = (user.id == match.host_id)
    if not is_captain and not is_host:
        logger.warning(f"👮‍♂️ User {user.first_name} is not captain or host")
        try:
            await update.message.delete()
        except Exception:
            pass
        return

    if not context.args:
        await update.message.reply_text("ℹ️ <b>Usage:</b> <code>/batting [serial_number]</code>", parse_mode=ParseMode.HTML)
        return
    
    try:
        serial = int(context.args[0])
        logger.info(f"🔢 Serial number: {serial}")
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 8240)")
        await update.message.reply_text("❌ Invalid number.")
        return

    player = bat_team.get_player_by_serial(serial)
    if not player:
        logger.warning(f"🚫 Player #{serial} not found")
        await update.message.reply_text(f"🚫 Player #{serial} not found.")
        return
    
    logger.info(f"👤 Player selected: {player.first_name} (ID: {player.user_id})")
    
    if player.is_out:
        logger.warning(f"💀 Player {player.first_name} is already OUT")
        await update.message.reply_text(f"💀 {player.first_name} is already OUT!")
        return
    
    player_idx = serial - 1
    
    # Check duplicates
    if player_idx == bat_team.current_batsman_idx or player_idx == bat_team.current_non_striker_idx:
        logger.warning(f"🛑 Player {player.first_name} already on crease")
        await update.message.reply_text(f"🛑 {player.first_name} is already on the crease!")
        return

    # ========================================
    # 🎯 CASE 1: SELECTING STRIKER (Opening)
    # ========================================
    if bat_team.current_batsman_idx is None and bat_team.current_non_striker_idx is None:
        logger.info("🎯 CASE 1: Selecting STRIKER (Opening)")
        bat_team.current_batsman_idx = player_idx
        
        await update.message.reply_text(
            f"✅ <b>Hey here is our Striker:</b> {player.first_name}", 
            parse_mode=ParseMode.HTML
        )
        logger.info(f"✅ Here is our Striker set: {player.first_name} (Index: {player_idx})")
        await asyncio.sleep(1)

        # Request Non-Striker
        captain_tag = get_user_tag(match.get_captain(bat_team))
        msg = f"🧢 <b>{captain_tag}</b>, now select the <b>NON-STRIKER</b>:\n"
        msg += f"👉 <b>Command:</b> <code>/batting [serial_number]</code>"
        
        await context.bot.send_message(chat.id, msg, parse_mode=ParseMode.HTML)
        logger.info("✅ Here our Non-striker request sent")
        return

    # ========================================
    # 🎯 CASE 2: SELECTING NON-STRIKER (Opening)
    # ========================================
    elif bat_team.current_non_striker_idx is None:
        logger.info("🎯 CASE 2: Selecting NON-STRIKER (Opening)")
        bat_team.current_non_striker_idx = player_idx
        
        await update.message.reply_text(f"🃏 <b>Non-Striker Selected:</b> {player.first_name}", parse_mode=ParseMode.HTML)
        logger.info(f"✅ Non-striker set: {player.first_name} (Index: {player_idx})")
        await asyncio.sleep(1)
        
        # ✅ Opening Pair Complete
        match.waiting_for_batsman = False
        if match.batsman_selection_task:
            match.batsman_selection_task.cancel()
            logger.info("✅ Batsman selection timer cancelled")
        
        striker = bat_team.players[bat_team.current_batsman_idx]
        non_striker = bat_team.players[bat_team.current_non_striker_idx]
        
        confirm_msg = f"✅ <b>Today's Match Opener </b>\n"
        confirm_msg += f"─────────────────\n"
        confirm_msg += f"🏏 <b>Striker:</b> {striker.first_name}\n"
        confirm_msg += f"🃏 <b>Non-Striker:</b> {non_striker.first_name}\n\n"
        
        # Send with photo
        try:
            await context.bot.send_photo(
                chat.id,
                photo=OPENING_PAIR_PHOTO,
                caption=confirm_msg,
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"Error sending opening pair photo: {e}")
            # Fallback to text
            await context.bot.send_message(chat.id, confirm_msg, parse_mode=ParseMode.HTML)
        
        logger.info("✅ Opening pair confirmed")
        await asyncio.sleep(2)
        
        # ✅ Request Bowler (Step 3) - THIS IS THE CRITICAL FIX
        match.waiting_for_bowler = True
        match.waiting_for_batsman = False  # Ensure this is false
        logger.info("📣 Calling request_bowler_selection...")
        await request_bowler_selection(context, chat.id, match)
        logger.info("✅ Bowler selection initiated")
        return

    # ========================================
    # 🎯 CASE 3: NEW BATSMAN (After Wicket)
    # ========================================
    else:
        logger.info("🎯 CASE 3: Selecting NEW BATSMAN after wicket")
        
        if not match.waiting_for_batsman:
            logger.warning("⚠️ Not waiting for batsman")
            await update.message.reply_text("⚠️ Batsmen are already set. Use /impact for substitution.")
            return

        # ✅ SET NEW STRIKER (NON-STRIKER STAYS SAME)
        bat_team.current_batsman_idx = player_idx
        match.waiting_for_batsman = False
        
        if match.batsman_selection_task:
            match.batsman_selection_task.cancel()
            logger.info("✅ Batsman selection timer cancelled")
    
        player_tag = get_user_tag(player)
        logger.info(f"✅ New batsman set: {player.first_name} (Index: {player_idx})")
    
        await asyncio.sleep(2)
        
        # ✅ CRITICAL: Check pending over complete status FIRST
        if hasattr(match, 'pending_over_complete') and match.pending_over_complete:
            logger.info("🏁 Pending over complete detected, calling check_over_complete")
            match.pending_over_complete = False  # Reset flag
            await check_over_complete(context, chat.id, match)
            return
        
        # ✅ If no pending over complete, resume normal play
        bowl_team = match.current_bowling_team
        
        # ✅ If bowler exists, resume
        if bowl_team.current_bowler_idx is not None:
            logger.info("▶️ Bowler exists, resuming ball execution")
            await execute_ball(context, chat.id, match)
            
        # ✅ Edge case: No bowler (shouldn't happen in normal flow)
        else:
            logger.warning("⚠️ No bowler found, requesting bowler selection")
            match.waiting_for_bowler = True
            await request_bowler_selection(context, chat.id, match)        
        return

async def _build_players_text(match: Match) -> str:
    """Rebuild the /players text (used by both the command and the Refresh button)."""
    toss_winner_team = getattr(match, 'toss_winner', None)

    NUM_EMOJI = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟",
                 "1️⃣1️⃣","1️⃣2️⃣","1️⃣3️⃣","1️⃣4️⃣","1️⃣5️⃣"]

    def _get_player_status_icons(player, team):
        if player.is_out:
            return "❌"
        icons = []
        if player.user_id == team.captain_id:
            icons.append("👑")
        if match.current_batting_team == team:
            bat_idx = team.current_batsman_idx
            ns_idx = team.current_non_striker_idx
            if bat_idx is not None and bat_idx < len(team.players) and team.players[bat_idx].user_id == player.user_id:
                icons.append("🏏")
            elif ns_idx is not None and ns_idx < len(team.players) and team.players[ns_idx].user_id == player.user_id:
                icons.append("🏃‍♂️")
        if match.current_bowling_team == team:
            bowl_idx = team.current_bowler_idx
            if bowl_idx is not None and bowl_idx < len(team.players) and team.players[bowl_idx].user_id == player.user_id:
                icons.append("‼️")
        return " ".join(icons) if icons else ""

    def _build_player_row(player, team, num):
        tag = f'<a href="tg://user?id={player.user_id}">{html.escape(player.first_name)}</a>'
        status = _get_player_status_icons(player, team)
        num_icon = NUM_EMOJI[num-1] if num <= len(NUM_EMOJI) else f"{num}."
        row = f"├ {num_icon} {tag}"
        if status:
            row += f" {status}"
        row += "\n"
        return row

    def _build_team_block(team, color, num_players):
        toss_icon = " 🪙" if toss_winner_team == team else ""
        score_str = ""
        if match.phase == GamePhase.MATCH_IN_PROGRESS or match.innings >= 1:
            score_str = f" ➔ {team.score}/{team.wickets} ({format_overs(team.balls)} ov)"
        color_icon = "🧊" if team == match.team_x else "🔥"
        block = f"{color_icon} <b>𝗧𝗘𝗔𝗠 {html.escape(team.name)}</b>{toss_icon}{score_str}\n"
        block += "┌───────────────────\n"
        for i, player in enumerate(team.players, 1):
            block += _build_player_row(player, team, i)
        block += "└───────────────────\n"
        return block

    host_tag = f'<a href="tg://user?id={match.host_id}">{html.escape(match.host_name or "Host")}</a>'
    overs_info = getattr(match, 'total_overs', 0)
    resume_code_top = getattr(match, 'resume_code', None)
    text = f"👑 𝗛𝗼𝘀𝘁: {host_tag}\n"
    text += f"⏳ 𝗢𝘃𝗲𝗿𝘀: {overs_info}\n"
    if resume_code_top:
        text += f"🔑 𝗥𝗲𝘀𝘂𝗺𝗲: <code>/regame {resume_code_top}</code>\n"
    text += "─────────────────\n"
    text += _build_team_block(match.team_x, "❄️", len(match.team_x.players))
    text += _build_team_block(match.team_y, "🔥", len(match.team_y.players))
    ist_now = datetime.utcnow() + timedelta(hours=5, minutes=30)
    text += f"\n🕒 <i>Last updated: {ist_now.strftime('%H:%M:%S')} IST</i>"
    return text


PLAYERS_CMD_MAX_USES = 6  # /players can only be run this many times per match (Refresh button doesn't count)


async def players_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Show playing squads with player tags and live real-time status"""
    group_id = update.effective_chat.id
    match = active_matches.get(group_id)
    
    if not match:
        await update.message.reply_text("🏏 No active match! Start with /game")
        return

    if getattr(match, 'game_mode', None) in ["SOLO", "MAGICBALL"] or match.phase in [GamePhase.SOLO_JOINING, GamePhase.SOLO_MATCH]:
        # Solo mode → show player roster
        msg = "📜 <b>SOLO BATTLE ROSTER</b>\n"
        msg += "─────────────────\n"
        for i, p in enumerate(match.solo_players, 1):
            status = "⏳ <i>Waiting</i>"
            if p.is_out: status = "❌ <b>OUT</b>"
            elif match.phase == GamePhase.SOLO_MATCH:
                if i-1 == match.current_solo_bat_idx: status = "🏏 <b>BATTING</b>"
                elif i-1 == match.current_solo_bowl_idx: status = "⚾ <b>BOWLING</b>"
                elif p.is_bowling_banned: status = "🚫 <b>BANNED (Bowl)</b>"
            msg += f"<b>{i}. {p.first_name}</b>\n   └ {status} • {p.runs} Runs\n"
        msg += "─────────────────"
        await update.message.reply_text(msg, parse_mode=ParseMode.HTML)
        return

    # ── Usage limit: /players can only be used 6 times per match ──
    uses = getattr(match, 'players_cmd_uses', 0)
    if uses >= PLAYERS_CMD_MAX_USES:
        await update.message.reply_text(
            f"⚠️ <b>/players limit reached</b> ({PLAYERS_CMD_MAX_USES}/match). "
            f"Use the 🔄 Refresh button on the last card instead.",
            parse_mode=ParseMode.HTML
        )
        return

    # ── 2-minute cooldown for players command during active match ──
    if match.phase == GamePhase.MATCH_IN_PROGRESS:
        remaining = check_players_cooldown(group_id)
        if remaining is not None:
            secs = math.ceil(remaining)
            mins = secs // 60
            sec_part = secs % 60
            cool_msg = await update.message.reply_text(
                f"⏳ <b>Players command cooldown:</b> Wait <b>{mins}m {sec_part}s</b> more!",
                parse_mode=ParseMode.HTML
            )
            asyncio.get_event_loop().call_later(
                remaining + 1,
                lambda: asyncio.ensure_future(cool_msg.delete())
            )
            return
        set_players_cooldown(group_id)

    match.players_cmd_uses = uses + 1
    text = await _build_players_text(match)
    refresh_kb = InlineKeyboardMarkup([[
        styled_button("🔄 Refresh", callback_data=f"players_refresh_{group_id}")
    ]])

    try:
        players_img = await generate_players_squad_image(match, context)
        if players_img:
            sent = await update.message.reply_photo(
                photo=players_img, caption=text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb
            )
        else:
            sent = await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
    except Exception:
        try:
            sent = await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
        except Exception:
            await update.message.reply_text("🏏 Players list unavailable right now.")
            return
    # Pin the players message
    try:
        await context.bot.pin_chat_message(
            chat_id=group_id,
            message_id=sent.message_id,
            disable_notification=True
        )
    except Exception:
        pass


async def players_refresh_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Refresh button on /players — updates the text in place, doesn't count against the 6-use limit."""
    query = update.callback_query
    try:
        group_id = int(query.data.split("_")[-1])
    except Exception:
        await query.answer("Invalid request", show_alert=True)
        return

    match = active_matches.get(group_id)
    if not match:
        await query.answer("⚠️ No active match anymore!", show_alert=True)
        return

    text = await _build_players_text(match)
    refresh_kb = InlineKeyboardMarkup([[
        styled_button("🔄 Refresh", callback_data=f"players_refresh_{group_id}")
    ]])
    try:
        if query.message.photo:
            await query.edit_message_caption(caption=text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
        else:
            await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=refresh_kb)
        await query.answer("✅ Refreshed!")
    except Exception:
        await query.answer("Already up to date!")



async def batsman_selection_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle batsman selection timeout"""
    try:
        await asyncio.sleep(120)  # 2 minutes - send reminder
        
        if not match.waiting_for_batsman:
            return
        
        # 2-minute reminder
        reminder_msg = (
            f"⚠️ {match.current_batting_team.name} → pick your next batter!\n"
            f"⌨️ <code>/batting [number]</code>  ·  ⏳ <b>2 min</b> left!"
        )
        await context.bot.send_message(
            chat_id=group_id,
            text=reminder_msg,
            parse_mode=ParseMode.HTML
        )
        
        await asyncio.sleep(120)  # Another 2 minutes (total 4 min)
        
        if not match.waiting_for_batsman or getattr(match, 'is_paused', False):
            return
        
        # Timeout occurred - penalty
        penalty = 6
        match.current_batting_team.score -= penalty
        match.current_batting_team.score = max(0, match.current_batting_team.score)
        match.current_batting_team.penalty_runs += penalty
        
        penalty_msg = (
            f"💸 <b>{match.current_batting_team.name}</b> penalized <b>-{penalty} runs</b> for delay!\n"
            f"📊 Score: <b>{match.current_batting_team.score}/{match.current_batting_team.wickets}</b>\n"
            f"⌨️ Select NOW: <code>/batting [number]</code>"
        )
        
        await context.bot.send_message(
            chat_id=group_id,
            text=penalty_msg,
            parse_mode=ParseMode.HTML
        )
        
        # Reset timer
        match.batsman_selection_time = time.time()
        match.batsman_selection_task = asyncio.create_task(
            batsman_selection_timeout(context, group_id, match)
        )
    
    except asyncio.CancelledError:
        pass

async def request_bowler_selection(context: ContextTypes.DEFAULT_TYPE, chat_id: int, match: Match):
    """Prompt captain for bowler - GUARANTEED DELIVERY WITH FULL LOGGING"""

    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if is_match_stale(chat_id, match):
        logger.info("⛔ request_bowler_selection aborted — match already ended.")
        return

    logger.info(f"🎬 === BOWLER SELECTION START === Chat: {chat_id}")
    
    # Validate bowling team exists
    if not match.current_bowling_team:
        logger.error("❌ CRITICAL: No bowling team set!")
        await context.bot.send_message(chat_id, "⚠️ Error: No bowling team found!", parse_mode=ParseMode.HTML)
        return
    
    logger.info(f"✅ Bowling team: {match.current_bowling_team.name}")

    # ── Check bowling queue first ──
    bowl_team = match.current_bowling_team
    queued_idx = _pop_next_bowler(chat_id, bowl_team)
    if queued_idx is not None:
        bowl_team.current_bowler_idx = queued_idx
        match.waiting_for_bowler = False
        match.current_ball_data = {}
        queued_bowler = bowl_team.players[queued_idx]
        bowler_tag = get_user_tag(queued_bowler)
        await context.bot.send_message(
            chat_id,
            f"⚾ <b>NEXT BOWLER (from queue):</b> {bowler_tag} takes the ball!",
            parse_mode=ParseMode.HTML
        )
        logger.info(f"✅ Auto-selected queued bowler: {queued_bowler.first_name}")
        await asyncio.sleep(1)
        await execute_ball(context, chat_id, match)
        return
    
    # Get captain
    captain = match.get_captain(match.current_bowling_team)
    if not captain:
        logger.error("❌ CRITICAL: No bowling captain found!")
        await context.bot.send_message(
            chat_id, 
            f"⚠️ <b>No bowling captain set!</b> 👑 Host (<code>{match.host_id}</code>) can send <code>/bowling [number]</code> to continue, or use /changecap to set a captain.", 
            parse_mode=ParseMode.HTML
        )
        return

    captain_tag = get_user_tag(captain)
    logger.info(f"👑 Captain: {captain.first_name} (ID: {captain.user_id})")
    
    # Get available bowlers
    available = match.current_bowling_team.get_available_bowlers()
    logger.info(f"📊 Available bowlers: {len(available)}")
    
    if len(available) == 0:
        logger.error("❌ CRITICAL: No available bowlers!")
        await context.bot.send_message(
            chat_id,
            "⚠️ <b>Error:</b> No bowlers available! All players may be banned from bowling.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Log available bowlers
    for i, p in enumerate(available):
        logger.info(f"  Bowler #{i+1}: {p.first_name} (ID: {p.user_id})")
    
    # Build message → properly initialized
    over_num = len(match.team_x_over_runs if match.current_batting_team == match.team_x else match.team_y_over_runs) + 1
    bowler_lines = [
        f"{captain_tag} ➔ Send in your strike bowler!",
        f"Use: <code>/bowling [number]</code>",
        f"Use <code>/qbowling</code> to pre-queue a bowler.",
        f"Host can also send this if the captain's away.",
    ]
    msg = themed("SELECT BOWLER", bowler_lines, "")
    
    # Group URL for "Go to Group" button
    try:
        _cid_str = str(abs(chat_id))
        _tme_gid = _cid_str[3:] if _cid_str.startswith("100") else _cid_str
        _group_url = f"https://t.me/c/{_tme_gid}/1"
    except Exception:
        _group_url = f"https://t.me/{context.bot.username}"
    
    bowler_select_markup = InlineKeyboardMarkup([[
        styled_button("🏟️ Go to Group", url=_group_url)
    ]])
    
    # Send message to group
    try:
        sent_msg = await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML, reply_markup=bowler_select_markup)
        logger.info(f"✅ Group message sent successfully (msg_id: {sent_msg.message_id})")
    except Exception as e:
        logger.error(f"❌ Failed to send group message: {e}")
        return
    
    # SET WAITING STATE BEFORE ANYTHING ELSE
    match.waiting_for_bowler = True
    match.waiting_for_batsman = False
    match.current_ball_data = {}
    logger.info(f"✅ State set: waiting_for_bowler=True, waiting_for_batsman=False")
    
    # Start timeout timer
    match.bowler_selection_time = time.time()
    match.bowler_selection_task = asyncio.create_task(
        bowler_selection_timeout(context, chat_id, match)
    )
    logger.info(f"✅ Timeout timer started (120 seconds)")
    
    logger.info(f"🎬 === BOWLER SELECTION END ===")

async def bowler_selection_timeout(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """Handle bowler selection timeout"""
    try:
        await asyncio.sleep(120)  # 2 minutes - send reminder
        
        if not match.waiting_for_bowler:
            return
        
        # 2-minute reminder
        captain = match.get_captain(match.current_bowling_team)
        captain_tag = get_user_tag(captain) if captain else match.current_bowling_team.name
        reminder_msg = (
            f"⚾ {captain_tag} → pick your bowler now!\n"
            f"⌨️ <code>/bowling [number]</code>  ·  ⏳ <b>2 min</b> left!"
        )
        await context.bot.send_message(
            chat_id=group_id,
            text=reminder_msg,
            parse_mode=ParseMode.HTML
        )
        
        await asyncio.sleep(120)  # Another 2 minutes (total 4 min)
        
        if not match.waiting_for_bowler or getattr(match, 'is_paused', False):
            return
        
        # Get current bowler if any
        if match.current_bowling_team.current_bowler_idx is not None:
            bowler = match.current_bowling_team.players[match.current_bowling_team.current_bowler_idx]
            bowler.bowling_timeouts += 1
            
            timeout_count = bowler.bowling_timeouts
            
            if timeout_count >= 3:
                # Ban from bowling
                bowler.is_bowling_banned = True
                
                penalty_msg = (
                    f"🚨 <b>BOWLER BANNED → TIMEOUT!</b>\n"
                    f"─────────────────\n"
                    f"⛔ <b>{bowler.first_name}</b> timed out 3× → BANNED from bowling!\n"
                    f"📌 NO BALL  ·  ➕ +1 Run  ·  ⚡ FREE HIT next!\n"
                    f"⌨️ Select another: <code>/bowling [number]</code>"
                )
                
                # Add no ball
                match.current_batting_team.score += 1
                match.current_batting_team.extras += 1
                match.is_free_hit = True
                
                await context.bot.send_message(
                    chat_id=group_id,
                    text=penalty_msg,
                    parse_mode=ParseMode.HTML
                )
            else:
                penalty_msg = (
                    f"⏱️ <b>BOWLER TIMEOUT!</b>  <code>{timeout_count}/3</code>\n"
                    f"─────────────────\n"
                    f"⚠️ <b>{bowler.first_name}</b> didn't bowl in time!\n"
                    f"📌 NO BALL  ·  ➕ +1 Run  ·  ⚡ FREE HIT!\n"
                    f"⌨️ <code>/bowling [number]</code> → select bowler!"
                )
                
                # Add no ball
                match.current_batting_team.score += 1
                match.current_batting_team.extras += 1
                match.is_free_hit = True
                
                await context.bot.send_message(
                    chat_id=group_id,
                    text=penalty_msg,
                    parse_mode=ParseMode.HTML
                )
        else:
            # First ball, no specific bowler to penalize
            penalty_msg = (
                f"⚠️ <b>{match.current_bowling_team.name}</b> delayed bowler selection!\n"
                f"─────────────────\n"
                f"💸 -6 Run Penalty applied.\n"
                f"⌨️ <code>/bowling [number]</code> → select NOW!"
            )
            
            await context.bot.send_message(
                chat_id=group_id,
                text=penalty_msg,
                parse_mode=ParseMode.HTML
            )
        
        # Reset timer
        match.bowler_selection_time = time.time()
        match.bowler_selection_task = asyncio.create_task(
            bowler_selection_timeout(context, group_id, match)
        )
    
    except asyncio.CancelledError:
        pass

async def bowling_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Bowling Selection - FIXED VERSION"""
    chat = update.effective_chat
    user = update.effective_user
    
    logger.info(f"⚾ === BOWLING COMMAND START === From: {user.first_name} (ID: {user.id})")
    
    if chat.id not in active_matches: 
        logger.warning(f"❌ No active match in chat {chat.id}")
        await update.message.reply_text("❌ No active match")
        return
    
    match = active_matches[chat.id]
    logger.info(f"✅ Match found - Phase: {match.phase}")
    
    # Check if we are waiting for bowler
    if not match.waiting_for_bowler:
        logger.warning(f"⚠️ Not waiting for bowler (waiting_for_bowler=False)")
        await update.message.reply_text("⚠️ Not waiting for bowler selection right now.")
        return
    
    logger.info(f"✅ Waiting for bowler confirmed")
    
    bowling_captain = match.get_captain(match.current_bowling_team)
    is_host = (user.id == match.host_id)

    if not bowling_captain and not is_host:
        logger.error(f"❌ No bowling captain found!")
        await update.message.reply_text("⚠️ No bowling captain found!")
        return

    if bowling_captain:
        logger.info(f"👑 Bowling captain: {bowling_captain.first_name} (ID: {bowling_captain.user_id})")

    is_captain = bool(bowling_captain and user.id == bowling_captain.user_id)
    if not is_captain and not is_host:
        logger.warning(f"🚫 User {user.first_name} is not the bowling captain or host")
        try:
            await update.message.delete()
        except Exception:
            pass
        return
    
    logger.info(f"✅ Captain/host verification passed")
    
    if not context.args:
        logger.warning(f"⚠️ No serial number provided")
        await update.message.reply_text("⚠️ Usage: <code>/bowling [serial]</code>", parse_mode=ParseMode.HTML)
        return
    
    try:
        serial = int(context.args[0])
        logger.info(f"🔢 Serial number: {serial}")
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 8878)")
        logger.error(f"❌ Invalid serial number: {context.args[0]}")
        await update.message.reply_text("❌ Invalid number.")
        return
    
    bowler = match.current_bowling_team.get_player_by_serial(serial)
    if not bowler:
        logger.error(f"❌ Player #{serial} not found in bowling team")
        await update.message.reply_text(f"❌ Player #{serial} not found.")
        return
    
    logger.info(f"👤 Bowler selected: {bowler.first_name} (ID: {bowler.user_id})")
        
    if bowler.is_bowling_banned:
        logger.warning(f"🚫 {bowler.first_name} is banned from bowling")
        await update.message.reply_text("🚫 Player is BANNED from bowling.")
        return
    
    logger.info(f"✅ Bowler validation passed")
    
    # ✅ NO CONSECUTIVE OVERS CHECK
    bowler_idx = serial - 1
    if match.current_bowling_team.bowler_history:
        if bowler_idx == match.current_bowling_team.bowler_history[-1]:
            logger.warning(f"🚫 Consecutive over attempt by {bowler.first_name}")
            await update.message.reply_text("🚫 <b>Rule:</b> Bowler cannot bowl 2 consecutive overs!", parse_mode=ParseMode.HTML)
            return
    
    logger.info(f"✅ Consecutive over check passed")

    # ✅ SET BOWLER
    match.current_bowling_team.current_bowler_idx = bowler_idx
    match.waiting_for_bowler = False
    match.waiting_for_batsman = False 
    
    logger.info(f"✅ Bowler set: Index={bowler_idx}, waiting_for_bowler=False")
    
    if match.bowler_selection_task: 
        match.bowler_selection_task.cancel()
        logger.info(f"✅ Bowler selection timer cancelled")
    
    # (BOWLER LOCKED confirmation message removed per request)
    logger.info(f"✅ Bowler locked in, resuming without confirmation message")
    
    await asyncio.sleep(2)
    
    # ✅ RESUME GAME (Trigger first ball of over) - THIS IS THE CRITICAL FIX
    logger.info(f"🎮 Calling execute_ball to start bowling...")
    await execute_ball(context, chat.id, match)
    logger.info(f"⚾ === BOWLING COMMAND END ===")


