# 4️⃣ PLAYER STATS IN AUCTION
async def bring_next_player(context: ContextTypes.DEFAULT_TYPE, chat_id: int, auction: Auction):
    """🎯 Bring next player with PREMIUM UI"""
    
    # Check if auction complete
    if len(auction.player_pool) == 0:
        # Ask auctioneer/host for confirmation before officially ending
        sold_count = len(auction.sold_players)
        unsold_count = len(auction.unsold_players)
        confirm_kb = InlineKeyboardMarkup([[
            styled_button("✅ Yes, Conclude Auction", callback_data=f"confirm_endauction_{chat_id}"),
            styled_button("❌ Keep Going", callback_data="cancel_endauction")
        ]])
        try:
            await context.bot.send_message(
                chat_id,
                f"🏁 <b>ALL PLAYERS AUCTIONED!</b>\n\n"
                f"✅ Sold: <b>{sold_count}</b>  |  ❌ Unsold: <b>{unsold_count}</b>\n\n"
                f"Confirm to officially conclude the auction?",
                parse_mode=ParseMode.HTML,
                reply_markup=confirm_kb
            )
        except Exception as e:
            logger.error(f"bring_next_player end confirm error: {e}")
            await end_auction(context, chat_id, auction)
        return
    
    # Get player
    player = auction.player_pool.pop(0)
    auction.current_player_id = player["player_id"]
    auction.current_player_name = player["player_name"]
    auction.current_base_price = player["base_price"]
    auction.current_highest_bid = player["base_price"]
    auction.current_highest_bidder = None
    auction.last_bid_teams = []  # Reset bid history for new player
    auction.last_bidder_tag = None
    auction.last_team_name = None
    auction.live_bid_log = []
    auction.bids_frozen = False
    auction.pending_sold_confirmation = False
    
    # ✅ FIX: Set phase to AUCTION_LIVE
    auction.phase = AuctionPhase.AUCTION_LIVE
    
    # 🎬 PLAYER INTRODUCTION
    player_gif = GIFS.get("auction_live")
    player_tag = f'<a href=\"tg://user?id={player['player_id']}\">{player['player_name']}</a>'
    
    # Fetch player stats - try DB first, fallback to in-memory
    p_id = player['player_id']
    init_player_stats(p_id)
    s = player_stats.get(p_id, {}).get('team', {})
    
    # Also try to read from DB for accurate team stats
    try:
        _auc_conn= await asyncio.to_thread(db_connect, DB_PATH)
        _auc_c = _auc_conn.cursor()
        _auc_c.execute("""SELECT 
            team_matches_played, team_matches_won,
            team_total_runs, team_total_balls_faced, team_total_wickets,
            team_total_sixes, team_total_fours, team_highest_score,
            team_total_hundreds, team_total_fifties, team_best_bowling_wickets, team_best_bowling_runs
            FROM user_stats WHERE user_id = ?""", (p_id,))
        db_s = _auc_c.fetchone()
        _auc_conn.close()
        if db_s and db_s[0] and db_s[0] > 0:
            _m, _w, _r, _b, _wk, _sx, _4s, _hs, _huns, _50s, _bwk, _br = db_s
        else:
            _m = s.get("matches", 0)
            _w = s.get("wins", 0)
            _r = s.get("runs", 0)
            _b = s.get("balls", 0)
            _wk = s.get("wickets", 0)
            _sx = s.get("sixes", 0)
            _4s = s.get("fours", 0)
            _hs = s.get("highest", 0)
            _huns = s.get("centuries", 0)
            _50s = s.get("fifties", 0)
            _bwk = s.get("best_bowling", {}).get("wickets", 0) if isinstance(s.get("best_bowling"), dict) else 0
            _br = s.get("best_bowling", {}).get("runs", 0) if isinstance(s.get("best_bowling"), dict) else 0
    except Exception:
        _m = s.get("matches", 0)
        _w = s.get("wins", 0)
        _r = s.get("runs", 0)
        _b = s.get("balls", 0)
        _wk = s.get("wickets", 0)
        _sx = s.get("sixes", 0)
        _4s = s.get("fours", 0)
        _hs = s.get("highest", 0)
        _huns = s.get("centuries", 0)
        _50s = s.get("fifties", 0)
        _bwk = 0
        _br = 0
    
    _avg = round(_r / max(_m, 1), 1)
    _sr = round((_r / max(_b, 1)) * 100, 1) if _b > 0 else 0.0
    _eco = round((s.get("runs_conceded", 0) / max(s.get("balls_bowled", 1), 1)) * 6, 1) if s.get("balls_bowled", 0) > 0 else 0.0
    _win_rate = round((_w / max(_m, 1)) * 100, 1) if _m > 0 else 0.0
    _best_fig = f"{_bwk}/{_br}" if _bwk > 0 else "N/A"
    
    msg = (
        f"╭━━ 🔨 AUCTION: PLAYER UP ━━━━\n"
        f"┃ 👤 Player: {player_tag}\n"
        f"┃ 🪙 Base Price: {player['base_price']} 🔷\n"
        f"┣━─────────────────\n"
        f"┃ 📊 TEAM CAREER STATS\n"
        f"┃ ─────────────────\n"
        f"┃ └ Matches: {_m} | Wins: {_w} ({_win_rate}%)\n"
        f"┃\n"
        f"┃ 🏏 BATTING\n"
        f"┃ ├ Runs: {_r} | Avg: {_avg} | SR: {_sr}\n"
        f"┃ ├ Highest: {_hs} | 100s: {_huns} | 50s: {_50s}\n"
        f"┃ └ Fours: {_4s} | Sixes: {_sx}\n"
        f"┃\n"
        f"┃ 🥎 BOWLING\n"
        f"┃ ├ Wickets: {_wk} | Economy: {_eco}\n"
        f"┃ └ Best Figure: {_best_fig}\n"
        f"┃\n"
        f"┣━─────────────────\n"
        f"┃ 💰 CURRENT BID DETAILS\n"
        f"┃ ─────────────────\n"
        f"┃ ├ 💵 Current Bid: {player['base_price']} 🔷\n"
        f"┃ ├ 👑 Bid Leader: None\n"
        f"┃ └ ⏳ Timer: 30 Seconds\n"
        f"╰━━━━━━━━\n"
    )
    
    # Quick bid buttons (+3, +5 top row, +10 bottom row)
    base = player["base_price"]
    quick_kb = InlineKeyboardMarkup([
        [
            styled_button(f"⚡ +3  ({base+3})", callback_data=f"quickbid_{chat_id}_{base+3}"),
            styled_button(f"⚡ +5  ({base+5})", callback_data=f"quickbid_{chat_id}_{base+5}"),
        ],
        [
            styled_button(f"⚡ +10 ({base+10})", callback_data=f"quickbid_{chat_id}_{base+10}"),
        ]
    ])

    try:
        await context.bot.send_animation(
            chat_id,
            animation=player_gif,
            caption=msg,
            parse_mode=ParseMode.HTML,
            reply_markup=quick_kb
        )
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12271)")
        await context.bot.send_photo(
            chat_id,
            photo=MEDIA_ASSETS.get("auction_live"),
            caption=msg,
            parse_mode=ParseMode.HTML,
            reply_markup=quick_kb
        )
    
    # Start timer
    auction.bid_end_time = time.time() + 30
    auction.bid_timer_task = asyncio.create_task(bid_timer(context, chat_id, auction))

# /soloplayers
async def soloplayers_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Fancy Solo Player List"""
    chat = update.effective_chat
    if chat.id not in active_matches: return
    match = active_matches[chat.id]

    if match.game_mode not in ["SOLO", "MAGICBALL"]:
        await update.message.reply_text("⚠️ This is not a Solo match!")
        return

    def _sp_pad(s, w):
        s = html.escape(str(s))
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    header = f"{_sp_pad('S.No', 5)}{_sp_pad('Player', 16)}{_sp_pad('Status', 14)}\n"
    table = header + ("─" * 35) + "\n"
    for i, p in enumerate(match.solo_players, 1):
        status = "Waiting"
        if p.is_out:
            status = "OUT"
        elif match.phase == GamePhase.SOLO_MATCH:
            if i - 1 == match.current_solo_bat_idx:
                status = "Batting"
            elif i - 1 == match.current_solo_bowl_idx:
                status = "Bowling"
            elif p.is_bowling_banned:
                status = "Banned (Bowl)"
        table += f"{_sp_pad(i, 5)}{_sp_pad(p.first_name, 16)}{_sp_pad(status, 14)}\n"

    msg = "📜 <b>SOLO BATTLE ROSTER</b>\n─────────────────\n"
    msg += f"<pre>{table}</pre>"
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

# /soloscore
async def soloscore_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✅ ENHANCED Solo Leaderboard - Detailed & Clean"""
    chat = update.effective_chat
    
    if chat.id not in active_matches: 
        await update.message.reply_text("⚠️ No active match!")
        return
    
    match = active_matches[chat.id]
    
    if match.game_mode not in ["SOLO", "MAGICBALL"]:
        await update.message.reply_text("⚠️ This is not a Solo match!")
        return
    
    # Sort by Runs (Desc)
    sorted_players = sorted(match.solo_players, key=lambda x: x.runs, reverse=True)
    
    msg = "🏆 <b>SOLO BATTLE LEADERBOARD</b> 🏆\n"
    msg += "─────────────────\n\n"
    
    
    for i, p in enumerate(sorted_players, 1):
        rank = f"<b>{i}.</b>"
        
        # Status
        status = ""
        if p.is_out: 
            status = " (out)"
        elif i-1 == match.current_solo_bat_idx: 
            status = " (batting)"
        elif i-1 == match.current_solo_bowl_idx: 
            status = " (bowling)"
        
        # Stats
        sr = round((p.runs / max(p.balls_faced, 1)) * 100, 1)
        
        msg += f"{rank} <b>{p.first_name}</b>{status}\n"
        msg += f"   {p.runs} runs ({p.balls_faced} balls)\n"
        msg += f"   ⚡ SR: {sr} | 🎯 Wickets: {p.wickets}\n\n"
    
    msg += "─────────────────\n"
    msg += "<i>🔝 Top 3 in the spotlight!</i>"
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)

async def start_solo_mechanics(context, chat_id, match):
    """Initializes Solo Match with randomized order"""
    match.phase = GamePhase.SOLO_MATCH
    
    # Randomize Order
    random.shuffle(match.solo_players)
    
    match.current_solo_bat_idx = 0
    match.current_solo_bowl_idx = 1
    match.solo_balls_this_spell = 0
    
    # Announce Order
    order_msg = "╭━━ 🎲 BATTING ORDER ━━━━━━🏏\n"
    order_msg += f"┃ 🎙️ Host: {html.escape(match.host_name or 'Host')}\n"
    order_msg += f"┃ 🔑 Code: {match.resume_code}\n"
    order_msg += "┃ 🔀 The order has been shuffled!\n"
    order_msg += "┃\n"
    
    for i, p in enumerate(match.solo_players, 1):
        ptag = f'<a href=\"tg://user?id={p.user_id}\">{p.first_name}</a>'
        role = " (🏏 Striker)" if i == 1 else " (⚾ Bowler)" if i == 2 else ""
        order_msg += f"<code>{i}.</code> <b>{ptag}</b>{role}\n"
    
    order_msg += "┃\n"
    order_msg += "┃ 🔥 Match Starting in 5 seconds...\n"
    order_msg += "╰━━━━━━━━"
    
    # Send with Toss/Squad Image
    await context.bot.send_photo(
        chat_id=chat_id,
        photo=MEDIA_ASSETS.get("toss"),
        caption=order_msg,
        parse_mode=ParseMode.HTML
    )
    
    await asyncio.sleep(5)
    
    # Start First Ball
    await trigger_solo_ball(context, chat_id, match)

async def trigger_solo_ball(context, chat_id, match):
    """Sets up the next ball with Timers"""
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here —
    # this is called from timeout/rotation paths that run after long sleeps, so the
    # match could have been ended in the meantime.
    if is_match_stale(chat_id, match):
        logger.info("⛔ trigger_solo_ball aborted — match already ended.")
        return
    batter = match.solo_players[match.current_solo_bat_idx]
    bowler = match.solo_players[match.current_solo_bowl_idx]
    
    match.current_ball_data = {
        "bowler_id": bowler.user_id,
        "bowler_number": None,
        "batsman_number": None,
        "is_solo": True,
        "group_id": chat_id   # ✅ Store group_id for redirect button in DM
    }
    
    bat_tag = f'<a href=\"tg://user?id={batter.user_id}\">{batter.first_name}</a>'
    bowl_tag = f'<a href=\"tg://user?id={bowler.user_id}\">{bowler.first_name}</a>'
    
    # Calculate Strike Rate
    sr = round((batter.runs / batter.balls_faced) * 100, 1) if batter.balls_faced > 0 else 0
    
    msg = f"🔴 <b>LIVE</b>\n"
    msg += "─────────────────\n"
    msg += f"⚾ <b>{bowl_tag}</b> is going for run up...\n"
    msg += f"🔄 <b>Spell:</b> Ball {match.solo_balls_this_spell + 1}/3\n"
    
    # ✅ FIX: Use deep link ?start=bowl_{chat_id} — bare URL triggers /start welcome message
    bot_username = context.bot.username
    deliver_url = f"https://t.me/{bot_username}"
    keyboard = [[styled_button("📩 Deliver Bowl", url=deliver_url)]]
    
    ball_gif = "https://t.me/kyanaamrkhe/6"
    try:
        await context.bot.send_animation(chat_id, ball_gif, caption=msg, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12442)")
        await context.bot.send_message(chat_id, msg, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode=ParseMode.HTML)
    
    # ── Build group redirect button for DM ──
    try:
        _cid_str = str(abs(chat_id))
        _tme_gid = _cid_str[3:] if _cid_str.startswith("100") else _cid_str
        _game_url = f"https://t.me/c/{_tme_gid}/{match.main_message_id or 1}"
        _dm_markup = InlineKeyboardMarkup([[
            styled_button("🏟️ Watch in Group", url=_game_url)
        ]])
    except Exception:
        _dm_markup = None

    # DM Bowler with group redirect button
    try:
        sr_batter = round((batter.runs / max(batter.balls_faced, 1)) * 100, 1)
        dm_msg = (
            f"⚔️ <b>SOLO MATCH — YOUR TURN TO BOWL!</b>\n"
            f"─────────────────\n"
            f"🏏 Batsman: <b>{batter.first_name}</b>  {batter.runs}({batter.balls_faced})  SR {sr_batter}\n"
            f"─────────────────\n"
            f"📩 <b>Send a number (0–6) to bowl!</b>\n"
            f"⏱ <i>Timer is running!</i>"
        )
        await context.bot.send_message(bowler.user_id, dm_msg, parse_mode=ParseMode.HTML, reply_markup=_dm_markup)
        
        # ✅ START BOWLER TIMER
        match.ball_timeout_task = asyncio.create_task(
            solo_game_timer(context, chat_id, match, "bowler", bowler.first_name, seq=bump_solo_ball_seq(match))
        )
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12473)")
        await context.bot.send_message(chat_id, f"⚠️ Cannot DM {bowl_tag}. Please start the bot!", parse_mode=ParseMode.HTML)

async def process_solo_turn_result(context, chat_id, match):
    """Calculates Solo result with FIXED Next Batsman flow"""
    # 🔧 GLITCH FIX: if /endmatch or /endall already ended this match, stop here.
    if is_match_stale(chat_id, match):
        logger.info("⛔ process_solo_turn_result aborted — match already ended.")
        return

    batter = match.solo_players[match.current_solo_bat_idx]
    bowler = match.solo_players[match.current_solo_bowl_idx]
    bat_num = match.current_ball_data["batsman_number"]
    bowl_num = match.current_ball_data["bowler_number"]
    
    bat_tag = f'<a href=\"tg://user?id={batter.user_id}\">{batter.first_name}</a>'
    bowl_tag = f'<a href=\"tg://user?id={bowler.user_id}\">{bowler.first_name}</a>'

    # --- MAGIC BALL MODE INTERCEPTION ---
    is_wicket = (bat_num == bowl_num)
    runs = bat_num
    magic_msg = None

    if getattr(match, "game_mode", None) == "MAGICBALL":
        match_context = {
            "match": match,
            "batter": batter,
            "bowler": bowler,
            "batsman_num": bat_num,
            "bowler_num": bowl_num
        }
        magic_ball_result = await process_magic_ball(bat_num, bowl_num, match_context)
        if magic_ball_result and magic_ball_result.get("magic_type"):
            # 1. Handle Rewind (ball doesn't count, re-bowl)
            if magic_ball_result.get("special_flag") == "rewind":
                msg = magic_ball_result.get("message", "⏮️ Rewind triggered!")
                try:
                    await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
                match.current_ball_data = {}
                await trigger_solo_ball(context, chat_id, match)
                return

            # 2. Handle Ghost / Reveal Delay
            if magic_ball_result.get("reveal_delay", 0) > 0:
                msg = magic_ball_result.get("message", "")
                try:
                    await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
                except Exception:
                    pass
                await asyncio.sleep(magic_ball_result["reveal_delay"])
                
                rev_msg = magic_ball_result.get("reveal_message", "")
                if rev_msg:
                    try:
                        await context.bot.send_message(chat_id, rev_msg, parse_mode=ParseMode.HTML)
                    except Exception:
                        pass
            
            # Override outputs
            is_wicket = magic_ball_result.get("is_wicket", False)
            runs = magic_ball_result.get("runs", 0)
            magic_msg = magic_ball_result.get("message")

    # --- 1. WICKET LOGIC ---
    if is_wicket:
        batter.is_out = True
        match.solo_balls_this_spell = 0
        
        # Hat-trick tracking
        if not hasattr(match, 'solo_consecutive_wickets'):
            match.solo_consecutive_wickets = {}
        bowler_key = bowler.user_id
        match.solo_consecutive_wickets[bowler_key] = match.solo_consecutive_wickets.get(bowler_key, 0) + 1
        hat_trick = match.solo_consecutive_wickets[bowler_key] >= 3
        
        gif = get_random_gif(MatchEvent.WICKET)
        commentary = await get_ai_commentary_async("wicket", gc_settings.get(chat_id, {}).get("commentary_style", registered_groups.get(chat_id, {}).get("commentary_style", "english")))
        sr = round((batter.runs / max(batter.balls_faced, 1)) * 100, 1)
        
        msg = f"❌ <b>OUT! {batter.first_name} is gone!</b>\n"
        msg += "─────────────────\n"
        if magic_msg:
            msg += f"🔮 {magic_msg}\n─────────────────\n"
        msg += f"🏏 <b>Final Score:</b> {batter.runs} ({batter.balls_faced})\n"
        msg += f"💬 <i>{commentary}</i>"

        try:
            if gif: await context.bot.send_animation(chat_id, gif, caption=msg, parse_mode=ParseMode.HTML)
            else: await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12564)")
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        
        # 🎩 Hat-trick celebration
        if hat_trick:
            ht_msg = (
                f"🎩〔 <b>HAT-TRICK!</b> 〕🎩\n\n"
                f"🔥 <b>{bowler.first_name}</b> takes 3 consecutive wickets!\n"
                f"🏏 <i>Unbelievable bowling display!</i>"
            )
            try:
                ht_gif = get_random_gif(MatchEvent.HAT_TRICK)
                if ht_gif:
                    await context.bot.send_animation(chat_id, ht_gif, caption=ht_msg, parse_mode=ParseMode.HTML)
                else:
                    await context.bot.send_message(chat_id, ht_msg, parse_mode=ParseMode.HTML)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12580)")
                await context.bot.send_message(chat_id, ht_msg, parse_mode=ParseMode.HTML)
            match.solo_consecutive_wickets[bowler_key] = 0  # Reset after hat-trick
        match.current_solo_bat_idx += 1
        
        # Check if ALL OUT
        if match.current_solo_bat_idx >= len(match.solo_players):
            await end_solo_game_logic(context, chat_id, match)
            return

        # Assign New Bowler (Batsman ke next wala)
        match.current_solo_bowl_idx = (match.current_solo_bat_idx + 1) % len(match.solo_players)
        new_batter = match.solo_players[match.current_solo_bat_idx]
        new_bat_tag = f'<a href=\"tg://user?id={new_batter.user_id}\">{new_batter.first_name}</a>'
        
        await asyncio.sleep(2)
        await context.bot.send_message(
            chat_id, 
            f"⚡ <b>NEXT BATSMAN:</b> {new_bat_tag} walks to the crease!\n<i>Game resuming...</i>", 
            parse_mode=ParseMode.HTML
        )
        
        # ✅ CRITICAL FIX: Naya ball trigger karna zaroori hai
        await asyncio.sleep(2)
        # 🔧 GLITCH FIX: re-check — /endmatch may have fired during the awaits above.
        if is_match_stale(chat_id, match):
            logger.info("⛔ process_solo_turn_result (wicket branch) aborted post-await — match already ended.")
            return
        await trigger_solo_ball(context, chat_id, match)
        return

    # --- 2. RUNS LOGIC ---
    else:
        batter.runs += runs
        batter.balls_faced += 1
        # 🏏 FIX: track boundaries so /mystats shows real 4s/6s instead of 0
        if runs == 4:
            batter.boundaries += 1
        elif runs == 6:
            batter.sixes += 1
        
        # Reset consecutive wickets for this bowler (scored off)
        if not hasattr(match, 'solo_consecutive_wickets'):
            match.solo_consecutive_wickets = {}
        match.solo_consecutive_wickets[bowler.user_id] = 0
        
        # Map Run Events to GIFs
        events = {0: MatchEvent.DOT_BALL, 1: MatchEvent.RUNS_1, 2: MatchEvent.RUNS_2, 
                  3: MatchEvent.RUNS_3, 4: MatchEvent.RUNS_4, 5: MatchEvent.RUNS_5, 6: MatchEvent.RUNS_6}
        comm_keys = {0: "dot", 1: "single", 2: "double", 3: "triple", 4: "boundary", 5: "five", 6: "six"}
        
        gif = get_random_gif(events.get(runs, MatchEvent.DOT_BALL))
        commentary = await get_ai_commentary_async(comm_keys.get(runs, "dot"), gc_settings.get(chat_id, {}).get("commentary_style", registered_groups.get(chat_id, {}).get("commentary_style", "english")))
        sr = round((batter.runs / batter.balls_faced) * 100, 1)

        msg = f"🔴 <b>LIVE</b>\n"
        msg += "─────────────────\n"
        if magic_msg:
            msg += f"🔮 {magic_msg}\n─────────────────\n"
        msg += f"🏏 <b>{runs} RUN{'S' if runs != 1 else ''}!</b>\n"
        msg += f"💬 <i>{commentary}</i>\n"
        msg += "─────────────────\n"
        msg += f"📊 <b>{batter.first_name}:</b> {batter.runs} ({batter.balls_faced})\n"
        msg += f"⚡ <b>Strike Rate:</b> {sr}"

        try:
            if gif: await context.bot.send_animation(chat_id, gif, caption=msg, parse_mode=ParseMode.HTML)
            else: await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12648)")
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)

        # Over/Spell Rotation (Every 3 balls)
        match.solo_balls_this_spell += 1

        # ── 🎉 MILESTONE CELEBRATIONS ──
        prev_runs = batter.runs - runs
        # Fifty celebration
        if prev_runs < 50 and batter.runs >= 50 and batter.runs < 100:
            fifty_gif = get_random_gif(MatchEvent.FIFTY)
            cel_msg = (
                f"🌟〔 <b>FIFTY!</b> 〕🌟\n\n"
                f"🏏 <b>{batter.first_name}</b> reaches <b>50 runs</b>!\n"
                f"📊 {batter.runs} ({batter.balls_faced})  SR: {sr}\n"
                f"🎉 <i>Half-century milestone!</i>"
            )
            try:
                if fifty_gif:
                    await context.bot.send_animation(chat_id, fifty_gif, caption=cel_msg, parse_mode=ParseMode.HTML)
                else:
                    await context.bot.send_message(chat_id, cel_msg, parse_mode=ParseMode.HTML)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12670)")
                await context.bot.send_message(chat_id, cel_msg, parse_mode=ParseMode.HTML)
        # Hundred celebration
        elif prev_runs < 100 and batter.runs >= 100:
            hundred_gif = get_random_gif(MatchEvent.HUNDRED)
            cel_msg = (
                f"💯〔 <b>CENTURY!</b> 〕💯\n\n"
                f"🏏 <b>{batter.first_name}</b> reaches <b>100 runs</b>!\n"
                f"📊 {batter.runs} ({batter.balls_faced})  SR: {sr}\n"
                f"🎊 <i>What a magnificent hundred!</i>"
            )
            try:
                if hundred_gif:
                    await context.bot.send_animation(chat_id, hundred_gif, caption=cel_msg, parse_mode=ParseMode.HTML)
                else:
                    await context.bot.send_message(chat_id, cel_msg, parse_mode=ParseMode.HTML)
            except Exception as e:
                logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12686)")
                await context.bot.send_message(chat_id, cel_msg, parse_mode=ParseMode.HTML)
        if match.solo_balls_this_spell >= 3:
            match.solo_balls_this_spell = 0
            old_idx = match.current_solo_bowl_idx
            next_idx = (old_idx + 1) % len(match.solo_players)
            
            # Bowler cannot be the current Batsman
            if next_idx == match.current_solo_bat_idx:
                next_idx = (next_idx + 1) % len(match.solo_players)
            
            match.current_solo_bowl_idx = next_idx
            new_bowler = match.solo_players[next_idx]
            
            await asyncio.sleep(1)
            await context.bot.send_message(
                chat_id, 
                f"🔄 <b>CHANGE OF OVER!</b>\nNew Bowler: <b>{new_bowler.first_name}</b> takes the ball.", 
                parse_mode=ParseMode.HTML
            )
            await asyncio.sleep(2)

        # Trigger Next Ball
        # 🔧 GLITCH FIX: re-check — /endmatch may have fired during the awaits above
        # (animations, commentary calls, over-change sleeps) before we schedule the next ball.
        if is_match_stale(chat_id, match):
            logger.info("⛔ process_solo_turn_result (runs branch) aborted post-await — match already ended.")
            return
        await trigger_solo_ball(context, chat_id, match)

# --- NEW: Solo Callback Handler ---
async def solo_join_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle Solo Join/Leave AND Start Game - WITH TIMER"""
    query = update.callback_query
    chat = query.message.chat
    user = query.from_user

    if chat.id not in active_matches:
        await query.answer()
        return
    match = active_matches[chat.id]
    
    # --- ACTION: START GAME ---
    if query.data == "solo_start_game":
        # 1. Check Permissions (Host OR group admin)
        if not await _is_host_or_admin(context, chat.id, match, user.id):
            await query.answer("⚠️ Only the Host or a group admin can start the match!", show_alert=True)
            return

        # 2. Check Player Count
        if len(match.solo_players) < 2:
            await query.answer("⚠️ Need at least 2 players to start!", show_alert=True)
            return

        # 3. Ask for explicit Yes/No confirmation before force-starting
        await query.answer()
        confirm_keyboard = InlineKeyboardMarkup([
            [styled_button("✅ Yes, Force Start", callback_data="solo_start_confirm_yes"),
             styled_button("❌ No, Cancel", callback_data="solo_start_confirm_no")]
        ])
        try:
            await context.bot.send_message(
                chat_id=chat.id,
                text=(f"⚠️ <b>{html.escape(user.first_name)}</b> wants to force-start the match now, "
                      f"skipping the rest of the join timer.\n\n"
                      f"👥 <b>Players:</b> <code>{len(match.solo_players)}</code>\n\n"
                      f"❓ Force start now?"),
                parse_mode=ParseMode.HTML,
                reply_markup=confirm_keyboard
            )
        except Exception as e:
            logger.error(f"Failed to send solo force-start confirmation: {e}")
        return

    # --- ACTION: CONFIRM START GAME (Yes/No) ---
    if query.data in ("solo_start_confirm_yes", "solo_start_confirm_no"):
        if not await _is_host_or_admin(context, chat.id, match, user.id):
            await query.answer("🚫 Only the Host or a group admin can confirm this!", show_alert=True)
            return

        if query.data == "solo_start_confirm_no":
            try:
                await query.edit_message_text("❌ <b>Force-start cancelled.</b> The lobby will continue normally.",
                                               parse_mode=ParseMode.HTML)
            except Exception:
                pass
            return

        if match.phase != GamePhase.SOLO_JOINING or len(match.solo_players) < 2:
            await query.answer("⚠️ Need at least 2 players to start!", show_alert=True)
            return

        try:
            await query.edit_message_text("🚀 <b>Force-start confirmed!</b> Closing registration now...",
                                           parse_mode=ParseMode.HTML)
        except Exception:
            pass

        # Cancel Timer Task before starting
        if hasattr(match, 'solo_timer_task') and match.solo_timer_task:
            match.solo_timer_task.cancel()

        # Start the Game Logic
        await start_solo_mechanics(context, chat.id, match)
        return

    # --- VALIDATION FOR JOIN/LEAVE ---
    if match.game_mode not in ["SOLO", "MAGICBALL"] or match.phase != GamePhase.SOLO_JOINING:
        await query.answer("Registration Closed!", show_alert=True)
        return

    user_tag = f'<a href=\"tg://user?id={user.id}\">{user.first_name}</a>'

    # --- ACTION: JOIN ---
    if query.data == "solo_join":
        # Check duplicate
        for p in match.solo_players:
            if p.user_id == user.id:
                await query.answer("Already joined!", show_alert=True)
                return
        
        # Init Stats if new user
        if user.id not in player_stats: init_player_stats(user.id)
        
        # Add Player
        p = Player(user.id, user.username or "", user.first_name)
        match.solo_players.append(p)
        
        # Update the Board Image
        await update_solo_board(context, chat.id, match)

        # Popup alert to the player who tapped Join (no group spam)
        await query.answer(f"✅ You joined the Battleground! 🔥", show_alert=True)

    # --- ACTION: LEAVE ---
    elif query.data == "solo_leave":
        for i, p in enumerate(match.solo_players):
            if p.user_id == user.id:
                match.solo_players.pop(i)
                
                # Update the Board Image
                await update_solo_board(context, chat.id, match)

                # Popup alert to the player who tapped Leave (no group spam)
                await query.answer("👋 You left the Battleground.", show_alert=True)
                return
        
        await query.answer("You are not in the list.", show_alert=True)

async def solo_join_countdown(context, chat_id, match):
    """Background Timer for Solo Joining Phase - Auto Updates Board"""
    try:
        warning_sent = False
        last_bump = time.time()
        while True:
            # Check if phase changed
            if match.phase != GamePhase.SOLO_JOINING:
                break

            remaining = match.solo_join_end_time - time.time()
            
            # 30 Seconds Warning
            if remaining <= 30 and remaining > 20 and not warning_sent:
                await context.bot.send_message(
                    chat_id, 
                    "⏰ <b>LAST CALL!</b> 30 seconds left to join!\n─────────────────\n👇 Tap below NOW → hurry up! 🏏", 
                    parse_mode=ParseMode.HTML
                )
                warning_sent = True

            # Time Up
            if remaining <= 0:
                # Check minimum players
                if len(match.solo_players) < 2:
                    await context.bot.send_message(
                        chat_id,
                        "❌ <b>Match Cancelled!</b>\nNot enough players joined.",
                        parse_mode=ParseMode.HTML
                    )
                    del active_matches[chat_id]
                else:
                    # Auto-start the game
                    await context.bot.send_message(
                        chat_id,
                        "⏰ <b>Time's Up!</b> Starting match now...",
                        parse_mode=ParseMode.HTML
                    )
                    await start_solo_mechanics(context, chat_id, match)
                break
            
            # Wait 10 seconds before next update
            await asyncio.sleep(10)
            
            # Update Board
            if match.phase == GamePhase.SOLO_JOINING:
                # Every 30s: delete + resend so the board resurfaces at the
                # bottom of the chat (won't get buried under new messages).
                if time.time() - last_bump >= 30:
                    await bump_solo_board(context, chat_id, match)
                    last_bump = time.time()
                else:
                    await update_solo_board(context, chat_id, match)
            
    except asyncio.CancelledError:
        pass
    except Exception as e:
        logger.error(f"Solo timer error: {e}")

async def end_solo_game_logic(context, chat_id, match):
    """✅ FIXED: Solo End with GC Notification"""
    match.phase = GamePhase.MATCH_ENDED

    # 🔧 GLITCH FIX: cancel any lingering timer/task tied to this match so it
    # can't wake up later and act on a chat that has since moved on to a new
    # match. This mirrors what the manual /endsolo confirm handler already does.
    for _task_attr in ("ball_timeout_task", "solo_timer_task", "join_phase_task",
                       "active_ball_task", "pause_task"):
        _task = getattr(match, _task_attr, None)
        if _task:
            _task.cancel()

    # 🔧 GLITCH FIX: remove from active_matches immediately so a stray/late
    # callback checking "chat_id not in active_matches" can't mistake this
    # dead match for the currently active one.
    if active_matches.get(chat_id) is match:
        del active_matches[chat_id]
    
    # ✅ GENERATE AND SEND FINAL IMAGE FIRST
    if "generate_solo_end_image_v2" in globals():
        try:
            await generate_solo_end_image_v2(context, chat_id, match)
        except Exception as e:
            logger.error(f"Error generating solo end image: {e}")
    
    await asyncio.sleep(2)
    
    sorted_players = sorted(match.solo_players, key=lambda x: x.runs, reverse=True)
    winner = sorted_players[0]
    
    # Save Stats
    for p in match.solo_players:
        init_player_stats(p.user_id)
        
        if p.user_id in player_stats:
            s = player_stats[p.user_id]["solo"]
            s["matches"] += 1
            s["runs"] += p.runs
            s["balls"] += p.balls_faced
            s["wickets"] += p.wickets
            s["sixes"]   = s.get("sixes", 0) + getattr(p, "sixes", 0)
            s["fours"]   = s.get("fours", 0) + getattr(p, "boundaries", 0)
            if p.runs >= 100: s["centuries"] = s.get("centuries", 0) + 1
            elif p.runs >= 50: s["fifties"]  = s.get("fifties", 0) + 1
            if p.runs == 0 and p.is_out: s["ducks"] += 1
            if p.runs > s.get("highest", 0): s["highest"] = p.runs
            if p.runs > s.get("high_score", 0): s["high_score"] = p.runs
            
            if p.user_id == winner.user_id: 
                s["wins"] += 1
            if p in sorted_players[:3]:
                s["top_3_finishes"] += 1
                
    save_data()


    # ✅ 2. VICTORY GIF WITH DETAILED CARD
    winner_sr = round((winner.runs / winner.balls_faced) * 100, 1) if winner.balls_faced > 0 else 0
    winner_tag = f'<a href=\"tg://user?id={winner.user_id}\">{html.escape(winner.first_name)}</a>'
    
    msg = f"🏆 <b>SOLO BATTLE CHAMPION</b> 🏆\n"
    msg += "─────────────────\n\n"
    msg += f"👑 <b>WINNER: {winner_tag}</b>\n"
    msg += f"💥 <b>Score:</b> {winner.runs} ({winner.balls_faced})\n"
    msg += f"🔥 <b>Strike Rate:</b> {winner_sr}\n"
    msg += "─────────────────\n\n"
    
    msg += "📊 <b>FINAL LEADERBOARD</b>\n"
    msg += "─────────────────\n"
    
    medals = ["🥇", "🥈", "🥉"]  # 🔧 FIX: was undefined here, caused "name 'medals' is not defined"
    for i, p in enumerate(sorted_players):
        rank_icon = medals[i] if i < 3 else f"<b>{i+1}.</b>"
        status = " (Not Out)" if not p.is_out else ""
        sr = round((p.runs / p.balls_faced) * 100, 1) if p.balls_faced > 0 else 0
        msg += f"{rank_icon} <b>{p.first_name}</b>: {p.runs}({p.balls_faced}) SR: {sr}{status}\n"
        
    msg += "─────────────────"

    # Try sending with PIL-generated top3 image as champion card
    try:
        top3_bio = await generate_solo_top3_image(sorted_players, context)
        if top3_bio:
            await context.bot.send_photo(chat_id, photo=top3_bio, caption=msg, parse_mode=ParseMode.HTML)
            return
    except Exception as e:
        logger.error(f"Error sending solo end PIL photo: {e}")

    # Fallback to SOLO_END_PHOTO file_id
    try:
        await context.bot.send_photo(chat_id, photo=SOLO_END_PHOTO, caption=msg, parse_mode=ParseMode.HTML)
        return
    except Exception as e:
        logger.error(f"Error sending solo end photo: {e}")
    
    # Fallback to GIF
    victory_gif = get_random_gif(MatchEvent.VICTORY)
    try:
        if victory_gif:
            await context.bot.send_animation(chat_id, victory_gif, caption=msg, parse_mode=ParseMode.HTML)
        else:
            await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 12996)")
        await context.bot.send_message(chat_id, msg, parse_mode=ParseMode.HTML)

async def endsolo_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """End solo match - ADMIN ONLY"""
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id
    
    match = active_matches.get(chat_id)
    if not match:
        await update.message.reply_text("❌ No active match in this group!")
        return
    
    if match.phase not in [GamePhase.SOLO_JOINING, GamePhase.SOLO_MATCH]:
        await update.message.reply_text("❌ No solo match is running!")
        return
    
    # Check if user is admin
    try:
        member = await context.bot.get_chat_member(chat_id, user_id)
        is_admin = member.status in ['creator', 'administrator']
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 13017)")
        is_admin = False
    
    if not is_admin and user_id != match.host_id:
        await update.message.reply_text("❌ Only admins or host can end the solo match!")
        return
    
    # Show confirmation buttons
    keyboard = InlineKeyboardMarkup([
        [
            styled_button("✅ Yes, End Solo", callback_data=f"confirm_endsolo_{chat_id}"),
            styled_button("❌ Cancel", callback_data="cancel_endsolo")
        ]
    ])
    
    await update.message.reply_text(
        "⚠️ Are you sure you want to end this solo match?\n\n"
        "📊 Final results will be generated and stats will be saved.",
        reply_markup=keyboard
    )

# /extendsolo
async def extendsolo_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    if chat.id not in active_matches: return
    match = active_matches[chat.id]
    
    if match.game_mode not in ["SOLO", "MAGICBALL"] or match.phase != GamePhase.SOLO_JOINING:
        await update.message.reply_text("Can only extend during joining phase.")
        return

    try:
        sec = int(context.args[0])
        match.solo_join_end_time += sec
        await update.message.reply_text(f"✅ Extended by {sec} seconds!")
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 13052)")
        await update.message.reply_text("Usage: /extendsolo <seconds>")


