# Helper function to mock fonts if actual TTF files aren't provided


def add_vintage_texture(img: Image.Image) -> Image.Image:
    """Applies an ultimate level newspaper texture: grain, scanlines, and vignette."""
    W, H = img.size
    
    # 1. Base aged paper color overlay
    overlay = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    draw = ImageDraw.Draw(overlay)
    
    # 2. Add horizontal print scanlines
    for y in range(0, H, 3):
        alpha = random.randint(5, 20)
        draw.line([(0, y), (W, y)], fill=(150, 140, 120, alpha), width=1)
        
    # 3. Add paper impurities (speckles/grain)
    for _ in range(8000):
        x = random.randint(0, W - 1)
        y = random.randint(0, H - 1)
        alpha = random.randint(10, 40)
        draw.point((x, y), fill=(80, 70, 50, alpha))
        
    # 4. Vignette effect (darker edges for aged look)
    center_x, center_y = W / 2, H / 2
    max_dist = math.hypot(center_x, center_y)
    
    for y in range(0, H, 5):
        for x in range(0, W, 5):
            dist = math.hypot(x - center_x, y - center_y)
            intensity = (dist / max_dist) ** 2.5  # Non-linear scaling for edge focus
            if intensity > 0.2:
                alpha = int(min(200, 150 * intensity))
                draw.rectangle([x, y, x+5, y+5], fill=(50, 40, 20, alpha))

    # Composite the texture over the original image
    return Image.alpha_composite(img.convert("RGBA"), overlay).convert("RGB")

async def send_potm_message(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    🌟 PLAYER OF THE MATCH - DB update + DM only (group announcement now in win message)
    Bug 4 fix: MOM no longer announced separately in group; it's integrated in the victory message.
    """
    try:
        all_players = match.batting_first.players + match.bowling_first.players
        if not all_players: 
            return 

        # Calculate MVP Score (Improved Formula)
        best_player = None
        best_score = -1
        best_tiebreak = (-1, -1)  # (runs + wickets*20, sixes + boundaries) — for deterministic ties

        for p in all_players:
            # 🐛 FIX: a player who never batted or bowled a single ball must not
            # be eligible for MOTM. Previously best_score started at -1 and a
            # totally-inactive player's score of 0 could "win" by default just
            # by being first in the list, if nobody else had scored yet.
            if p.balls_faced == 0 and p.balls_bowled == 0:
                continue

            # Advanced scoring: Runs + Wickets*25 + SR_bonus + Economy_bonus + Impact
            score = p.runs + (p.wickets * 25)
            
            # Strike Rate Bonus
            if p.balls_faced > 10:
                sr = p.get_strike_rate()
                if sr > 150:
                    score += 20
                elif sr > 120:
                    score += 10
            
            # Economy Bonus
            if p.balls_bowled > 12:
                econ = p.get_economy()
                if econ < 5:
                    score += 20
                elif econ < 7:
                    score += 10
            
            # Boundaries Bonus
            score += (p.sixes * 3) + (p.boundaries * 1)

            # 🐛 FIX: deterministic tie-break instead of "first in list order wins".
            # Prefers the player with more combined runs+wickets impact, then
            # more boundaries, so near-identical scores don't hinge on team order.
            tiebreak = (p.runs + p.wickets * 20, p.sixes + p.boundaries)

            if score > best_score or (score == best_score and tiebreak > best_tiebreak):
                best_score = score
                best_tiebreak = tiebreak
                best_player = p

        if not best_player: 
            return

        # ✅ FIX: Save player_of_match on match object so DB update captures it
        match.player_of_match = best_player.user_id

        # ✅ FIX: Also increment mom in in-memory player_stats team dict
        init_player_stats(best_player.user_id)
        _mom_stats = player_stats[best_player.user_id]
        _mom_t = _mom_stats.setdefault("team", {})
        _mom_t["mom"] = _mom_t.get("mom", 0) + 1
        _mom_stats["team"] = _mom_t
        player_stats[best_player.user_id] = _mom_stats

        # ✅ FIX: Also update DB directly right here
        def _update_mom_db(uid):
            try:
                _mom_conn= db_connect(DB_PATH)
                _mom_c = _mom_conn.cursor()
                _mom_c.execute(
                    "INSERT INTO user_stats (user_id, player_of_match_count) VALUES (?, 1) "
                    "ON CONFLICT(user_id) DO UPDATE SET player_of_match_count = player_of_match_count + 1",
                    (uid,)
                )
                _mom_conn.commit()
                _mom_conn.close()
            except Exception as _mom_e:
                logger.error(f"MOM DB update error: {_mom_e}")
        await asyncio.to_thread(_update_mom_db, best_player.user_id)

        player_tag = get_user_tag(best_player)
        
        # Build MOM group announcement
        msg = f"🌟 <b>MAN OF THE MATCH</b> 🌟\n"
        msg += "─────────────────\n\n"
        msg += f"👑 <b>{player_tag}</b>\n\n"
        
        if best_player.balls_faced > 0:
            sr = best_player.get_strike_rate()
            msg += f"🏏 <b>BATTING</b>\n"
            msg += f"   📊 {best_player.runs} ({best_player.balls_faced})\n"
            msg += f"   ⚡ Strike Rate: {sr}\n"
            if best_player.boundaries > 0 or best_player.sixes > 0:
                msg += f"   💥 {best_player.boundaries}×4, {best_player.sixes}×6\n"
            msg += "\n"
        
        if best_player.balls_bowled > 0:
            econ = best_player.get_economy()
            msg += f"⚾ <b>BOWLING</b>\n"
            msg += f"   🎯 {best_player.wickets} Wickets\n"
            msg += f"   📉 {best_player.runs_conceded} Runs ({format_overs(best_player.balls_bowled)})\n"
            msg += f"   📊 Economy: {econ}\n\n"
        
        msg += "─────────────────\n"
        msg += "👏 <i>Outstanding Performance!</i>"

        # Bug 4 fix: MOM is now shown in the win message → skip the group announcement here.
        # Only send the DM acceptance speech to the MOM player.

        # ── Send funny acceptance speech to player DM ──
        try:
            speech_dm = generate_mom_speech(
                best_player.first_name,
                best_player.runs,
                best_player.wickets,
                getattr(match, 'group_name', '')
            )
            speech_dm += f"\n\n🏟️ <i>Congratulations from the whole Cricoverse!</i>"
            await context.bot.send_message(
                best_player.user_id,
                speech_dm,
                parse_mode=ParseMode.HTML
            )
        except Exception as dm_err:
            logger.warning(f"MOM speech DM failed: {dm_err}")

    except Exception as e:
        logger.error(f"POTM Error: {e}")


async def rematch_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle rematch button → starts a new game with same overs and mode."""
    query = update.callback_query
    await query.answer("🔁 Starting rematch!", show_alert=False)
    chat = update.effective_chat
    user = update.effective_user

    try:
        parts = query.data.split("_")
        # format: rematch_{group_id}_{overs}_{mode}
        group_id = int(parts[1])
        overs = int(parts[2])
        mode = parts[3] if len(parts) > 3 else "TEAM"
    except Exception:
        await query.answer("❌ Rematch data invalid.", show_alert=True)
        return

    if chat.id != group_id:
        await query.answer("❌ This button is for that group only.", show_alert=True)
        return

    if group_id in active_matches:
        await query.answer("⚠️ A match is already in progress!", show_alert=True)
        return

    # Create new match object
    new_match = Match(group_id, chat.title or "Group")
    new_match.total_overs = overs
    new_match.game_mode = mode
    if mode == "MAGICBALL":
        new_match.magic_ball_mode = True
    new_match.phase = GamePhase.TEAM_JOINING
    active_matches[group_id] = new_match
    try:
        await notify_group_game_started(context, group_id, chat.title)
    except Exception:
        pass

    msg = f"🔁 <b>REMATCH STARTING!</b>\n"
    msg += f"─────────────────\n"
    msg += f"📋 <b>Overs:</b> {overs}  ·  <b>Mode:</b> {mode}\n"
    msg += f"─────────────────\n"
    msg += f"👥 <b>Join your team below!</b>\n"
    msg += f"⏳ <i>Lobby opens now → tap to join!</i>"

    join_markup = InlineKeyboardMarkup([
        [styled_button("🧊 Join Team X", callback_data="join_team_x"),
         styled_button("🔥 Join Team Y", callback_data="join_team_y")],
        [styled_button("🚪 Leave", callback_data="leave_team")]
    ])

    try:
        sent = await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML, reply_markup=join_markup)
        new_match.main_message_id = sent.message_id
    except Exception as e:
        logger.error(f"Rematch start error: {e}")


async def start_super_over(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    ⚡ SUPER OVER MECHANICS
    - Each team gets 1 over (6 balls)
    - NO DRS
    - Highest score wins
    """
    match.is_super_over = True
    match.phase = GamePhase.SUPER_OVER
    
    # Toss for Super Over
    toss_winner = random.choice([match.team_x, match.team_y])
    toss_loser = match.get_other_team(toss_winner)
    
    # Toss winner chooses bat/bowl
    decision = random.choice(["bat", "bowl"])
    
    if decision == "bat":
        match.super_over_batting_first = toss_winner
        match.super_over_bowling_first = toss_loser
    else:
        match.super_over_batting_first = toss_loser
        match.super_over_bowling_first = toss_winner
    
    # Announcement
    msg = f"⚡〔 <b>SUPER OVER!</b> 〕⚡\n"
    msg += "─────────────────\n"
    msg += f"  🪙 Toss: {toss_winner.name} won  \n"
    msg += f"  👉 Decision: {decision.upper()} first  \n"
    msg += "─────────────────\n\n"
    msg += f"🏏 <b>{match.super_over_batting_first.name}</b> → BATTING\n"
    msg += f"⚾ <b>{match.super_over_bowling_first.name}</b> → BOWLING\n\n"
    msg += "📜 <b>RULES:</b>\n"
    msg += "🔸 1 Over (6 balls) per team\n"
    msg += "🔸 No DRS available\n"
    msg += "🔸 Highest score wins!\n\n"
    msg += "⏳ <i>Buckle up! Starting in 10 seconds...</i>"
    
    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
    await asyncio.sleep(10)
    
    # Reset teams for Super Over
    await reset_teams_for_super_over(match)
    
    # Start 1st Super Over Innings
    match.innings = 1
    match.total_overs = 1  # Only 1 over
    match.current_batting_team = match.super_over_batting_first
    match.current_bowling_team = match.super_over_bowling_first
    match.current_batting_team.innings_start_squad_size = len(match.current_batting_team.players)
    match.target = 0
    
    # Request openers
    match.waiting_for_batsman = True
    match.waiting_for_bowler = False
    
    captain = match.get_captain(match.current_batting_team)
    captain_tag = get_user_tag(captain)
    
    msg = f"⚔️ <b>SELECT STRIKER</b>\n"
    msg += f"👮‍♂️👉 <b>{captain_tag}</b>, select STRIKER:\n"
    msg += f"⌨️ <code>/batting [serial]</code>"
    
    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
    
    match.batsman_selection_time = time.time()
    match.batsman_selection_task = asyncio.create_task(
        batsman_selection_timeout(context, group_id, match)
    )

async def reset_teams_for_super_over(match: Match):
    """
    🔄 Reset team stats for Super Over
    """
    for team in [match.team_x, match.team_y]:
        team.score = 0
        team.wickets = 0
        team.balls = 0
        team.overs = 0.0
        team.extras = 0
        team.current_batsman_idx = None
        team.current_non_striker_idx = None
        team.current_bowler_idx = None
        team.out_players_indices = set()
        team.bowler_history = []
        team.drs_remaining = 0  # NO DRS in Super Over
        
        # Reset player stats
        for player in team.players:
            player.runs = 0
            player.balls_faced = 0
            player.wickets = 0
            player.balls_bowled = 0
            player.runs_conceded = 0
            player.is_out = False
            player.boundaries = 0
            player.sixes = 0

async def end_super_over_innings(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    🛑 Handle end of Super Over innings
    """
    bat_team = match.current_batting_team
    bowl_team = match.current_bowling_team
    
    first_innings_score = bat_team.score
    match.target = first_innings_score + 1
    # 🔧 FIX: reset_teams_for_super_over() below zeroes out BOTH teams' score
    # (including the team that just finished batting), so determine_super_over_winner()
    # was always comparing 0 vs the 2nd innings score. Snapshot it here instead.
    match.super_over_first_score = first_innings_score
    match.super_over_first_wickets = bat_team.wickets
    match.super_over_first_boundaries = sum(p.boundaries + p.sixes for p in bat_team.players)
    
    msg = f"⚡〔 <b>SUPER OVER → HALF TIME</b> 〕⚡\n"
    msg += "─────────────────\n"
    msg += f"  🏏 {bat_team.name}: {bat_team.score}/{bat_team.wickets}  \n"
    msg += "─────────────────\n\n"
    msg += f"🎯 <b>{bowl_team.name}</b> needs <b>{match.target}</b> to win!\n\n"
    msg += "⏳ <i>2nd super over innings in 20 seconds...</i>"
    
    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
    await asyncio.sleep(20)
    
    # Start 2nd innings
    match.innings = 2
    match.current_batting_team = bowl_team
    match.current_bowling_team = bat_team
    match.current_batting_team.innings_start_squad_size = len(match.current_batting_team.players)
    
    # Reset for 2nd inningsS
    await reset_teams_for_super_over(match)
    match.current_batting_team.score = 0
    match.current_batting_team.wickets = 0
    match.current_batting_team.balls = 0
    
    # Request openers
    match.waiting_for_batsman = True
    
    captain = match.get_captain(match.current_batting_team)
    captain_tag = get_user_tag(captain)
    
    msg = f"🔥 <b>SUPER OVER - 2ND INNINGS</b>\n"
    msg += f"👮‍♂️👉 <b>{captain_tag}</b>, select STRIKER:\n"
    msg += f"⌨️ <code>/batting [serial]</code>"
    
    await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
    
    match.batsman_selection_time = time.time()
    match.batsman_selection_task = asyncio.create_task(
        batsman_selection_timeout(context, group_id, match)
    )

async def determine_super_over_winner(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match):
    """
    🏆 Decide Super Over winner
    """
    first = match.super_over_batting_first
    second = match.get_other_team(first)

    # 🔧 FIX: first.score/first.wickets were zeroed out by reset_teams_for_super_over()
    # when the 2nd innings was set up. Use the snapshot taken in end_super_over_innings()
    # instead of the live (and now wrong) team object fields.
    first_score = match.super_over_first_score if match.super_over_first_score is not None else first.score
    first_wickets = match.super_over_first_wickets

    if second.score > first_score:
        winner = second
        loser = first
        margin = f"{second.score - first_score} runs"
    elif first_score > second.score:
        winner = first
        loser = second
        wickets_left = len(second.players) - second.wickets - len(second.out_players_indices)
        margin = f"{max(0, wickets_left)} wickets"
    else:
        # Still tied - Boundary count or wickets
        await context.bot.send_message(
            group_id,
            "🤝😱 <b>SUPER OVER ALSO TIED!</b>\n"
            "⚖️ <i>Result will be decided by boundary count...</i>",
            parse_mode=ParseMode.HTML
        )
        await asyncio.sleep(3)
        
        # Count boundaries (first innings snapshot, since reset_teams_for_super_over
        # already zeroed out first.players' boundaries/sixes for the 2nd innings)
        first_boundaries = match.super_over_first_boundaries
        second_boundaries = sum(p.boundaries + p.sixes for p in second.players)
        
        if second_boundaries > first_boundaries:
            winner = second
            loser = first
            margin = f"{second_boundaries} boundaries"
        else:
            winner = first
            loser = second
            margin = f"{first_boundaries} boundaries"
    
    # Victory Message
    victory_gif = get_random_gif(MatchEvent.VICTORY)
    
    msg = f"🏆✨ <b>SUPER OVER CHAMPION!</b> ✨🏆\n"
    msg += "─────────────────\n"
    msg += f"🥇 <b>WINNER: {winner.name}</b>\n"
    msg += f"📊 Won by: {margin}\n\n"
    msg += f"🔥 {first.name}: {first_score}/{first_wickets}\n"
    msg += f"🧊 {second.name}: {second.score}/{second.wickets}\n"
    msg += "─────────────────\n"
    msg += f"🔥 <i>What a thriller! Absolute edge-of-the-seat finish!</i>"
    
    try:
        await context.bot.send_animation(group_id, animation=victory_gif, caption=msg, parse_mode=ParseMode.HTML)
    except Exception as e:
        logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 18235)")
        await context.bot.send_message(group_id, msg, parse_mode=ParseMode.HTML)
    
    # Update stats
    try:
        await update_player_stats_after_match(match, winner, loser)
        await save_match_to_history(match, winner.name)
    except: pass
    
    await asyncio.sleep(3)
    
    # POTM
    try:
        await send_potm_message(context, group_id, match)
    except: pass
    
    # 🏆 Fantasy Dream III — finalize results
    try:
        await finalize_fantasy_results(context, group_id, match)
    except Exception as e:
        logger.error(f"❌ Fantasy results error (super over): {e}")
    
    # Cleanup
    try:
        if match.main_message_id:
            await context.bot.unpin_chat_message(chat_id=group_id, message_id=match.main_message_id)
    except: pass
    
    if group_id in active_matches:
        del active_matches[group_id]

async def send_match_summary(context: ContextTypes.DEFAULT_TYPE, group_id: int, match: Match, winner: Team, loser: Team):
    """Send detailed match summary with player statistics"""
    
    # Batting summary for both teams
    summary_text = "Match Summary\n"
    summary_text += "=" * 40 + "\n\n"
    
    # First innings batting
    summary_text += f"{match.batting_first.name} Batting\n"
    summary_text += "-" * 40 + "\n"
    for player in match.batting_first.players:
        if player.balls_faced > 0 or player.is_out:
            status = "out" if player.is_out else "not out"
            sr = player.get_strike_rate()
            summary_text += f"{player.first_name}: {player.runs} ({player.balls_faced}) - {status}"
            if player.boundaries > 0:
                summary_text += f" [{player.boundaries}x4"
                if player.sixes > 0:
                    summary_text += f", {player.sixes}x6"
                summary_text += "]"
            summary_text += f" SR: {sr}\n"
    
    summary_text += f"\nTotal: {match.batting_first.score}/{match.batting_first.wickets}\n"
    summary_text += f"Overs: {format_overs(match.batting_first.balls)}\n"
    summary_text += f"Extras: {match.batting_first.extras}\n\n"
    
    # Second innings batting
    summary_text += f"{match.bowling_first.name} Batting\n"
    summary_text += "-" * 40 + "\n"
    for player in match.bowling_first.players:
        if player.balls_faced > 0 or player.is_out:
            status = "out" if player.is_out else "not out"
            sr = player.get_strike_rate()
            summary_text += f"{player.first_name}: {player.runs} ({player.balls_faced}) - {status}"
            if player.boundaries > 0:
                summary_text += f" [{player.boundaries}x4"
                if player.sixes > 0:
                    summary_text += f", {player.sixes}x6"
                summary_text += "]"
            summary_text += f" SR: {sr}\n"
    
    summary_text += f"\nTotal: {match.bowling_first.score}/{match.bowling_first.wickets}\n"
    summary_text += f"Overs: {format_overs(match.bowling_first.balls)}\n"
    summary_text += f"Extras: {match.bowling_first.extras}\n\n"
    
    await context.bot.send_message(
        chat_id=group_id,
        text=summary_text
    )
    
    await asyncio.sleep(1)
    
    # Bowling summary
    bowling_summary = "Bowling Figures\n"
    bowling_summary += "=" * 40 + "\n\n"
    
    # First innings bowling
    bowling_summary += f"{match.bowling_first.name} Bowling\n"
    bowling_summary += "-" * 40 + "\n"
    for player in match.bowling_first.players:
        if player.balls_bowled > 0:
            overs = format_overs(player.balls_bowled)
            economy = player.get_economy()
            bowling_summary += f"{player.first_name}: {overs} overs, {player.wickets}/{player.runs_conceded}"
            bowling_summary += f" Econ: {economy}"
            if player.maiden_overs > 0:
                bowling_summary += f" M: {player.maiden_overs}"
            bowling_summary += "\n"
    
    bowling_summary += "\n"
    
    # Second innings bowling
    bowling_summary += f"{match.batting_first.name} Bowling\n"
    bowling_summary += "-" * 40 + "\n"
    for player in match.batting_first.players:
        if player.balls_bowled > 0:
            overs = format_overs(player.balls_bowled)
            economy = player.get_economy()
            bowling_summary += f"{player.first_name}: {overs} overs, {player.wickets}/{player.runs_conceded}"
            bowling_summary += f" Econ: {economy}"
            if player.maiden_overs > 0:
                bowling_summary += f" M: {player.maiden_overs}"
            bowling_summary += "\n"
    
    await context.bot.send_message(
        chat_id=group_id,
        text=bowling_summary
    )
    
    await asyncio.sleep(1)
    
    # Player of the Match
    potm_text = "Player of the Match\n"
    potm_text += "=" * 40 + "\n\n"
    
    # Calculate POTM based on performance
    all_players = match.batting_first.players + match.bowling_first.players
    best_player = None
    best_score = 0
    
    for player in all_players:
        # Score calculation: runs + (wickets * 20) + (boundaries * 2)
        performance_score = player.runs + (player.wickets * 20) + (player.boundaries * 2)
        if performance_score > best_score:
            best_score = performance_score
            best_player = player
    
    if best_player:
        potm_text += f"{best_player.first_name}\n\n"
        if best_player.balls_faced > 0:
            potm_text += f"Batting: {best_player.runs} ({best_player.balls_faced}) SR: {best_player.get_strike_rate()}\n"
        if best_player.balls_bowled > 0:
            potm_text += f"Bowling: {best_player.wickets}/{best_player.runs_conceded} Econ: {best_player.get_economy()}\n"
    
    await context.bot.send_message(
        chat_id=group_id,
        text=potm_text
    )

async def update_player_stats_after_match(match: Match, winner: Team, loser: Team):
    """Update global player statistics after match → writes BOTH flat + team/solo dicts."""
    all_players = match.batting_first.players + match.bowling_first.players

    for player in all_players:
        user_id = player.user_id
        init_player_stats(user_id)          # ensures all keys exist
        stats    = player_stats[user_id]
        is_winner = bool(winner and player in winner.players)

        # ── flat legacy keys (kept for backward compat) ──
        stats["matches_played"]     = stats.get("matches_played", 0) + 1
        if winner and is_winner:
            stats["matches_won"]    = stats.get("matches_won", 0) + 1

        # ── Form guide: last 5 W/L results ──
        _result_char = "W" if is_winner else "L"
        _last5 = stats.get("last_5_results", []) + [_result_char]
        stats["last_5_results"] = _last5[-5:]
        # Also mirror into team dict early (will be overwritten later but sets key)
        _t_early = stats.setdefault("team", {})
        _t_early["last_5_results"] = (_t_early.get("last_5_results", []) + [_result_char])[-5:]

        if player.balls_faced > 0:
            stats["total_runs"]         = stats.get("total_runs", 0) + player.runs
            stats["total_balls_faced"]  = stats.get("total_balls_faced", 0) + player.balls_faced
            stats["dot_balls_faced"]    = stats.get("dot_balls_faced", 0) + getattr(player, 'dot_balls_faced', 0)
            stats["boundaries"]         = stats.get("boundaries", 0) + getattr(player, 'boundaries', 0)
            stats["sixes"]              = stats.get("sixes", 0) + getattr(player, 'sixes', 0)
            if player.runs >= 100: stats["centuries"]       = stats.get("centuries", 0) + 1
            elif player.runs >= 50: stats["half_centuries"] = stats.get("half_centuries", 0) + 1
            if player.runs > stats.get("highest_score", 0): stats["highest_score"] = player.runs
            if player.runs == 0 and player.is_out: stats["ducks"] = stats.get("ducks", 0) + 1
            ls = stats.get("last_5_scores", []) + [player.runs]
            stats["last_5_scores"] = ls[-5:]

        # Catches & Dismissals tracking
        c_taken = getattr(player, 'catches', 0)
        if c_taken > 0:
            stats["catches_taken"] = stats.get("catches_taken", 0) + c_taken
        if player.is_out:
            dtype = getattr(player, 'dismissal_type', 'Bowled')
            if dtype == "Bowled":
                stats["dismissals_bowled"] = stats.get("dismissals_bowled", 0) + 1
            elif dtype == "LBW":
                stats["dismissals_lbw"] = stats.get("dismissals_lbw", 0) + 1
            elif dtype == "Caught":
                stats["dismissals_caught"] = stats.get("dismissals_caught", 0) + 1

        if player.balls_bowled > 0:
            stats["total_wickets"]        = stats.get("total_wickets", 0) + player.wickets
            stats["total_balls_bowled"]   = stats.get("total_balls_bowled", 0) + player.balls_bowled
            stats["total_runs_conceded"]  = stats.get("total_runs_conceded", 0) + player.runs_conceded
            stats["dot_balls_bowled"]     = stats.get("dot_balls_bowled", 0) + getattr(player, 'dot_balls_bowled', 0)
            bb = stats.get("best_bowling")
            if not isinstance(bb, dict): bb = {"wickets": 0, "runs": 999}
            if player.wickets > bb["wickets"] or (player.wickets == bb["wickets"] and player.runs_conceded < bb.get("runs", 999)):
                bb = {"wickets": player.wickets, "runs": player.runs_conceded}
            stats["best_bowling"] = bb
            lw = stats.get("last_5_wickets", []) + [player.wickets]
            stats["last_5_wickets"] = lw[-5:]
            if getattr(player, 'has_hat_trick', False):
                stats["hat_tricks"] = stats.get("hat_tricks", 0) + 1

        # ══════════════════════════════════════════════
        # ✅ TEAM DICT → this is what /mystats reads
        # ══════════════════════════════════════════════
        t = stats.setdefault("team", {})
        t["matches"]        = t.get("matches", 0) + 1
        t["matches_played"] = t.get("matches_played", 0) + 1
        if is_winner:
            t["wins"]       = t.get("wins", 0) + 1
        t["runs"]           = t.get("runs", 0)  + player.runs
        t["balls"]          = t.get("balls", 0) + player.balls_faced
        t["wickets"]        = t.get("wickets", 0) + player.wickets
        t["balls_bowled"]   = t.get("balls_bowled", 0) + player.balls_bowled
        t["runs_conceded"]  = t.get("runs_conceded", 0) + player.runs_conceded
        t["fours"]          = t.get("fours", 0) + getattr(player, 'boundaries', 0)
        t["sixes"]          = t.get("sixes", 0) + getattr(player, 'sixes', 0)
        t["dots"]           = t.get("dots", 0) + getattr(player, 'dot_balls_faced', 0)
        if player.runs > t.get("highest", 0):      t["highest"] = player.runs
        if player.runs >= 100:                     t["centuries"] = t.get("centuries", 0) + 1
        elif player.runs >= 50:                    t["fifties"]   = t.get("fifties", 0) + 1
        if player.runs == 0 and player.balls_faced > 0 and player.is_out:
            t["ducks"] = t.get("ducks", 0) + 1
        if c_taken > 0:
            t["catches_taken"] = t.get("catches_taken", 0) + c_taken
        if player.is_out:
            dtype = getattr(player, 'dismissal_type', 'Bowled')
            if dtype == "Bowled":
                t["dismissals_bowled"] = t.get("dismissals_bowled", 0) + 1
            elif dtype == "LBW":
                t["dismissals_lbw"] = t.get("dismissals_lbw", 0) + 1
            elif dtype == "Caught":
                t["dismissals_caught"] = t.get("dismissals_caught", 0) + 1
        if not player.is_out and player.balls_faced > 0:
            t["times_not_out"] = t.get("times_not_out", 0) + 1
        # best bowling
        cb_w = t.get("best_bowling_wickets", 0)
        cb_r = t.get("best_bowling_runs", 999)
        if player.balls_bowled > 0 and (player.wickets > cb_w or (player.wickets == cb_w and player.runs_conceded < cb_r)):
            t["best_bowling_wickets"] = player.wickets
            t["best_bowling_runs"]    = player.runs_conceded
        if getattr(player, 'has_hat_trick', False):
            t["hat_tricks"] = t.get("hat_tricks", 0) + 1
        stats["team"] = t

        # ✅ FIX: Save captaincy stats in team dict
        # Check if this player is captain of team_x or team_y
        _is_cap = False
        if hasattr(match, 'team_x') and match.team_x.captain_id == player.user_id:
            _is_cap = True
        elif hasattr(match, 'team_y') and match.team_y.captain_id == player.user_id:
            _is_cap = True
        if _is_cap:
            t["cap_matches"] = t.get("cap_matches", 0) + 1
            if is_winner:
                t["cap_wins"] = t.get("cap_wins", 0) + 1
            stats["team"] = t

        player_stats[user_id] = stats

    # ── sync to DB ──
    # 🔧 SCALE FIX: this used to run a full upsert query per player directly
    # on the event loop, every single time ANY match ended in ANY group.
    # With hundreds of groups finishing matches around the same time, this
    # was blocking ball-detection/messages everywhere else. Now it runs in
    # a background thread.
    def _sync_player_stats_to_db(all_players, winner):
        try:
            conn_s= db_connect(DB_PATH)
            cs = conn_s.cursor()
            for player in all_players:
                uid   = player.user_id
                is_w  = 1 if (winner and player in winner.players) else 0
                _sixes    = getattr(player, 'sixes', 0)
                _fours    = getattr(player, 'boundaries', 0)
                _dots     = getattr(player, 'dot_balls_faced', 0)
                _is_duck  = 1 if (player.runs == 0 and player.balls_faced > 0 and player.is_out) else 0
                _is_100   = 1 if player.runs >= 100 else 0
                _is_50    = 1 if 50 <= player.runs < 100 else 0
                _is_fifer = 1 if player.balls_bowled > 0 and player.wickets >= 5 else 0
                _hat_trick = 1 if getattr(player, 'has_hat_trick', False) else 0

                cs.execute("""
                    INSERT INTO user_stats
                        (user_id, username, first_name,
                         matches_played, matches_won,
                         total_runs, total_balls_faced,
                         total_wickets, total_balls_bowled,
                         total_sixes, total_fours,
                         highest_score, total_hundreds,
                         total_fifties, total_ducks, total_dots,
                         best_bowling_wickets, best_bowling_runs,
                         five_wicket_hauls, hat_tricks,
                         team_matches_played, team_matches_won,
                         team_total_runs, team_total_balls_faced,
                         team_total_wickets, team_total_balls_bowled,
                         team_total_sixes, team_total_fours,
                         team_highest_score, team_total_hundreds,
                         team_total_fifties, team_total_ducks, team_total_dots)
                    VALUES (?,?,?,
                            1,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,
                            1,?,?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(user_id) DO UPDATE SET
                        username              = excluded.username,
                        first_name            = excluded.first_name,
                        matches_played        = matches_played + 1,
                        matches_won           = matches_won + ?,
                        total_runs            = total_runs + ?,
                        total_balls_faced     = total_balls_faced + ?,
                        total_wickets         = total_wickets + ?,
                        total_balls_bowled    = total_balls_bowled + ?,
                        total_sixes           = total_sixes + ?,
                        total_fours           = total_fours + ?,
                        highest_score         = MAX(highest_score, ?),
                        total_hundreds        = total_hundreds + ?,
                        total_fifties         = total_fifties + ?,
                        total_ducks           = total_ducks + ?,
                        total_dots            = total_dots + ?,
                        best_bowling_wickets  = CASE WHEN ? > best_bowling_wickets THEN ? ELSE best_bowling_wickets END,
                        best_bowling_runs     = CASE WHEN ? > best_bowling_wickets THEN ? WHEN ? = best_bowling_wickets THEN MIN(best_bowling_runs, ?) ELSE best_bowling_runs END,
                        five_wicket_hauls     = five_wicket_hauls + ?,
                        hat_tricks            = hat_tricks + ?,
                        team_matches_played   = team_matches_played + 1,
                        team_matches_won      = team_matches_won + ?,
                        team_total_runs       = team_total_runs + ?,
                        team_total_balls_faced= team_total_balls_faced + ?,
                        team_total_wickets    = team_total_wickets + ?,
                        team_total_balls_bowled=team_total_balls_bowled + ?,
                        team_total_sixes      = team_total_sixes + ?,
                        team_total_fours      = team_total_fours + ?,
                        team_highest_score    = MAX(team_highest_score, ?),
                        team_total_hundreds   = team_total_hundreds + ?,
                        team_total_fifties    = team_total_fifties + ?,
                        team_total_ducks      = team_total_ducks + ?,
                        team_total_dots       = team_total_dots + ?
                """, (
                    # INSERT values
                    uid, player.username or "", player.first_name,
                    # flat insert
                    is_w, player.runs, player.balls_faced,
                    player.wickets, player.balls_bowled,
                    _sixes, _fours,
                    player.runs, _is_100, _is_50, _is_duck, _dots,
                    player.wickets, player.runs_conceded,
                    _is_fifer, _hat_trick,
                    # team insert
                    is_w, player.runs, player.balls_faced,
                    player.wickets, player.balls_bowled,
                    _sixes, _fours,
                    player.runs, _is_100, _is_50, _is_duck, _dots,
                    # ON CONFLICT flat update params
                    is_w, player.runs, player.balls_faced,
                    player.wickets, player.balls_bowled,
                    _sixes, _fours,
                    player.runs, _is_100, _is_50, _is_duck, _dots,
                    # best bowling update (needs wickets x3, runs x2)
                    player.wickets, player.wickets,
                    player.wickets, player.runs_conceded, player.wickets, player.runs_conceded,
                    _is_fifer, _hat_trick,
                    # ON CONFLICT team update params
                    is_w, player.runs, player.balls_faced,
                    player.wickets, player.balls_bowled,
                    _sixes, _fours,
                    player.runs, _is_100, _is_50, _is_duck, _dots,
                ))
            conn_s.commit()
            conn_s.close()
        except Exception as db_e:
            logger.error(f"DB sync error in update_player_stats: {db_e}")

    await asyncio.to_thread(_sync_player_stats_to_db, all_players, winner)

    save_data()


def update_h2h_stats(match: Match):
    """
    Update Head-to-Head stats using REAL match data
    """

    all_players = []

    all_players.extend(match.team_x.players)
    all_players.extend(match.team_y.players)

    for p1 in all_players:
        init_player_stats(p1.user_id)

        for p2 in all_players:
            if p1.user_id == p2.user_id:
                continue

            vs = player_stats[p1.user_id].setdefault("vs_player_stats", {})
            record = vs.setdefault(str(p2.user_id), {
                "matches": 0,
                "runs_scored": 0,
                "balls_faced": 0,
                "dismissals": 0,
                "wickets_taken": 0
            })

            # Played together in same match
            record["matches"] += 1

            # Batting vs opponent
            record["runs_scored"] += p1.runs
            record["balls_faced"] += p1.balls_faced

            # If p1 got out & p2 was bowler
            if p1.is_out and match.current_bowling_team.get_player(p2.user_id):
                record["dismissals"] += 1

            # Bowling vs opponent
            record["wickets_taken"] += p1.wickets

    # 🔮 Magic Ball Mode stats recording has been permanently disabled.
    # (Magic Ball matches no longer contribute to player statistics.)

    save_data()


# 🏆 Icons cycled for achievements shown in /mystats (purely cosmetic, in display order)
ACHIEVEMENT_ICONS = ["🥇", "⭐", "🟠", "🟣", "🏅", "🎖️", "🔥", "💎"]


def build_achievements_text(user_id: int, user_name: str) -> str:
    """Build the 🏆 Achievements section text shown in /mystats."""
    user_achievements = list(achievements.get(user_id, []))

    # 👑 Special badge for the bot owner
    if user_id == OWNER_ID and "Owner of Bot" not in user_achievements:
        user_achievements.insert(0, "Owner of Bot")

    BAR = "────────────────────"

    text = (
        f"🏆 𝗔𝗖𝗛𝗜𝗘𝗩𝗘𝗠𝗘𝗡𝗧𝗦\n"
        f"{BAR}\n"
        f"👤 𝗣𝗹𝗮𝘆𝗲𝗿 ➜ {html.escape(user_name)}\n\n"
        f"🏅 𝗕𝗔𝗗𝗚𝗘𝗦\n"
        f"┌{BAR}\n"
    )

    if not user_achievements:
        text += "├ 🔒 No badges earned yet — keep playing!\n"
    else:
        for i, ach in enumerate(user_achievements):
            icon = ACHIEVEMENT_ICONS[i % len(ACHIEVEMENT_ICONS)]
            connector = "└" if i == len(user_achievements) - 1 else "├"
            text += f"{connector} {icon} {html.escape(ach)}\n"
            continue
        text = text.rstrip("\n") + "\n"

    text += f"└{BAR}"
    return text


def check_achievements(player: Player):
    """Check and award achievements to player"""
    user_id = player.user_id
    stats = player_stats.get(user_id)
    
    if not stats:
        return
    
    if user_id not in achievements:
        achievements[user_id] = []
    
    user_achievements = achievements[user_id]
    
    # Century Maker
    if stats["centuries"] >= 1 and "Century Maker" not in user_achievements:
        user_achievements.append("Century Maker")
    
    # Hat-trick Hero (3 wickets in match)
    if player.wickets >= 3 and "Hat-trick Hero" not in user_achievements:
        user_achievements.append("Hat-trick Hero")
    
    # Diamond Hands (50+ matches)
    if stats["matches_played"] >= 50 and "Diamond Hands" not in user_achievements:
        user_achievements.append("Diamond Hands")
    
    # Speed Demon (Strike Rate > 200 in a match with 10+ runs)
    if player.runs >= 10 and player.get_strike_rate() > 200 and "Speed Demon" not in user_achievements:
        user_achievements.append("Speed Demon")
    
    # Economical (Economy < 5 in a match with 12+ balls bowled)
    if player.balls_bowled >= 12 and player.get_economy() < 5 and "Economical" not in user_achievements:
        user_achievements.append("Economical")

def _save_match_to_history_sync(match, winner_team: str):
    """All the blocking DB work for save_match_to_history — always run via
    asyncio.to_thread. This runs at the end of EVERY team match in EVERY
    group, so keeping it off the event loop matters a lot at scale."""
    conn= db_connect(DB_PATH)
    c = conn.cursor()
    
    # Determine scores
    team_x_score = match.team_x_runs
    team_y_score = match.team_y_runs
    
    # Save match history
    c.execute("""
        INSERT INTO match_history 
        (group_id, match_type, winner_team, runner_up_team, total_overs, 
         team_x_score, team_y_score, player_of_match)
        VALUES (?, 'TEAM', ?, ?, ?, ?, ?, ?)
    """, (match.group_id, winner_team, 
          'Team Y' if winner_team == 'Team X' else 'Team X',
          match.total_overs, team_x_score, team_y_score, 
          match.player_of_match))
    
    # Update player stats for both teams
    all_players = list(match.team_x_players.keys()) + list(match.team_y_players.keys())
    
    for user_id in all_players:
        player = match.players.get(user_id)
        if not player:
            continue
        
        username = player.get('username', 'Unknown')
        first_name = player.get('first_name', 'Player')
        
        batting_stats = match.batting_stats.get(user_id, {})
        bowling_stats = match.bowling_stats.get(user_id, {})
        
        runs = batting_stats.get('runs', 0)
        balls_faced = batting_stats.get('balls', 0)
        wickets = bowling_stats.get('wickets', 0)
        balls_bowled = bowling_stats.get('balls', 0)
        runs_conceded = bowling_stats.get('runs', 0)
        
        # Check if user exists
        c.execute("SELECT user_id FROM user_stats WHERE user_id = ?", (user_id,))
        exists = c.fetchone()
        
        # Determine if player's team won
        player_team = 'X' if user_id in match.team_x_players else 'Y'
        won = 1 if (player_team == 'X' and winner_team == 'Team X') or \
                   (player_team == 'Y' and winner_team == 'Team Y') else 0
        
        if not exists:
            c.execute("""
                INSERT INTO user_stats 
                (user_id, username, first_name, total_runs, total_balls_faced,
                 total_wickets, total_balls_bowled, total_runs_conceded,
                 matches_played, matches_won, highest_score)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
            """, (user_id, username, first_name, runs, balls_faced, 
                  wickets, balls_bowled, runs_conceded, won, runs))
        else:
            c.execute("""
                UPDATE user_stats 
                SET total_runs = total_runs + ?,
                    total_balls_faced = total_balls_faced + ?,
                    total_wickets = total_wickets + ?,
                    total_balls_bowled = total_balls_bowled + ?,
                    total_runs_conceded = total_runs_conceded + ?,
                    matches_played = matches_played + 1,
                    matches_won = matches_won + ?,
                    highest_score = MAX(highest_score, ?),
                    username = ?,
                    first_name = ?
                WHERE user_id = ?
            """, (runs, balls_faced, wickets, balls_bowled, runs_conceded,
                  won, runs, username, first_name, user_id))
        
        # Update fifties/hundreds
        if runs >= 100:
            c.execute("UPDATE user_stats SET total_hundreds = total_hundreds + 1 WHERE user_id = ?", (user_id,))
        elif runs >= 50:
            c.execute("UPDATE user_stats SET total_fifties = total_fifties + 1 WHERE user_id = ?", (user_id,))
        
        # Update bowling best figures
        if wickets > 0:
            c.execute("""
                UPDATE user_stats 
                SET best_bowling_wickets = MAX(best_bowling_wickets, ?),
                    best_bowling_runs = CASE 
                        WHEN ? > best_bowling_wickets THEN ?
                        WHEN ? = best_bowling_wickets THEN MIN(best_bowling_runs, ?)
                        ELSE best_bowling_runs
                    END
                WHERE user_id = ?
            """, (wickets, wickets, runs_conceded, wickets, runs_conceded, user_id))
            
            if wickets >= 5:
                c.execute("UPDATE user_stats SET five_wicket_hauls = five_wicket_hauls + 1 WHERE user_id = ?", (user_id,))
    
    # Update player of match
    if match.player_of_match:
        c.execute("UPDATE user_stats SET player_of_match_count = player_of_match_count + 1 WHERE user_id = ?", 
                  (match.player_of_match,))
    
    conn.commit()
    conn.close()


async def save_match_to_history(match, winner_team: str):
    """Save team match stats to database"""
    await asyncio.to_thread(_save_match_to_history_sync, match, winner_team)



def compute_player_role(user_id: int) -> str:
    """Compute player role (All-Rounder, Batsman, Bowler, Rookie) based on stats."""
    p_stat = player_stats.get(user_id, {}).get("team", {})
    runs = p_stat.get("runs", 0)
    wickets = p_stat.get("wickets", 0)
    balls = p_stat.get("balls", 0)
    balls_bowled = p_stat.get("balls_bowled", 0)

    if runs >= 50 and wickets >= 3:
        return "All-Rounder 🏏⚾"
    elif wickets >= 3 or balls_bowled > max(balls, 1):
        return "Bowler ⚾"
    elif runs > 0 or balls > 0:
        return "Batsman 🏏"
    return "Rookie 🌟"


def build_team_stats_text(user_id: int, user_name: str) -> str:
    """Build the 👥 Team stats section text shown in /mystats (also used as the default view)."""
    SEP = "─────────────────"
    conn= db_connect(DB_PATH)
    c = conn.cursor()
    c.execute("""
        SELECT
            team_matches_played, team_matches_won,
            team_total_runs, team_highest_score,
            team_total_balls_faced, team_total_wickets,
            team_total_sixes, team_total_fours,
            team_total_hundreds, team_total_fifties, team_total_ducks,
            team_best_bowling_wickets, team_best_bowling_runs,
            team_total_dots, team_total_balls_bowled,
            win_streak, hat_tricks, player_of_match_count,
            five_wicket_hauls, times_not_out
        FROM user_stats WHERE user_id = ?
    """, (user_id,))
    db_row = c.fetchone()
    conn.close()

    if not db_row or db_row[0] == 0:
        # Fallback to old columns
        conn2= db_connect(DB_PATH)
        c2 = conn2.cursor()
        c2.execute("""
            SELECT matches_played, matches_won, total_runs, highest_score,
                   total_balls_faced, total_wickets, total_sixes, total_fours,
                   total_hundreds, total_fifties, total_ducks,
                   best_bowling_wickets, best_bowling_runs, total_dots,
                   total_balls_bowled, player_of_match_count, five_wicket_hauls
            FROM user_stats WHERE user_id = ?
        """, (user_id,))
        old_row = c2.fetchone()
        conn2.close()
        if old_row and old_row[0] > 0:
            matches, wins, runs, hs, balls_faced, wickets, sixes, fours, hundreds, fifties, ducks, best_w, best_r, dots, balls_bowled, mom, fifer = old_row
            win_streak = hat_tricks = times_not_out = 0
        else:
            matches = wins = runs = hs = balls_faced = wickets = sixes = fours = 0
            hundreds = fifties = ducks = best_w = best_r = dots = balls_bowled = mom = fifer = 0
            win_streak = hat_tricks = times_not_out = 0
    else:
        matches, wins, runs, hs, balls_faced, wickets, sixes, fours, hundreds, fifties, ducks, best_w, best_r, dots, balls_bowled, win_streak, hat_tricks, mom, fifer, times_not_out = db_row

    # ── PRIMARY: always prefer in-memory player_stats["team"] (most up-to-date) ──
    mem_team = player_stats.get(user_id, {}).get("team", {})
    if mem_team.get("matches", 0) > 0:
        matches     = mem_team.get("matches", mem_team.get("matches_played", matches))
        wins        = mem_team.get("wins", wins)
        runs        = mem_team.get("runs", runs)
        hs          = mem_team.get("highest", hs)
        balls_faced = mem_team.get("balls", balls_faced)
        wickets     = mem_team.get("wickets", wickets)
        sixes       = mem_team.get("sixes", sixes)
        fours       = mem_team.get("fours", fours)
        hundreds    = mem_team.get("centuries", hundreds)
        fifties     = mem_team.get("fifties", fifties)
        ducks       = mem_team.get("ducks", ducks)
        best_w      = mem_team.get("best_bowling_wickets", best_w)
        best_r      = mem_team.get("best_bowling_runs", best_r)
        dots        = mem_team.get("dots", dots)
        balls_bowled= mem_team.get("balls_bowled", balls_bowled)
        win_streak  = mem_team.get("win_streak", win_streak)
        hat_tricks  = mem_team.get("hat_tricks", hat_tricks)
        mom         = mem_team.get("mom", mom)
        fifer       = mem_team.get("five_wicket_hauls", fifer)
        times_not_out = mem_team.get("times_not_out", times_not_out)
        runs_conceded = mem_team.get("runs_conceded", 0)
        d_bowled    = mem_team.get("dismissals_bowled", player_stats.get(user_id, {}).get("dismissals_bowled", 0))
        d_lbw       = mem_team.get("dismissals_lbw", player_stats.get(user_id, {}).get("dismissals_lbw", 0))
        d_caught    = mem_team.get("dismissals_caught", player_stats.get(user_id, {}).get("dismissals_caught", 0))
        catches_taken = mem_team.get("catches_taken", player_stats.get(user_id, {}).get("catches_taken", 0))
    else:
        runs_conceded = 0

    if matches == 0:
        text = (
            f"👥 <b>{user_name}'s TEAM STATS</b>\n{SEP}\n"
            "🏟️ <i>No team matches played yet!</i>\n"
            "Join a team match to get started. 🏏"
        )
    else:
        # Batting metrics
        inns_bat = matches - ducks
        avg = round(runs / max(inns_bat, 1), 2)
        sr  = round((runs / max(balls_faced, 1)) * 100, 2)
        win_rate = round((wins / matches) * 100, 1)
        losses = matches - wins
        # Bowling metrics
        eco = round((runs_conceded / max(balls_bowled, 1)) * 6, 2) if balls_bowled > 0 else "→"
        bowl_avg = round(runs_conceded / max(wickets, 1), 2) if wickets > 0 else "→"
        # overs text
        overs_text = format_overs(balls_bowled)
        # Recent form → W/L results (last 5 matches)
        _form_results = mem_team.get("last_5_results", player_stats.get(user_id, {}).get("last_5_results", []))
        if _form_results:
            _form_dots = ""
            for _r in _form_results:
                _form_dots += "🟢" if _r == "W" else "🔴"
            _form_bar = f"{_form_dots}  <i>({'  '.join(_form_results)})</i>"
        else:
            # Fallback: score-based bar
            _form_s = player_stats.get(user_id, {}).get("last_5_scores", [])
            _form_bar = ""
            for _sc in _form_s[-5:]:
                _form_bar += "🟩" if _sc >= 50 else "🟡" if _sc >= 20 else "🔴" if _sc == 0 else "🟠"
            _form_bar = _form_bar or "→"

        # Captaincy stats
        cap_matches = mem_team.get("cap_matches", mem_team.get("captain_matches", 0))
        cap_wins    = mem_team.get("cap_wins", mem_team.get("captain_wins", 0))
        cap_rate    = round((cap_wins / max(cap_matches, 1)) * 100, 1) if cap_matches > 0 else 0
        best_bowl   = f"{best_w}/{best_r}" if best_w else "N/A"
        bat_sr      = sr
        bat_avg     = avg
        highest     = hs

        _ccc_row = get_player_ccc_rank(user_id)
        if _ccc_row:
            _ccc_cat = _ccc_row.get('category', 'Batsman')
            _ccc_cat_emoji = '🏏' if _ccc_cat == 'Batsman' else '⚾' if _ccc_cat == 'Bowler' else '🏏⚾'
            _ccc_cat_rank = _ccc_row.get('cat_rank', _ccc_row['rank'])
            ccc_line = f"├👑 𝗖𝗖𝗖     ➜ {_ccc_cat} {_ccc_cat_emoji} | #{_ccc_cat_rank} ⭐ {_ccc_row['rating']}\n"
        else:
            ccc_line = f"├👑 𝗖𝗖𝗖     ➜ Unranked\n"

        player_role = compute_player_role(user_id)
        role_line = f"├🎭 𝗥𝗼𝗹𝗲     ➜ {player_role}\n"

        jersey_num = user_data.get(user_id, {}).get("jersey_number")
        jersey_line = f"#{jersey_num}" if jersey_num is not None else "—"

        # Recent form dots only (most recent last, same order as before)
        _form_results = mem_team.get("last_5_results", player_stats.get(user_id, {}).get("last_5_results", []))
        if _form_results:
            form_dots = "".join("🟢" if r == "W" else "🔴" for r in _form_results)
        else:
            _form_s = player_stats.get(user_id, {}).get("last_5_scores", [])[-5:]
            form_dots = "".join("🟢" if s >= 50 else "🟡" if s >= 20 else "🔴" if s == 0 else "🟠" for s in _form_s) or "—"

        BAR = "────────────────────"

        text = (
            f"👤 𝗣𝗟𝗔𝗬𝗘𝗥 𝗣𝗥𝗢𝗙𝗜𝗟𝗘\n"
            f"┌{BAR}\n"
            f"├🆔 𝗜𝗗      ➜ {user_id}\n"
            f"├👤 𝗡𝗮𝗺𝗲    ➜ {html.escape(user_name)}\n"
            f"├🎽 𝗝𝗲𝗿𝘀𝗲𝘆  ➜ {jersey_line}\n"
            f"{role_line}"
            f"{ccc_line}"
            f"└{BAR}\n\n"
            f"📊 𝗖𝗔𝗥𝗘𝗘𝗥 𝗥𝗘𝗖𝗢𝗥𝗗\n"
            f"┌{BAR}\n"
            f"├ 🎮 Matches      ➜ {matches}\n"
            f"├ ✅ Wins         ➜ {wins}\n"
            f"├ ❌ Losses       ➜ {losses}\n"
            f"├ 👑 Captaincy    ➜ {cap_wins}/{cap_matches} ({cap_rate}%)\n"
            f"├ 🏅 MOTM         ➜ {mom}\n"
            f"├ 🔥 Recent Form  ➜ {form_dots}\n"
            f"└{BAR}\n\n"
            f"🏏 𝗕𝗔𝗧𝗧𝗜𝗡𝗚 𝗦𝗧𝗔𝗧𝗦\n"
            f"┌{BAR}\n"
            f"├ 🏏 Runs         ➜ {runs}\n"
            f"├ 🥎 Balls        ➜ {balls_faced}\n"
            f"├ 📈 Average      ➜ {bat_avg}\n"
            f"├ ⚡ Strike Rate  ➜ {bat_sr}\n"
            f"├ 🎯 Highest      ➜ {highest}\n"
            f"├ 💥 Fours        ➜ {fours}\n"
            f"├ 🚀 Sixes        ➜ {sixes}\n"
            f"├ ✨ Half Cent.   ➜ {fifties}\n"
            f"├ 💯 Centuries    ➜ {hundreds}\n"
            f"└{BAR}\n\n"
            f"🥎 𝗕𝗢𝗪𝗟𝗜𝗡𝗚 𝗦𝗧𝗔𝗧𝗦\n"
            f"┌{BAR}\n"
            f"├ 🎯 Wickets      ➜ {wickets}\n"
            f"├ ⏳ Overs        ➜ {overs_text}\n"
            f"├ 📉 Economy      ➜ {eco}\n"
            f"├ 📊 Average      ➜ {bowl_avg}\n"
            f"├ 💎 Best Figures ➜ {best_bowl}\n"
            f"├ 🎩 Hat-tricks   ➜ {hat_tricks}\n"
            f"├ 🔥 5-Wickets    ➜ {fifer}\n"
            f"└{BAR}\n\n"
            f"🧤 𝗙𝗜𝗘𝗟𝗗𝗜𝗡𝗚 & 𝗗𝗜𝗦𝗠𝗜𝗦𝗦𝗔𝗟𝗦\n"
            f"┌{BAR}\n"
            f"├ 🎯 Bowled Out   ➜ {d_bowled}\n"
            f"├ ☝️ LBW Out      ➜ {d_lbw}\n"
            f"├ 🧤 Caught Out   ➜ {d_caught}\n"
            f"├ 🤲 Catches Taken➜ {catches_taken}\n"
            f"└{BAR}"
        )

    return text


def fetch_team_stats_for_card(user_id: int) -> dict:
    """Fetch team stats in the same dict shape generate_stats_image expects."""
    conn= db_connect(DB_PATH)
    c = conn.cursor()
    c.execute("""
        SELECT team_matches_played, team_matches_won, team_total_runs, team_highest_score,
               team_total_balls_faced, team_total_wickets, team_total_fifties, team_total_hundreds
        FROM user_stats WHERE user_id = ?
    """, (user_id,))
    row = c.fetchone()
    conn.close()

    matches = wins = runs = hs = balls = wickets = fifties = hundreds = 0
    if row and row[0]:
        matches, wins, runs, hs, balls, wickets, fifties, hundreds = row

    mem_team = player_stats.get(user_id, {}).get("team", {})
    if mem_team.get("matches", 0) > 0:
        matches  = mem_team.get("matches", matches)
        wins     = mem_team.get("wins", wins)
        runs     = mem_team.get("runs", runs)
        hs       = mem_team.get("highest", hs)
        balls    = mem_team.get("balls", balls)
        wickets  = mem_team.get("wickets", wickets)
        fifties  = mem_team.get("fifties", fifties)
        hundreds = mem_team.get("centuries", hundreds)

    sr = round((runs / balls * 100), 2) if balls > 0 else 0.0
    win_rate = round((wins / matches * 100), 1) if matches > 0 else 0.0

    return {
        "matches": matches, "wins": wins, "losses": max(matches - wins, 0),
        "win_rate": win_rate, "runs": runs, "highest": hs, "balls": balls,
        "wickets": wickets, "fifties": fifties, "hundreds": hundreds,
        "strike_rate": sr,
    }


# ═══════════════════════════════════════════════════════════════
# ⚔️ HEAD TO HEAD (/h2h) — Team Mode player comparison card
# ═══════════════════════════════════════════════════════════════

H2H_STAT_ROWS = [
    # (label, stats_key, formatter)
    ("Matches",       "matches",     lambda v: str(v)),
    ("Wins",          "wins",        lambda v: str(v)),
    ("Win Rate",      "win_rate",    lambda v: f"{v:.1f}%"),
    ("Runs",          "runs",        lambda v: str(v)),
    ("Highest Score", "highest",     lambda v: str(v)),
    ("Strike Rate",   "strike_rate", lambda v: f"{v:.1f}%"),
    ("Wickets",       "wickets",     lambda v: str(v)),
    ("Fifties",       "fifties",     lambda v: str(v)),
    ("Hundreds",      "hundreds",    lambda v: str(v)),
]


def _h2h_verdict_text(name1: str, stats1: dict, name2: str, stats2: dict) -> Tuple[str, int, int]:
    """Count category wins for each player (higher value wins each category)."""
    score1 = score2 = 0
    for _, key, _ in H2H_STAT_ROWS:
        v1, v2 = stats1.get(key, 0), stats2.get(key, 0)
        if v1 > v2:
            score1 += 1
        elif v2 > v1:
            score2 += 1
    if score1 == score2:
        return ("🤝 <b>It's a Dead Heat!</b> Both players are evenly matched.", score1, score2)
    winner = name1 if score1 > score2 else name2
    win_score, lose_score = max(score1, score2), min(score1, score2)
    return (
        f"🏆 <b>{html.escape(winner)} wins the Head-to-Head!</b> "
        f"({win_score}-{lose_score})",
        score1, score2
    )


def _h2h_caption_stats_block(name1: str, stats1: dict, name2: str, stats2: dict) -> str:
    """Build a neatly aligned monospace stat table for the caption (inside <pre>),
    with 🔥 marking whichever player leads that row."""
    n1 = (name1 or "P1").split()[0][:9]
    n2 = (name2 or "P2").split()[0][:9]

    LABEL_W, VAL_W = 13, 9
    lines = [f"{'STAT':<{LABEL_W}}{n1:>{VAL_W}}{n2:>{VAL_W}}"]
    lines.append("─" * (LABEL_W + VAL_W * 2))

    for label, key, fmt in H2H_STAT_ROWS:
        v1, v2 = stats1.get(key, 0), stats2.get(key, 0)
        s1, s2 = fmt(v1), fmt(v2)
        if v1 > v2:
            s1 = "🔥" + s1
        elif v2 > v1:
            s2 = "🔥" + s2
        lines.append(f"{label:<{LABEL_W}}{s1:>{VAL_W}}{s2:>{VAL_W}}")

    table = "\n".join(lines)
    return f"📊 <b>TEAM MODE STATS</b>\n<pre>{table}</pre>"


def _h2h_category_bar(name1: str, score1: int, name2: str, score2: int, total: int) -> str:
    """Small visual bar showing how many stat-categories each player leads."""
    n1 = html.escape((name1 or "P1")[:14])
    n2 = html.escape((name2 or "P2")[:14])
    bar1 = "🟩" * score1 + "⬜" * (total - score1)
    bar2 = "🟦" * score2 + "⬜" * (total - score2)
    return (
        f"📈 <b>Categories Won</b>\n"
        f"{n1}: {bar1}  <b>{score1}</b>\n"
        f"{n2}: {bar2}  <b>{score2}</b>"
    )


H2H_TEMPLATE_CANDIDATES = ["h2h_template.png", "/home/cricoverse/h2h_template.png"]

# Pixel-measured positions on the h2h_template.png reference card (native 1536x1024):
H2H_TPL_LEFT_CX, H2H_TPL_LEFT_CY   = 385, 505
H2H_TPL_RIGHT_CX, H2H_TPL_RIGHT_CY = 1150, 505
H2H_TPL_CIRCLE_R = 195
H2H_TPL_LEFT_BOX  = (214, 741, 557, 818)
H2H_TPL_RIGHT_BOX = (978, 741, 1319, 818)


def _render_h2h_image_from_template(
    template_path: str,
    name1: str, uname1: str, avatar1_bytes: Optional[bytes],
    name2: str, uname2: str, avatar2_bytes: Optional[bytes],
) -> Optional[BytesIO]:
    """Overlay pfp + username onto the branded h2h_template.png card."""
    base = Image.open(template_path).convert("RGBA")
    Wt, Ht = base.size
    # Positions were measured on a 1536x1024 reference; scale if the
    # actual template file is a different resolution.
    sx, sy = Wt / 1536.0, Ht / 1024.0

    overlay = Image.new("RGBA", (Wt, Ht), (0, 0, 0, 0))
    draw = ImageDraw.Draw(overlay)

    def paste_avatar(cx, cy, r, avatar_bytes, initials):
        size = max(int(r * 2), 2)
        hq = size * 3  # render at 3x then downsample for crisp edges
        av = _create_avatar_image(avatar_bytes, hq, initials)
        av = av.resize((size, size), Image.Resampling.LANCZOS)
        overlay.alpha_composite(av, (int(cx - size / 2), int(cy - size / 2)))

    paste_avatar(H2H_TPL_LEFT_CX * sx, H2H_TPL_LEFT_CY * sy, H2H_TPL_CIRCLE_R * min(sx, sy),
                 avatar1_bytes, (name1 or "P1")[:2].upper())
    paste_avatar(H2H_TPL_RIGHT_CX * sx, H2H_TPL_RIGHT_CY * sy, H2H_TPL_CIRCLE_R * min(sx, sy),
                 avatar2_bytes, (name2 or "P2")[:2].upper())

    base_font_size = 30 * min(sx, sy)
    uname_font_size = 20 * min(sx, sy)
    f_name  = _get_font(True, max(int(base_font_size), 10))
    f_uname = _get_font(False, max(int(uname_font_size), 8))
    DARK = (10, 60, 60, 255)
    GRAY = (95, 105, 105, 255)

    def draw_box_text(box, name, username):
        x0, y0, x1, y1 = [v * (sx if i % 2 == 0 else sy) for i, v in enumerate(box)]
        cx = (x0 + x1) / 2
        nm = (name or "Player")[:16]
        un = (username or "")[:20]
        nb = draw.textbbox((0, 0), nm, font=f_name)
        nh = nb[3] - nb[1]
        ub = draw.textbbox((0, 0), un, font=f_uname)
        uh = ub[3] - ub[1]
        gap = 6 * min(sx, sy)
        total_h = nh + uh + gap
        top = y0 + ((y1 - y0) - total_h) / 2
        draw.text((cx - (nb[2] - nb[0]) / 2, top - nb[1]), nm, font=f_name, fill=DARK)
        draw.text((cx - (ub[2] - ub[0]) / 2, top + nh + gap - ub[1]), un, font=f_uname, fill=GRAY)

    draw_box_text(H2H_TPL_LEFT_BOX, name1, uname1)
    draw_box_text(H2H_TPL_RIGHT_BOX, name2, uname2)

    final = Image.alpha_composite(base, overlay).convert("RGB")
    bio = BytesIO()
    final.save(bio, "JPEG", quality=95)
    bio.seek(0)
    return bio


def _render_h2h_image(
    id1: int, name1: str, uname1: str, stats1: dict, avatar1_bytes: Optional[bytes],
    id2: int, name2: str, uname2: str, stats2: dict, avatar2_bytes: Optional[bytes],
) -> Optional[BytesIO]:
    """Blocking PIL work for the /h2h card. Uses the branded h2h_template.png if
    present (pfp + username overlaid onto the two circles/boxes), otherwise
    falls back to a fully-drawn card. Always call via asyncio.to_thread."""
    template_path = next((p for p in H2H_TEMPLATE_CANDIDATES if os.path.exists(p)), None)
    if template_path:
        try:
            return _render_h2h_image_from_template(
                template_path, name1, uname1, avatar1_bytes, name2, uname2, avatar2_bytes
            )
        except Exception as e:
            logger.error(f"H2H template render failed, using fallback: {e}")

    return _render_h2h_image_fallback(
        id1, name1, uname1, stats1, avatar1_bytes,
        id2, name2, uname2, stats2, avatar2_bytes,
    )


def _render_h2h_image_fallback(
    id1: int, name1: str, uname1: str, stats1: dict, avatar1_bytes: Optional[bytes],
    id2: int, name2: str, uname2: str, stats2: dict, avatar2_bytes: Optional[bytes],
) -> Optional[BytesIO]:
    """Fully programmatic PIL card, used only if h2h_template.png is missing.
    All stat comparison lives in the caption text, not the image."""
    try:
        SCALE = 2  # supersample for crisp text/edges, downscale at the end
        W = 1200
        H = 640

        Wc, Hc = W * SCALE, H * SCALE
        base = Image.new("RGBA", (Wc, Hc), (255, 255, 255, 255))
        draw = ImageDraw.Draw(base)

        TEAL_DARK   = (10, 74, 74, 255)
        TEAL        = (14, 110, 110, 255)
        TEAL_LIGHT  = (224, 244, 244, 255)
        WHITE       = (255, 255, 255, 255)
        GOLD        = (255, 196, 60, 255)
        GRAY        = (110, 120, 120, 255)
        DARK_TXT    = (20, 40, 40, 255)

        # ── Outer border frame ──
        border = 10 * SCALE
        draw.rounded_rectangle(
            [border // 2, border // 2, Wc - border // 2, Hc - border // 2],
            radius=28 * SCALE, outline=TEAL, width=border
        )

        HEADER_H = 210
        # ── Header band ──
        for y in range(HEADER_H * SCALE):
            t = y / max(HEADER_H * SCALE - 1, 1)
            r = int(TEAL_DARK[0] + (TEAL[0] - TEAL_DARK[0]) * t)
            g = int(TEAL_DARK[1] + (TEAL[1] - TEAL_DARK[1]) * t)
            b = int(TEAL_DARK[2] + (TEAL[2] - TEAL_DARK[2]) * t)
            draw.line([(border, y), (Wc - border, y)], fill=(r, g, b, 255))

        f_logo   = _get_font(True, 24 * SCALE)
        f_title  = _get_font(True, 56 * SCALE)
        f_sub    = _get_font(False, 20 * SCALE)
        f_name   = _get_font(True, 32 * SCALE)
        f_uname  = _get_font(False, 22 * SCALE)
        f_vs     = _get_font(True, 46 * SCALE)

        draw.text((36 * SCALE, 26 * SCALE), "CRICOVERSE", font=f_logo, fill=WHITE)
        title = "HEAD TO HEAD"
        tb = draw.textbbox((0, 0), title, font=f_title)
        draw.text(((Wc - (tb[2] - tb[0])) / 2, 55 * SCALE), title, font=f_title, fill=WHITE)
        sub = "TEAM MODE COMPARISON"
        sb = draw.textbbox((0, 0), sub, font=f_sub)
        draw.text(((Wc - (sb[2] - sb[0])) / 2, 135 * SCALE), sub, font=f_sub, fill=TEAL_LIGHT)

        # ── Avatar zone ──
        avatar_size = 260 * SCALE
        cy = HEADER_H * SCALE + 55 * SCALE + avatar_size // 2
        cx1 = Wc // 4
        cx2 = Wc - Wc // 4

        av1 = _create_avatar_image(avatar1_bytes, avatar_size, (name1 or "P1")[:2].upper())
        av2 = _create_avatar_image(avatar2_bytes, avatar_size, (name2 or "P2")[:2].upper())

        ring_pad = 8 * SCALE
        for (cx, av) in [(cx1, av1), (cx2, av2)]:
            ring_box = [cx - avatar_size // 2 - ring_pad, cy - avatar_size // 2 - ring_pad,
                        cx + avatar_size // 2 + ring_pad, cy + avatar_size // 2 + ring_pad]
            draw.ellipse(ring_box, outline=TEAL, width=6 * SCALE, fill=(245, 248, 248, 255))
            base.alpha_composite(av, (cx - avatar_size // 2, cy - avatar_size // 2))

        # VS badge in the middle
        vs_r = 46 * SCALE
        vs_cx, vs_cy = Wc // 2, cy
        draw.ellipse([vs_cx - vs_r, vs_cy - vs_r, vs_cx + vs_r, vs_cy + vs_r], fill=TEAL_DARK)
        vb = draw.textbbox((0, 0), "VS", font=f_vs)
        draw.text((vs_cx - (vb[2] - vb[0]) / 2, vs_cy - (vb[3] - vb[1]) / 2 - vb[1]), "VS", font=f_vs, fill=GOLD)

        # Names + usernames under avatars, inside a rounded box (like the template)
        name_y = cy + avatar_size // 2 + ring_pad + 30 * SCALE
        box_w, box_h = 320 * SCALE, 90 * SCALE
        for cx, nm, un in [(cx1, name1, uname1), (cx2, name2, uname2)]:
            box = [cx - box_w // 2, name_y, cx + box_w // 2, name_y + box_h]
            draw.rounded_rectangle(box, radius=14 * SCALE, outline=TEAL, width=4 * SCALE, fill=(255, 255, 255, 255))
            nm_disp = (nm or "Player")[:16]
            nb = draw.textbbox((0, 0), nm_disp, font=f_name)
            draw.text((cx - (nb[2] - nb[0]) / 2, name_y + 14 * SCALE), nm_disp, font=f_name, fill=DARK_TXT)
            un_disp = (un or "")[:20]
            ub = draw.textbbox((0, 0), un_disp, font=f_uname)
            draw.text((cx - (ub[2] - ub[0]) / 2, name_y + 52 * SCALE), un_disp, font=f_uname, fill=GRAY)

        final = base.resize((W, H), Image.Resampling.LANCZOS).convert("RGB")
        bio = BytesIO()
        final.save(bio, "JPEG", quality=95)
        bio.seek(0)
        return bio
    except Exception as e:
        logger.error("H2H image generation error: " + str(e))
        return None


async def generate_h2h_image(
    id1: int, name1: str, uname1: str, stats1: dict, avatar1_bytes: Optional[bytes],
    id2: int, name2: str, uname2: str, stats2: dict, avatar2_bytes: Optional[bytes],
) -> Optional[BytesIO]:
    """Non-blocking wrapper for _render_h2h_image (runs PIL work in a thread)."""
    return await asyncio.to_thread(
        _render_h2h_image,
        id1, name1, uname1, stats1, avatar1_bytes,
        id2, name2, uname2, stats2, avatar2_bytes,
    )


async def h2h_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """⚔️ /h2h — Head-to-Head Team Mode comparison card between two players.

    Usage:
      /h2h @user1 @user2
      /h2h <user1_id> <user2_id>
      (reply to a player's message) /h2h @user2
      (reply to a player's message) /h2h <user2_id>
    A reply always fills Player 1 first; the mention/ID given fills Player 2.
    """
    message = update.message
    resolved: List[Tuple[int, str, Optional[str]]] = []

    async def _resolve_from_username(raw_username: str):
        username = raw_username.lstrip("@")
        if not username:
            return None
        try:
            chat = await context.bot.get_chat(f"@{username}")
            return (chat.id, (chat.first_name or chat.title or username), (chat.username or username))
        except Exception:
            pass
        for uid, data in user_data.items():
            if (data.get("username") or "").lower() == username.lower():
                return (int(uid), data.get("first_name", "Player"), data.get("username", username))
        return None

    async def _resolve_from_id(uid_str: str):
        try:
            uid = int(uid_str)
        except ValueError:
            return None
        stored = user_data.get(uid, {})
        name = stored.get("first_name")
        username = stored.get("username")
        if not name:
            try:
                chat = await context.bot.get_chat(uid)
                name = chat.first_name or chat.title or f"Player_{uid}"
                username = chat.username or username
            except Exception:
                name = f"Player_{uid}"
        return (uid, name, username)

    # 1) Reply → Player 1
    if message.reply_to_message and message.reply_to_message.from_user:
        ru = message.reply_to_message.from_user
        resolved.append((ru.id, ru.first_name or "Player", ru.username))

    # 2) @mentions / text_mentions from the command text
    if message.entities:
        for entity in message.entities:
            if len(resolved) >= 2:
                break
            if entity.type == "text_mention" and entity.user:
                u = entity.user
                resolved.append((u.id, u.first_name or "Player", u.username))
            elif entity.type == "mention":
                username = message.text[entity.offset:entity.offset + entity.length]
                r = await _resolve_from_username(username)
                if r:
                    resolved.append(r)

    # 3) Numeric user IDs among the args
    if len(resolved) < 2 and context.args:
        for arg in context.args:
            if len(resolved) >= 2:
                break
            if arg.startswith("@"):
                continue  # handled via entities above
            if arg.isdigit():
                r = await _resolve_from_id(arg)
                if r:
                    resolved.append(r)

    # de-duplicate, preserve order
    seen: Set[int] = set()
    unique = []
    for r in resolved:
        if r[0] not in seen:
            unique.append(r)
            seen.add(r[0])
    resolved = unique

    if len(resolved) < 2:
        await message.reply_text(
            "⚔️ <b>HEAD TO HEAD — Usage</b>\n"
            "─────────────────\n"
            "• <code>/h2h @user1 @user2</code>\n"
            "• <code>/h2h user1_id user2_id</code>\n"
            "• Reply to a player's message with <code>/h2h @user2</code>\n"
            "  or <code>/h2h user2_id</code> — the replied-to player\n"
            "  becomes Player 1 automatically.\n"
            "─────────────────\n"
            "<i>Compares Team Mode stats only.</i>",
            parse_mode=ParseMode.HTML
        )
        return

    (id1, name1, uname1), (id2, name2, uname2) = resolved[0], resolved[1]

    if id1 == id2:
        await message.reply_text("⚔️ A player can't go Head-to-Head with themselves!")
        return

    if update.effective_chat.type != "private":
        remaining = check_image_cooldown(update.effective_chat.id)
        if remaining is not None:
            await send_cooldown_warning(update, remaining)
            return

    wait_msg = None
    try:
        wait_msg = await message.reply_text("⚔️ <b>Generating Head-to-Head card...</b>", parse_mode=ParseMode.HTML)
    except Exception:
        pass

    stats1 = fetch_team_stats_for_card(id1)
    stats2 = fetch_team_stats_for_card(id2)

    avatar1, avatar2 = await asyncio.gather(
        fetch_user_avatar_bytes(context, id1),
        fetch_user_avatar_bytes(context, id2),
    )

    uname1_disp = f"@{uname1}" if uname1 else "No Username"
    uname2_disp = f"@{uname2}" if uname2 else "No Username"

    bio = await generate_h2h_image(
        id1, name1, uname1_disp, stats1, avatar1,
        id2, name2, uname2_disp, stats2, avatar2,
    )

    if wait_msg is not None:
        try:
            await wait_msg.delete()
        except Exception:
            pass

    if bio is None:
        await message.reply_text("⚠️ Couldn't generate the Head-to-Head card. Try again!")
        return

    verdict_text, sc1, sc2 = _h2h_verdict_text(name1, stats1, name2, stats2)
    stats_block = _h2h_caption_stats_block(name1, stats1, name2, stats2)
    category_bar = _h2h_category_bar(name1, sc1, name2, sc2, len(H2H_STAT_ROWS))
    caption = (
        f"⚔️ <b>HEAD TO HEAD</b>\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"👤 {format_name_with_jersey(id1, name1)}  🆚  {format_name_with_jersey(id2, name2)}\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"{stats_block}\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"{category_bar}\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"{verdict_text}"
    )

    bio.name = "h2h.jpg"
    await message.reply_photo(photo=bio, caption=caption, parse_mode=ParseMode.HTML)
    if update.effective_chat.type != "private":
        set_image_cooldown(update.effective_chat.id)


async def jersey_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎽 /jersey <number> — Set your personal jersey number (1-999), shown on profile & squads."""
    user = update.effective_user
    user_id = user.id

    if not context.args:
        current = user_data.get(user_id, {}).get("jersey_number")
        if current is not None:
            await update.message.reply_text(
                f"🎽 <b>Your Jersey Number:</b> #{current}\n"
                f"<i>Use /jersey <number> (0-999) to change it.</i>",
                parse_mode=ParseMode.HTML
            )
        else:
            await update.message.reply_text(
                "🎽 <b>Set Your Jersey Number!</b>\n"
                "─────────────────\n"
                "Usage: <code>/jersey [number]</code>\n"
                "<i>Pick any number between 0-999.</i>",
                parse_mode=ParseMode.HTML
            )
        return

    raw = context.args[0].strip()
    if not raw.isdigit() or not (0 <= int(raw) <= 999):
        await update.message.reply_text(
            "⚠️ Please pick a valid jersey number between <b>0</b> and <b>999</b>.\n"
            "Usage: <code>/jersey 7</code>",
            parse_mode=ParseMode.HTML
        )
        return

    number = int(raw)

    # 🎽 Ensure this number isn't already taken by someone else
    holder_id = find_user_id_by_jersey(number)
    if holder_id is not None and holder_id != user_id:
        holder_data = user_data.get(holder_id, {})
        holder_name = holder_data.get("first_name", "another player")
        holder_tag = f'<a href="tg://user?id={holder_id}">{html.escape(holder_name)}</a>'

        nearby_free = find_nearby_free_jersey_numbers(number)
        nearby_line = ""
        if nearby_free:
            nearby_line = "🆓 <b>Free nearby:</b> " + ", ".join(f"#{n}" for n in nearby_free) + "\n"

        keyboard_rows = [[
            styled_button("🔁 Request Swap", callback_data=f"jswap_req_{holder_id}_{number}")
        ]]
        if nearby_free:
            keyboard_rows.append([
                styled_button(f"🎽 Take #{n}", callback_data=f"jersey_take_{n}") for n in nearby_free[:3]
            ])
        keyboard_rows.append([
            styled_button("🔔 Notify me when free", callback_data=f"jersey_notify_{number}")
        ])
        keyboard = InlineKeyboardMarkup(keyboard_rows)
        await update.message.reply_text(
            f"🚫 <b>Number Taken!</b>\n"
            f"─────────────────\n"
            f"🎽 #{number} is already worn by {holder_tag}.\n"
            f"{nearby_line}"
            f"<i>Pick a free number above, send a swap request, or get notified when #{number} opens up.</i>",
            parse_mode=ParseMode.HTML,
            reply_markup=keyboard
        )
        return

    # Ensure user profile exists (edge case: /jersey before any /start)
    if user_id not in user_data:
        user_data[user_id] = {
            "user_id": user_id,
            "username": user.username or "",
            "first_name": user.first_name,
            "started_at": datetime.now().isoformat(),
            "total_matches": 0
        }
        init_player_stats(user_id)

    user_data[user_id]["jersey_number"] = number
    user_data[user_id]["jersey_last_active"] = datetime.now().isoformat()
    user_data[user_id]["jersey_warned_at"] = None
    save_data()

    await update.message.reply_text(
        f"✅ <b>Jersey Number Set!</b>\n"
        f"─────────────────\n"
        f"🎽 <b>#{number}</b> — {html.escape(user.first_name)}\n"
        f"<i>This will show up on your profile & squad lineups.</i>",
        parse_mode=ParseMode.HTML
    )


async def jersey_inactivity_job(context: ContextTypes.DEFAULT_TYPE):
    """🎽 Runs daily. Frees up jersey numbers from players inactive for 90+ days,
    so popular numbers (7, 10, 18, 1...) don't get locked forever.
    DMs a warning at 60 days of inactivity, then releases the number at 90 days."""
    now = datetime.now()
    changed = False

    for uid, data in list(user_data.items()):
        number = data.get("jersey_number")
        if number is None:
            continue

        last_active_raw = data.get("jersey_last_active")
        if last_active_raw:
            try:
                last_active = datetime.fromisoformat(last_active_raw)
            except Exception:
                last_active = data.get("started_at")
                last_active = datetime.fromisoformat(last_active) if last_active else now
        else:
            # No activity recorded yet — fall back to when they joined, or set it now
            started_raw = data.get("started_at")
            if started_raw:
                try:
                    last_active = datetime.fromisoformat(started_raw)
                except Exception:
                    last_active = now
            else:
                last_active = now
            data["jersey_last_active"] = last_active.isoformat()
            changed = True

        days_inactive = (now - last_active).days

        if days_inactive >= JERSEY_RETIRE_DAYS:
            # 🚫 Release the number
            data["jersey_number"] = None
            data["jersey_warned_at"] = None
            changed = True
            try:
                await context.bot.send_message(
                    chat_id=uid,
                    text=(
                        f"🎽 <b>Jersey Number Released</b>\n"
                        f"─────────────────\n"
                        f"Your number <b>#{number}</b> has been released after "
                        f"{JERSEY_RETIRE_DAYS}+ days of inactivity.\n"
                        f"<i>Play a match and grab a new number anytime with /jersey.</i>"
                    ),
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass
            try:
                await notify_jersey_now_free(context, number)
            except Exception:
                pass
            # ⚠️ Send a one-time warning DM
            data["jersey_warned_at"] = now.isoformat()
            changed = True
            days_left = JERSEY_RETIRE_DAYS - days_inactive
            try:
                await context.bot.send_message(
                    chat_id=uid,
                    text=(
                        f"⚠️ <b>Your Jersey Number May Be Released Soon</b>\n"
                        f"─────────────────\n"
                        f"You've been inactive for {days_inactive} days and your number "
                        f"<b>#{number}</b> will be released in about {days_left} days if "
                        f"you don't play a match.\n"
                        f"<i>Stay active to keep it!</i>"
                    ),
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass

    if changed:
        save_data()


async def jersey_swap_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔁 Handles jersey swap request/accept/decline flow.
    Callback data formats:
      jswap_req_{holder_id}_{number}      -> requester wants holder's number
      jswap_yes_{requester_id}_{number}   -> holder accepts (DM button)
      jswap_no_{requester_id}_{number}    -> holder declines (DM button)
    """
    query = update.callback_query
    requester = query.from_user
    parts = query.data.split("_")
    action = parts[1]  # req / yes / no

    if action == "req":
        holder_id = int(parts[2])
        number = int(parts[3])
        requester_id = requester.id

        if requester_id == holder_id:
            await query.answer("You already own this number!", show_alert=True)
            return

        # Requester must currently hold a jersey number themselves to swap
        my_number = user_data.get(requester_id, {}).get("jersey_number")

        # ── One swap request per requester per day ──
        last_req_at = user_data.get(requester_id, {}).get("jersey_last_swap_request_at")
        if last_req_at:
            try:
                elapsed_hours = (datetime.now() - datetime.fromisoformat(last_req_at)).total_seconds() / 3600
            except Exception:
                elapsed_hours = JERSEY_SWAP_COOLDOWN_HOURS
            if elapsed_hours < JERSEY_SWAP_COOLDOWN_HOURS:
                remaining_h = round(JERSEY_SWAP_COOLDOWN_HOURS - elapsed_hours, 1)
                await query.answer(
                    f"You can only send 1 swap request per day. Try again in ~{remaining_h}h.",
                    show_alert=True
                )
                return

        # Verify the number is still held by holder_id
        current_holder = find_user_id_by_jersey(number)
        if current_holder != holder_id:
            await query.answer("That number is no longer held by them. Try /jersey again.", show_alert=True)
            return

        if requester_id not in user_data:
            user_data[requester_id] = {
                "user_id": requester_id,
                "username": requester.username or "",
                "first_name": requester.first_name,
                "started_at": datetime.now().isoformat(),
                "total_matches": 0
            }
            init_player_stats(requester_id)

        user_data[requester_id]["jersey_last_swap_request_at"] = datetime.now().isoformat()
        save_data()

        await query.answer("Swap request sent! Waiting for their confirmation.", show_alert=True)

        requester_tag = f'<a href="tg://user?id={requester_id}">{html.escape(requester.first_name)}</a>'
        my_number_text = f"#{my_number}" if my_number is not None else "no jersey number yet"
        dm_keyboard = InlineKeyboardMarkup([[
            styled_button("✅ Accept Swap", callback_data=f"jswap_yes_{requester_id}_{number}"),
            styled_button("❌ Decline", callback_data=f"jswap_no_{requester_id}_{number}")
        ]])
        try:
            await context.bot.send_message(
                chat_id=holder_id,
                text=(
                    f"🔁 <b>Jersey Swap Request!</b>\n"
                    f"─────────────────\n"
                    f"{requester_tag} wants your <b>🎽 #{number}</b>.\n"
                    f"They currently wear <b>{my_number_text}</b>, which would become yours if you accept.\n"
                    f"─────────────────\n"
                    f"<i>Confirm below to swap numbers.</i>"
                ),
                parse_mode=ParseMode.HTML,
                reply_markup=dm_keyboard
            )
        except Exception:
            await query.message.reply_text(
                "⚠️ Couldn't DM the number holder — ask them to start the bot in DM first.",
                parse_mode=ParseMode.HTML
            )
        return

    # ── Holder responding from their DM ──
    requester_id = int(parts[2])
    number = int(parts[3])
    holder_id = requester.id  # whoever tapped the button in their own DM

    if action == "no":
        try:
            await query.edit_message_text("❌ <b>Swap declined.</b>", parse_mode=ParseMode.HTML)
        except Exception:
            pass
        try:
            await context.bot.send_message(
                chat_id=requester_id,
                text=f"❌ Your swap request for 🎽 #{number} was declined.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return

    # action == "yes"
    current_holder = find_user_id_by_jersey(number)
    if current_holder != holder_id:
        await query.answer("You no longer hold this number.", show_alert=True)
        return

    requester_number = user_data.get(requester_id, {}).get("jersey_number")

    # Perform the swap
    user_data.setdefault(holder_id, {})["jersey_number"] = requester_number
    user_data[holder_id]["jersey_last_active"] = datetime.now().isoformat()
    user_data.setdefault(requester_id, {})["jersey_number"] = number
    user_data[requester_id]["jersey_last_active"] = datetime.now().isoformat()
    save_data()

    try:
        await query.edit_message_text(
            f"✅ <b>Swap complete!</b> You now wear "
            f"{'🎽 #' + str(requester_number) if requester_number else 'no number'}.",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass
    try:
        await context.bot.send_message(
            chat_id=requester_id,
            text=f"✅ <b>Swap complete!</b> You now wear 🎽 #{number}.",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass


async def jersey_notify_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔔 jersey_notify_{number} — subscribe to a one-time DM when that number frees up (1 week window)."""
    query = update.callback_query
    user = query.from_user
    number = int(query.data.split("_")[-1])

    if find_user_id_by_jersey(number) is None:
        await query.answer(f"#{number} is already free — grab it with /jersey {number}!", show_alert=True)
        return

    add_jersey_release_subscriber(number, user.id)
    save_data()
    await query.answer(f"🔔 You'll get a DM if #{number} frees up (valid for {JERSEY_NOTIFY_EXPIRY_DAYS} days).", show_alert=True)


async def jersey_take_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎽 jersey_take_{number} — one-tap claim of a suggested free number."""
