async def rmjersey_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🎽 /rmjersey <number> — Owner-only. DMs the current holder an activity check;
    if they don't confirm within JERSEY_OWNER_CHECK_DAYS, the number is auto-released."""
    user = update.effective_user
    if user.id != OWNER_ID:
        return

    if not context.args:
        await update.message.reply_text("Usage: <code>/rmjersey [number]</code>", parse_mode=ParseMode.HTML)
        return

    try:
        number = int(context.args[0])
    except ValueError:
        await update.message.reply_text("⚠️ Please give a valid jersey number.")
        return

    holder_id = find_user_id_by_jersey(number)
    if holder_id is None:
        await update.message.reply_text(f"🎽 No one is wearing #{number}.")
        return

    jersey_owner_checks[str(number)] = {
        "holder_id": holder_id,
        "requested_at": datetime.now().isoformat(),
        "requested_by": user.id,
    }
    save_data()

    keyboard = InlineKeyboardMarkup([[
        styled_button("✅ Yes, I'm active — keep my jersey", callback_data=f"jkeep_{number}")
    ]])
    try:
        await context.bot.send_message(
            chat_id=holder_id,
            text=(
                f"🎽 <b>Jersey Activity Check</b>\n"
                f"─────────────────\n"
                f"We noticed you might not be active anymore, so <b>#{number}</b> is under review.\n"
                f"If you're still around, tap below within <b>{JERSEY_OWNER_CHECK_DAYS} days</b> to keep it.\n"
                f"<i>No response in time and the number will be released.</i>"
            ),
            parse_mode=ParseMode.HTML,
            reply_markup=keyboard
        )
        await update.message.reply_text(f"📨 Activity check sent to the holder of #{number}. They have {JERSEY_OWNER_CHECK_DAYS} days to respond.")
    except Exception:
        await update.message.reply_text(f"⚠️ Couldn't DM the holder of #{number} — removing the number immediately instead.")
        await _release_jersey_number(context, number, notify_holder=False)
        jersey_owner_checks.pop(str(number), None)
        save_data()


async def jersey_keep_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✅ jkeep_{number} — holder confirms they're active, cancels the pending removal."""
    query = update.callback_query
    number = int(query.data.split("_")[-1])
    check = jersey_owner_checks.get(str(number))
    if not check or check.get("holder_id") != query.from_user.id:
        await query.answer("This check is no longer active.", show_alert=True)
        return

    jersey_owner_checks.pop(str(number), None)
    user_data.setdefault(query.from_user.id, {})["jersey_last_active"] = datetime.now().isoformat()
    save_data()
    await query.answer("✅ Confirmed — your jersey is safe!", show_alert=True)
    try:
        await query.edit_message_text(f"✅ <b>Confirmed active.</b> You keep 🎽 #{number}.", parse_mode=ParseMode.HTML)
    except Exception:
        pass


async def _release_jersey_number(context: ContextTypes.DEFAULT_TYPE, number: int, notify_holder: bool = True) -> None:
    """Clears jersey_number from whoever holds `number` and pings release subscribers."""
    holder_id = find_user_id_by_jersey(number)
    if holder_id is not None:
        user_data[holder_id]["jersey_number"] = None
        if notify_holder:
            try:
                await context.bot.send_message(
                    holder_id,
                    f"🎽 <b>Jersey #{number} removed</b> due to no response to the activity check.\n"
                    f"<i>Grab a new number anytime with /jersey.</i>",
                    parse_mode=ParseMode.HTML
                )
            except Exception:
                pass
    save_data()
    await notify_jersey_now_free(context, number)


async def jersey_owner_check_job(context: ContextTypes.DEFAULT_TYPE):
    """⏰ Runs periodically. Releases jersey numbers whose /rmjersey activity check
    went unanswered for JERSEY_OWNER_CHECK_DAYS."""
    now = datetime.now()
    for number_str, check in list(jersey_owner_checks.items()):
        try:
            requested_at = datetime.fromisoformat(check["requested_at"])
        except Exception:
            continue
        if (now - requested_at).days >= JERSEY_OWNER_CHECK_DAYS:
            number = int(number_str)
            await _release_jersey_number(context, number, notify_holder=True)
            jersey_owner_checks.pop(number_str, None)
            save_data()


async def mystats_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Interactive cricket stats → per-mode with photo card"""
    query = update.callback_query
    user_id = update.effective_user.id
    user_name = update.effective_user.first_name

    # 🎽 Jersey-number search: /mystats #7 or /mystats 7 → look up that player directly
    if query is None and context.args:
        raw = context.args[0].strip().lstrip("#")
        if raw.isdigit():
            jersey_num = int(raw)
            target_id = find_user_id_by_jersey(jersey_num)
            if target_id is None:
                await update.message.reply_text(
                    f"🎽 <b>No one is wearing #{jersey_num} right now.</b>\n"
                    f"<i>Try /mystats without a number to view your own card.</i>",
                    parse_mode=ParseMode.HTML
                )
                return
            user_id = target_id
            user_name = user_data.get(target_id, {}).get("first_name", "Player")

    if query is None:
        # ── Image cooldown check for groups ──
        group_id = update.effective_chat.id
        if update.effective_chat.type != "private":
            remaining = check_image_cooldown(group_id)
            if remaining is not None:
                await send_cooldown_warning(update, remaining)
                return
        keyboard = [
            [
                styled_button("👥 Team", callback_data=f"mystats_team_{user_id}"),
                styled_button("⚔️ Solo", callback_data=f"mystats_solo_{user_id}")
            ],
            [
                styled_button("🏆 Achievements", callback_data=f"mystats_achievements_{user_id}")
            ]
        ]
        reply_markup = InlineKeyboardMarkup(keyboard)
        
        caption = f"─────────────────\n"
        caption += f"  🏏  C R I C K E T  C A R D  \n"
        caption += f"─────────────────\n"
        caption += f"👤 <b>{format_name_with_jersey(user_id, user_name)}</b>\n"
        caption += f"─────────────────\n"
        caption += "👇 <i>Select a mode to view your stats!</i>"
        
        try:
            # Use scorecard photo (already available in MEDIA_ASSETS)
            stats_photo = MEDIA_ASSETS.get("botstats")
            if stats_photo:
                await update.message.reply_photo(
                    photo=stats_photo,
                    caption=caption,
                    parse_mode=ParseMode.HTML,
                    reply_markup=reply_markup
                )
                if update.effective_chat.type != "private":
                    set_image_cooldown(update.effective_chat.id)
            else:
                await update.message.reply_text(
                    caption,
                    parse_mode=ParseMode.HTML,
                    reply_markup=reply_markup
                )
        except Exception as e:
            logger.error(f"mystats send error: {e}")
            await update.message.reply_text("🏏 Error loading stats. Try again!")
    else:
        await query.answer()

def _render_stats_image(user_id: int, name: str, stats: dict, avatar_bytes: Optional[bytes], mode: str) -> Optional[BytesIO]:
    """Actual blocking PIL work for the mystats/scorecard card.
    Always call this via asyncio.to_thread — never directly on the event
    loop — since the 3x supersampled compositing here can take a real
    chunk of CPU time and used to freeze every group's live game while
    one group's scorecard was being drawn.

    🎽 JERSEY-CARD TEMPLATE — single 1536x1024 image: jersey back on the
    left half, player card on the right half. Coordinates below were
    pixel-measured off the template at that exact resolution.
    """
    try:
        import os
        from PIL import Image, ImageDraw, ImageFont, ImageOps
        from io import BytesIO

        TEMPLATE_PATH = "mystats_jersey_template.jpg"
        if not os.path.exists(TEMPLATE_PATH):
            # Fallback: try upload location
            TEMPLATE_PATH = "/home/cricoverse/mystats_jersey_template.jpg"

        base = Image.open(TEMPLATE_PATH).convert("RGBA")
        W, H = base.size  # 1536 x 1024
        overlay = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        draw = ImageDraw.Draw(overlay)

        # ── FONTS ──
        def _font(path, size):
            try:
                return ImageFont.truetype(path, size)
            except Exception:
                return ImageFont.load_default(size=size)

        f_jersey_name = _font("Roboto-Bold.ttf", 48)
        f_jersey_num  = _font("Roboto-Bold.ttf", 240)
        f_card_name   = _font("Roboto-Bold.ttf", 40)
        f_rank        = _font("Roboto-Bold.ttf", 128)
        f_stat_val    = _font("Roboto-Bold.ttf", 60)

        # Dark teal, matching the template's own text/wordmark color
        TEAL = (7, 48, 54, 255)

        def _center_text(cx, cy, text, font, fill=TEAL, stroke=2):
            bb = draw.textbbox((0, 0), text, font=font, stroke_width=stroke)
            w = bb[2] - bb[0]
            h = bb[3] - bb[1]
            draw.text((cx - w / 2 - bb[0], cy - h / 2 - bb[1]), text, font=font, fill=fill,
                       stroke_width=stroke, stroke_fill=fill)

        # ── JERSEY (left half) ──
        jersey_number = user_data.get(user_id, {}).get("jersey_number")
        jersey_num_str = f"{jersey_number}" if jersey_number is not None else "--"
        safe_name = (name or "Player").upper()[:16]

        JERSEY_CX = 380  # horizontal center of the shirt back
        _center_text(JERSEY_CX, 355, safe_name, f_jersey_name, stroke=2)
        _center_text(JERSEY_CX, 545, jersey_num_str, f_jersey_num, stroke=4)

        # ── CARD (right half, offset +760) ──
        CARD_X = 760

        # 1. Player photo (rounded square box: x 815-1110, y 205-500)
        box_x0, box_y0, box_x1, box_y1 = CARD_X + 55, 185, CARD_X + 350, 520
        box_w, box_h = box_x1 - box_x0, box_y1 - box_y0
        hq = 3
        pfp_img = Image.new("RGBA", (box_w * hq, box_h * hq), (210, 210, 210, 255))
        if avatar_bytes:
            try:
                src = Image.open(BytesIO(avatar_bytes)).convert("RGBA")
                src = ImageOps.fit(src, (box_w * hq, box_h * hq), method=Image.Resampling.LANCZOS)
                pfp_img = src
            except Exception:
                pass
        else:
            id_draw = ImageDraw.Draw(pfp_img)
            id_draw.rectangle([0, 0, box_w * hq, box_h * hq], fill=(20, 60, 68, 255))
            initials = "".join(p[:1] for p in (name or "PL").split()[:2]).upper()
            fi = _font("Roboto-Bold.ttf", (box_h * hq) // 3)
            ib = id_draw.textbbox((0, 0), initials, font=fi)
            id_draw.text(
                ((box_w * hq - (ib[2] - ib[0])) // 2, (box_h * hq - (ib[3] - ib[1])) // 2),
                initials, font=fi, fill=(255, 255, 255, 255)
            )
        # rounded-rect mask so the photo matches the template's rounded box
        radius = 28 * hq
        mask_hq = Image.new("L", (box_w * hq, box_h * hq), 0)
        ImageDraw.Draw(mask_hq).rounded_rectangle(
            [0, 0, box_w * hq - 1, box_h * hq - 1], radius=radius, fill=255
        )
        pfp_masked_hq = Image.new("RGBA", (box_w * hq, box_h * hq), (0, 0, 0, 0))
        pfp_masked_hq.paste(pfp_img, (0, 0), mask_hq)
        pfp_final = pfp_masked_hq.resize((box_w, box_h), Image.Resampling.LANCZOS)
        overlay.alpha_composite(pfp_final, (box_x0, box_y0))

        # 2. Player name (in the blank name bar, nudged left, bold)
        _center_text(CARD_X + 500, 312, (name or "Player")[:18], f_card_name, stroke=1)

        # 3. CCC Ranking (in the wreath gap under PLAYER PROFILE)
        try:
            ccc_row = get_player_ccc_rank(user_id)
        except Exception:
            ccc_row = None
        if ccc_row:
            _cat_short = {"Batsman": "BAT", "Bowler": "BOWL", "All-Rounder": "AR"}.get(ccc_row.get("category", "Batsman"), "BAT")
            rank_str = f"#{ccc_row.get('cat_rank', ccc_row['rank'])} ({_cat_short})"
        else:
            rank_str = "Unranked"
        _center_text(CARD_X + 370, 675, rank_str, f_rank, stroke=3)

        # 5. Matches / Runs / Wickets values, centered in the stats section box
        stat_cols = [
            (CARD_X + 195, str(stats.get("matches", 0))),
            (CARD_X + 385, str(stats.get("runs", 0))),
            (CARD_X + 585, str(stats.get("wickets", 0))),
        ]
        for cx, val in stat_cols:
            _center_text(cx, 855, val, f_stat_val, stroke=1)

        final = Image.alpha_composite(base, overlay).convert("RGB")
        bio = BytesIO()
        final.save(bio, "JPEG", quality=97)
        bio.seek(0)
        return bio

    except Exception as e:
        logger.error("Stats image generation error: " + str(e))
        return None


async def generate_stats_image(user_id: int, name: str, stats: dict, avatar_bytes: Optional[bytes] = None, mode: str = "overall") -> Optional[BytesIO]:
    """
    ✅ TEMPLATE-BASED mystats card.
    Uses mystats_template.jpg as background and overlays:
      - Player pfp in the circular area (right side)
      - Player name below the crown (top area)
      - Stats (matches, runs, wickets, 50/100, strike rate, highest score)
        at the exact positions shown in the template

    🔧 SCALE FIX: the actual PIL drawing now runs in a background thread
    via _render_stats_image, so building one group's scorecard never
    stalls ball-detection/messages in every other group.
    """
    return await asyncio.to_thread(_render_stats_image, user_id, name, stats, avatar_bytes, mode)



def fetch_overall_stats(user_id: int) -> dict:
    """Fetch overall player statistics from user_stats and calculate derived values."""
    try:
        conn= db_connect(DB_PATH)
        c = conn.cursor()
        c.execute("""
            SELECT 
                matches_played, matches_won, total_runs, highest_score,
                total_balls_faced, total_wickets, total_sixes, total_fours,
                total_dots, best_bowling_wickets, best_bowling_runs,
                total_ducks, total_fifties, total_hundreds,
                five_wicket_hauls, player_of_match_count
            FROM user_stats
            WHERE user_id = ?
        """, (user_id,))
        row = c.fetchone()
        conn.close()
    except Exception as e:
        logger.error(f"Error fetching overall stats: {e}")
        row = None

    if not row:
        return {
            "matches": 0, "wins": 0, "losses": 0, "win_rate": 0.0,
            "runs": 0, "highest": 0, "balls": 0, "wickets": 0,
            "sixes": 0, "fours": 0, "dots": 0, "best_bowling": "0/0",
            "best_bowling_wickets": 0, "best_bowling_runs": 0,
            "ducks": 0, "fifties": 0, "hundreds": 0, "fifers": 0,
            "mom": 0, "average": 0.0, "strike_rate": 0.0, "form": []
        }

    matches, won, runs, hs, balls, wickets, sixes, fours, dots, bb_w, bb_r, ducks, fifties, hundreds, fifers, mom_count = row
    avg = round(runs / max(matches - ducks, 1), 2)
    sr = round((runs / balls * 100), 2) if balls > 0 else 0.0
    win_rate = round((won / matches * 100), 1) if matches > 0 else 0.0
    best_bowl = f"{bb_w}/{bb_r}" if bb_w else "N/A"
    
    _form = player_stats.get(user_id, {}).get("last_5_results", [])
    
    return {
        "matches": matches,
        "wins": won,
        "losses": max(matches - won, 0),
        "win_rate": win_rate,
        "runs": runs,
        "highest": hs,
        "balls": balls,
        "wickets": wickets,
        "sixes": sixes,
        "fours": fours,
        "dots": dots,
        "best_bowling": best_bowl,
        "best_bowling_wickets": bb_w,
        "best_bowling_runs": bb_r,
        "ducks": ducks,
        "fifties": fifties,
        "hundreds": hundreds,
        "fifers": fifers,
        "mom": mom_count,
        "average": avg,
        "strike_rate": sr,
        "form": _form
    }


async def mystats_command_v2(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Modern /mystats entry point: generated profile card plus clean mode tabs."""
    query = update.callback_query
    if query is not None:
        await query.answer()
        return

    user_id = update.effective_user.id
    user_name = update.effective_user.first_name or "Player"
    group_id = update.effective_chat.id

    # 🎽 Jersey-number search: /mystats #7 or /mystats 7 → look up that player directly
    if context.args:
        raw = context.args[0].strip().lstrip("#")
        if raw.isdigit():
            jersey_num = int(raw)
            target_id = find_user_id_by_jersey(jersey_num)
            if target_id is None:
                await update.message.reply_text(
                    f"🎽 <b>No one is wearing #{jersey_num} right now.</b>\n"
                    f"<i>Try /mystats without a number to view your own card.</i>",
                    parse_mode=ParseMode.HTML
                )
                return
            user_id = target_id
            user_name = user_data.get(target_id, {}).get("first_name", "Player")

    if update.effective_chat.type != "private":
        remaining = check_image_cooldown(group_id)
        if remaining is not None:
            await send_cooldown_warning(update, remaining)
            return

    keyboard = [
        [
            styled_button("👥 Team", callback_data=f"mystats_team_{user_id}"),
            styled_button("⚔️ Solo", callback_data=f"mystats_solo_{user_id}")
        ],
        [
            styled_button("🏆 Achievements", callback_data=f"mystats_achievements_{user_id}")
        ]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    # ── Default view is Team stats ──
    # 🔧 SCALE FIX: these do direct sqlite3 queries; run off the event loop
    # so other groups' games don't stall while this card is built.
    stats = await asyncio.to_thread(fetch_team_stats_for_card, user_id)
    caption = await asyncio.to_thread(build_team_stats_text, user_id, user_name)

    wait_msg = await send_photo_generation_status(
        update,
        "Building your player card",
        "Adding profile photo, team stats, and a cleaner card layout."
    )
    try:
        avatar_bytes = await fetch_user_avatar_bytes(context, user_id)
        stats_photo = await generate_stats_image(user_id, user_name, stats, avatar_bytes, "team")
        if stats_photo:
            photo_caption = caption if len(caption) <= 1024 else caption[:1020] + "…"
            await update.message.reply_photo(
                photo=stats_photo,
                caption=photo_caption,
                parse_mode=ParseMode.HTML,
                reply_markup=reply_markup
            )
            if update.effective_chat.type != "private":
                set_image_cooldown(group_id)
        else:
            await update.message.reply_text(caption, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
    except Exception as e:
        logger.error(f"mystats v2 send error: {e}")
        await update.message.reply_text("🏏 Error loading stats. Try again!")
    finally:
        try:
            if wait_msg:
                await wait_msg.delete()
        except Exception:
            pass


