async def reg_price_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Complete registration"""
    query = update.callback_query
    await query.answer()
    
    parts = query.data.split('_')
    group_id = int(parts[2])
    base_price = int(parts[3])
    user_id = query.from_user.id
    username = query.from_user.username or "No username"
    full_name = query.from_user.full_name
    
    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()
    
    try:
        c.execute('INSERT INTO registered_players (group_id, user_id, username, full_name, base_price, registered_at) VALUES (?, ?, ?, ?, ?, ?)',
                 (group_id, user_id, username, full_name, base_price, datetime.now().isoformat()))
        conn.commit()
        
        c.execute('SELECT group_name FROM tournament_groups WHERE group_id = ?', (group_id,))
        result = c.fetchone()
        group_name = result[0] if result else "Unknown"
        conn.close()
        
        _success_text = (
            f"✅ <b>Registration Successful!</b>\n"
            f"─────────────────\n"
            f"🏆 <b>Tournament:</b> {group_name}\n"
            f"👤 <b>Player:</b> {full_name}\n"
            f"💰 <b>Base Price:</b> {base_price} 🔷\n"
            f"─────────────────\n"
            f"🍀 <i>May the best player win! Good luck!</i>"
        )
        # Message is a photo — edit caption, not text
        try:
            await query.edit_message_caption(caption=_success_text, parse_mode=ParseMode.HTML)
        except Exception:
            await query.message.reply_text(_success_text, parse_mode=ParseMode.HTML)
        
        try:
            # Send photo with caption to the group
            registration_msg = (
                f"╭━━ 🎊 NEW PLAYER REGISTERED! ━━━🏏\n"
                f"┃ 👤 {full_name}\n"
                f"┃ 🔖 @{username if username != 'No username' else 'N/A'}\n"
                f"┃ 💰 Base Price: {base_price} 🔷\n"
                f"┃\n"
                f"┃ 🏆 Welcome to {group_name} Tournament!\n"
                f"┃ 🍀 Good luck, champion!\n"
                f"╰━━━━━━━━"
            )
            
            await context.bot.send_photo(
                group_id,
                photo=PLAYER_REGISTERED_PHOTO,
                caption=registration_msg,
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            logger.error(f"Error sending registration photo: {e}")
            # Fallback to text message
            try:
                registration_msg = (
                    f"╭━━ 🎊 NEW PLAYER REGISTERED! ━━━🏏\n"
                    f"┃ 👤 {full_name}  ┊  @{username if username != 'No username' else 'N/A'}\n"
                    f"┃ 💰 Base Price: {base_price} 🔷\n"
                    f"┃ 🏆 Welcome to {group_name} Tournament!\n"
                    f"╰━━━━━━━━"
                )
                await context.bot.send_message(group_id, registration_msg, parse_mode=ParseMode.HTML)
            except Exception:
                pass
    except sqlite3.IntegrityError:
        conn.close()
        try:
            await query.edit_message_caption(caption="🏏 <b>Already registered!</b>", parse_mode=ParseMode.HTML)
        except Exception:
            await query.message.reply_text("🏏 Already registered!")
    except Exception as e:
        conn.close()
        logger.error(f"reg_price_callback DB error: {e}")
        try:
            await query.edit_message_caption(
                caption="❌ <b>Registration Failed!</b>\nAn error occurred. Please try again or contact the admin.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            await query.message.reply_text("❌ Registration failed! Please try again.")

async def unregister_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Unregister from tournament (DM only)"""
    if update.effective_chat.type != 'private':
        await update.message.reply_text(
            "🏏 <b>Use this command in DM!</b>\nMessage me privately to unregister.",
            parse_mode=ParseMode.HTML
        )
        return

    user_id = update.effective_user.id
    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()

    # Find all active registrations this user is part of
    c.execute("""
        SELECT rp.group_id, COALESCE(rp.tournament_name, tg.group_name) as name, rp.end_date
        FROM registered_players reg
        JOIN registration_periods rp ON rp.group_id = reg.group_id AND rp.is_active = 1
        JOIN tournament_groups tg ON tg.group_id = reg.group_id
        WHERE reg.user_id = ? AND rp.end_date > ?
    """, (user_id, datetime.now().isoformat()))
    rows = c.fetchall()
    conn.close()

    if not rows:
        await update.message.reply_text(
            "📋 <b>No Active Registrations</b>\n"
            "─────────────────\n"
            "You are not registered in any open tournament right now.",
            parse_mode=ParseMode.HTML
        )
        return

    keyboard = [
        [styled_button(f"❌ {name}", callback_data=f"unreg_confirm_{gid}")]
        for gid, name, _ in rows
    ]
    keyboard.append([styled_button("🚫 Cancel", callback_data="unreg_cancel")])

    await update.message.reply_text(
        "📋 <b>UNREGISTER FROM TOURNAMENT</b>\n"
        "─────────────────\n"
        "Select the tournament you want to leave:\n\n"
        "⚠️ <i>This cannot be undone!</i>",
        reply_markup=InlineKeyboardMarkup(keyboard),
        parse_mode=ParseMode.HTML
    )


async def unreg_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle unregister confirmation"""
    query = update.callback_query
    await query.answer()

    if query.data == "unreg_cancel":
        try:
            await query.edit_message_text(
                "✅ <b>Cancelled.</b> You are still registered.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return

    try:
        group_id = int(query.data.split("_")[2])
    except (IndexError, ValueError):
        return

    user_id = query.from_user.id
    full_name = query.from_user.full_name
    username = query.from_user.username or "N/A"

    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()

    # Check registration still open
    c.execute(
        "SELECT end_date FROM registration_periods WHERE group_id = ? AND is_active = 1",
        (group_id,)
    )
    row = c.fetchone()
    if not row:
        conn.close()
        await query.edit_message_text(
            "⏰ <b>Registration is closed!</b>\nYou can no longer unregister.",
            parse_mode=ParseMode.HTML
        )
        return

    try:
        end_dt = datetime.fromisoformat(row[0])
        if end_dt <= datetime.now():
            conn.close()
            await query.edit_message_text(
                "⏰ <b>Registration is closed!</b>\nYou can no longer unregister.",
                parse_mode=ParseMode.HTML
            )
            return
    except Exception:
        pass

    # Delete registration
    c.execute(
        "DELETE FROM registered_players WHERE group_id = ? AND user_id = ?",
        (group_id, user_id)
    )
    deleted = c.rowcount

    c.execute("SELECT group_name FROM tournament_groups WHERE group_id = ?", (group_id,))
    res = c.fetchone()
    group_name = res[0] if res else "Tournament"
    conn.commit()
    conn.close()

    if deleted == 0:
        await query.edit_message_text(
            "❓ <b>Not Found</b>\nYou were not registered in this tournament.",
            parse_mode=ParseMode.HTML
        )
        return

    await query.edit_message_text(
        f"✅ <b>Unregistered Successfully!</b>\n"
        f"─────────────────\n"
        f"🏆 <b>Tournament:</b> {html.escape(group_name)}\n"
        f"👤 <b>Player:</b> {html.escape(full_name)}\n\n"
        f"<i>You have been removed from the player pool.\n"
        f"Contact an admin if this was a mistake.</i>",
        parse_mode=ParseMode.HTML
    )

    # Notify the group
    try:
        await context.bot.send_message(
            group_id,
            f"📤 <b>PLAYER UNREGISTERED</b>\n"
            f"─────────────────\n"
            f"👤 <b>{html.escape(full_name)}</b> (@{username})\n"
            f"<i>has withdrawn from the tournament.</i>",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass


