def _reglist_price_dropdown_keyboard(group_id: int, price_groups: dict) -> InlineKeyboardMarkup:
    """Dropdown menu with 50 30 20 10 base price options using styled colored buttons."""
    rows = []
    for price in [50, 30, 20, 10]:
        count = len(price_groups.get(price, []))
        rows.append([styled_button(
            f"Base Price {price} ({count})",
            callback_data=f"reglist_price_{group_id}_{price}_0",
            style="primary"
        )])
    other_prices = sorted([p for p in price_groups if p not in (50, 30, 20, 10)], reverse=True)
    for price in other_prices:
        count = len(price_groups[price])
        rows.append([styled_button(
            f"Base Price {price} ({count})",
            callback_data=f"reglist_price_{group_id}_{price}_0",
            style="primary"
        )])
    rows.append([styled_button("❌ Close", callback_data="reglist_close", style="danger")])
    return InlineKeyboardMarkup(rows)


def _reglist_dropdown_text(group_name: str, total: int) -> str:
    return (
        f"📋 <b>TOURNAMENT REGISTRATION</b>\n"
        f"🏆 <b>{html.escape(str(group_name))}</b>\n"
        f"👥 Total: <b>{total}</b> players\n"
        f"─────────────────\n\n"
        f"👇 Select a base price to view its player table:"
    )


def _group_players_by_price(players):
    """players rows: (user_id, username, full_name, base_price, registered_at)"""
    price_groups = defaultdict(list)
    for user_id_p, username, full_name, base_price, registered_at in players:
        price_groups[base_price].append({
            'user_id': user_id_p,
            'username': username or 'No Username',
            'full_name': full_name or 'Unknown',
        })
    return price_groups


_REGLIST_ROWS_PER_PAGE = 20


def _build_reglist_table_page(players_for_price: list, price: int, group_name: str, page_idx: int):
    """Build one page of the S.No | Player Name | Id | username table for a
    single base-price category, returned as a monospace <pre> block."""
    total_pages = max(1, math.ceil(len(players_for_price) / _REGLIST_ROWS_PER_PAGE))
    page_idx = max(0, min(page_idx, total_pages - 1))
    start = page_idx * _REGLIST_ROWS_PER_PAGE
    chunk = players_for_price[start:start + _REGLIST_ROWS_PER_PAGE]

    def _pad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    header_line = f"{_pad('S.No', 5)}{_pad('Player Name', 16)}{_pad('Id', 12)}{_pad('Username', 16)}\n"
    table = header_line + ("─" * 49) + "\n"
    for i, p in enumerate(chunk, start=start + 1):
        name = p['full_name'][:14]
        uname = f"@{p['username']}"[:14]
        table += f"{_pad(i, 5)}{_pad(name, 16)}{_pad(p['user_id'], 12)}{_pad(uname, 16)}\n"
    if not chunk:
        table += "  No players in this category\n"

    text = (
        f"📋 <b>TOURNAMENT REGISTRATION</b>\n"
        f"🏆 <b>{html.escape(str(group_name))}</b>  ·  💰 Base Price: <b>{price} 🔷</b>\n"
        f"─────────────────\n"
        f"<pre>{table}</pre>"
        f"<i>Page {page_idx + 1} of {total_pages}</i>"
    )
    return text, total_pages, page_idx


def _reglist_table_keyboard(group_id: int, price: int, page_idx: int, total_pages: int) -> InlineKeyboardMarkup:
    nav_row = []
    if page_idx > 0:
        nav_row.append(styled_button("⬅️ Prev", callback_data=f"reglist_price_{group_id}_{price}_{page_idx - 1}"))
    nav_row.append(styled_button(f"📄 {page_idx + 1}/{total_pages}", callback_data="noop"))
    if page_idx < total_pages - 1:
        nav_row.append(styled_button("Next ➡️", callback_data=f"reglist_price_{group_id}_{price}_{page_idx + 1}"))
    back_row = [
        styled_button("◀ Back", callback_data=f"reglist_back_{group_id}"),
        styled_button("❌ Close", callback_data="reglist_close"),
    ]
    return InlineKeyboardMarkup(([nav_row] if nav_row else []) + [back_row])


async def reglist_price_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the S.No/Player Name/Id/username table for the chosen base price."""
    query = update.callback_query
    await query.answer()
    try:
        # Format: reglist_price_<group_id>_<price>_<page_idx>
        stripped = query.data[len("reglist_price_"):]
        group_id_str, price_str, page_str = stripped.rsplit("_", 2)
        group_id = int(group_id_str)
        price = int(price_str)
        page_idx = int(page_str)
    except (IndexError, ValueError):
        return

    players, group_name, _ = await asyncio.to_thread(_fetch_registeredlist_data, group_id)
    price_groups = _group_players_by_price(players)
    players_for_price = price_groups.get(price, [])

    text, total_pages, page_idx = _build_reglist_table_page(players_for_price, price, group_name, page_idx)
    kb = _reglist_table_keyboard(group_id, price, page_idx, total_pages)

    try:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.error(f"reglist_price_callback edit error: {e}")


async def reglist_back_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Back button from a price table → return to the base-price dropdown."""
    query = update.callback_query
    await query.answer()
    try:
        group_id = int(query.data[len("reglist_back_"):])
    except ValueError:
        return

    players, group_name, _ = await asyncio.to_thread(_fetch_registeredlist_data, group_id)
    price_groups = _group_players_by_price(players)

    if not players:
        try:
            await query.edit_message_text(
                f"📋 <b>REGISTERED PLAYERS</b>\n🏆 <b>{html.escape(str(group_name))}</b>\n─────────────────\n❌ No players registered yet.",
                parse_mode=ParseMode.HTML
            )
        except Exception:
            pass
        return

    text = _reglist_dropdown_text(group_name, len(players))
    kb = _reglist_price_dropdown_keyboard(group_id, price_groups)
    try:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception as e:
        logger.error(f"reglist_back_callback edit error: {e}")


async def reglist_close_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Delete the registeredlist message on Close button."""
    query = update.callback_query
    await query.answer()
    try:
        await query.message.delete()
    except Exception:
        try:
            await query.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass

def _check_tournament_power_user_db(user_id: int, group_id: int) -> bool:
    conn_chk= db_connect(TOURNAMENT_DB_PATH)
    c_chk = conn_chk.cursor()
    c_chk.execute(
        'SELECT user_id FROM tournament_power_users WHERE user_id = ? AND group_id = ?',
        (user_id, group_id)
    )
    has_power = c_chk.fetchone()
    conn_chk.close()
    return bool(has_power)


def _fetch_registeredlist_data(group_id: int):
    conn= db_connect(TOURNAMENT_DB_PATH)
    c = conn.cursor()
    c.execute(
        'SELECT user_id, username, full_name, base_price, registered_at '
        'FROM registered_players WHERE group_id = ? ORDER BY base_price DESC, registered_at',
        (group_id,)
    )
    players = c.fetchall()
    c.execute('SELECT group_name FROM tournament_groups WHERE group_id = ?', (group_id,))
    res = c.fetchone()
    group_name = res[0] if res else "Unknown Group"

    # Also fetch registration period info
    c.execute(
        'SELECT end_date, tournament_name FROM registration_periods WHERE group_id = ? AND is_active = 1 ORDER BY id DESC LIMIT 1',
        (group_id,)
    )
    reg_info = c.fetchone()
    conn.close()
    return players, group_name, reg_info


async def registeredlist_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Show registered players list with Prev/Next/Close pagination"""
    user_id = update.effective_user.id
    chat_id = update.effective_chat.id
    chat_type = update.effective_chat.type

    # ── Determine group_id ──
    if chat_type == 'private':
        if not context.args:
            await update.message.reply_text(
                "🏏 <b>Usage:</b> <code>/registeredlist &lt;group_id&gt;</code>",
                parse_mode=ParseMode.HTML
            )
            return
        try:
            group_id = int(context.args[0])
        except ValueError:
            await update.message.reply_text("🏏 Invalid group ID!", parse_mode=ParseMode.HTML)
            return
    else:
        group_id = chat_id
        # Admin-only in groups
        try:
            member = await context.bot.get_chat_member(group_id, user_id)
            if member.status not in ['creator', 'administrator']:
                # Also allow TOURNAMENT_POWER_USERS
                if (user_id, group_id) not in TOURNAMENT_POWER_USERS:
                    has_power = await asyncio.to_thread(_check_tournament_power_user_db, user_id, group_id)
                    if not has_power:
                        await update.message.reply_text(
                            "🏏 <b>Admin Only!</b>\nOnly group admins can use this command.",
                            parse_mode=ParseMode.HTML
                        )
                        return
        except Exception:
            await update.message.reply_text("🏏 Error checking permissions!")
            return

    # ── Fetch data ──
    # 🔧 SCALE FIX: run off the event loop so this doesn't stall other groups' games.
    players, group_name, reg_info = await asyncio.to_thread(_fetch_registeredlist_data, group_id)

    if not players:
        reg_status = ""
        if reg_info:
            try:
                end_dt = datetime.fromisoformat(reg_info[0])
                reg_status = f"\n⏰ Registration open until: <b>{end_dt.strftime('%d %b %Y %H:%M')}</b>"
            except Exception:
                pass
        await update.message.reply_text(
            f"📋 <b>TOURNAMENT REGISTRATION</b>\n"
            f"🏆 <b>{html.escape(str(group_name))}</b>\n"
            f"─────────────────\n"
            f"❌ No players registered yet.{reg_status}",
            parse_mode=ParseMode.HTML
        )
        return

    # ── Show base-price dropdown (50/30/20/10) first ──
    price_groups = _group_players_by_price(players)
    text = _reglist_dropdown_text(group_name, len(players))
    kb = _reglist_price_dropdown_keyboard(group_id, price_groups)

    await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=kb)

async def auctionset_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Display auction set - registered players grouped by base price"""
    user_id = update.effective_user.id
    
    # Get group_id
    if update.effective_chat.type == 'private':
        if not context.args:
            await update.message.reply_text(
                "🏏 <b>Usage:</b> <code>/auctionset &lt;group_id&gt;</code>", 
                parse_mode=ParseMode.HTML
            )
            return
        try:
            group_id = int(context.args[0])
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 29304)")
            await update.message.reply_text("🏏 Invalid group ID!", parse_mode=ParseMode.HTML)
            return
    else:
        group_id = update.effective_chat.id
    
    # Check permissions
    if user_id not in [OWNER_ID, SECOND_APPROVER_ID] and (user_id, group_id) not in TOURNAMENT_POWER_USERS:
        conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
        c = conn.cursor()
        c.execute('SELECT user_id FROM tournament_power_users WHERE user_id = ? AND group_id = ?', (user_id, group_id))
        if not c.fetchone():
            await update.message.reply_text("🏏 No permission to view auction set!", parse_mode=ParseMode.HTML)
            conn.close()
            return
        conn.close()
    
    # Fetch registered players
    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()
    c.execute('SELECT user_id, username, full_name, base_price FROM registered_players WHERE group_id = ? ORDER BY base_price, registered_at', (group_id,))
    players = c.fetchall()
    c.execute('SELECT group_name FROM tournament_groups WHERE group_id = ?', (group_id,))
    result = c.fetchone()
    group_name = result[0] if result else "Unknown"
    conn.close()
    
    if not players:
        await update.message.reply_text(
            f"🏏 <b>No Registered Players</b>\n\n"
            f"Tournament: {group_name}\n"
            f"No players have registered yet!",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Group players by base price
    price_groups = {}
    for user_id_p, username, full_name, base_price in players:
        if base_price not in price_groups:
            price_groups[base_price] = []
        price_groups[base_price].append({
            'user_id': user_id_p,
            'username': username,
            'full_name': full_name
        })
    
    # Build the auction set message
    message = (
        f"🏏 <b>AUCTION SET - {group_name}</b>\n"
        f"─────────────────\n\n"
    )
    
    # Sort base prices in ascending order
    sorted_prices = sorted(price_groups.keys())
    
    for base_price in sorted_prices:
        players_in_group = price_groups[base_price]
        message += f"💰 <b>Base Price: {base_price} 🔷</b>\n"
        
        # List all user IDs in this price group
        user_ids = [str(p['user_id']) for p in players_in_group]
        message += f"<code>{' '.join(user_ids)}</code>\n\n"
    
    message += (
        f"─────────────────\n"
        f"📊 <b>Total Players:</b> {len(players)}\n"
        f"💵 <b>Price Categories:</b> {len(price_groups)}\n\n"
        f"<i>Use these User IDs for auction commands</i>"
    )
    
    await update.message.reply_text(message, parse_mode=ParseMode.HTML)


async def auctionresults_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏏 Export auction results"""
    if pd is None:
        await update.message.reply_text("🏏 Excel export not available!")
        return
    
    group_id = update.effective_chat.id if update.effective_chat.type != 'private' else None
    if not group_id and context.args:
        try:
            group_id = int(context.args[0])
        except Exception as e:
            logger.exception(f"Unhandled exception (auto-fixed bare except, orig line 29388)")
            pass
    
    if not group_id:
        await update.message.reply_text("🏏 Use in group or provide group ID!")
        return
    
    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()
    c.execute('SELECT player_name, team_name, final_price, auction_date FROM auction_results WHERE group_id = ? ORDER BY team_name, final_price DESC', (group_id,))
    results = c.fetchall()
    c.execute('SELECT group_name FROM tournament_groups WHERE group_id = ?', (group_id,))
    result = c.fetchone()
    group_name = result[0] if result else "Unknown"
    conn.close()
    
    if not results:
        await update.message.reply_text("🏏 No auction results found!")
        return
    
    df = pd.DataFrame(results, columns=['Player', 'Team', 'Price', 'Date'])
    excel_file = f"/tmp/auction_{abs(group_id)}.xlsx"
    df.to_excel(excel_file, index=False, engine='openpyxl')
    
    try:
        with open(excel_file, 'rb') as f:
            await update.message.reply_document(document=f, filename=f"auction_{group_name.replace(' ', '_')}.xlsx",
                                              caption=f"🏏 Auction Results\n{group_name}\nTotal: {len(results)} players")
    finally:
        if os.path.exists(excel_file):
            os.remove(excel_file)

async def save_auction_results_to_db(group_id: int, auction):
    """Save auction results to tournament database"""
    conn= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
    c = conn.cursor()
    try:
        for team_name, team in auction.teams.items():
            for player in team.players:
                c.execute('INSERT INTO auction_results (group_id, player_user_id, player_name, team_name, final_price) VALUES (?, ?, ?, ?, ?)',
                         (group_id, player['player_id'], player['player_name'], team_name, player['price']))
        conn.commit()
        logger.info(f"✅ Saved auction results for group {group_id}")
    except Exception as e:
        logger.error(f"Error saving auction results: {e}")
    finally:
        conn.close()





async def tourrestore_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🔄 Restore tournament.db from a backup file (Owner only)"""
    user = update.effective_user

    # ── Security: only owner or second approver ──
    if user.id not in [OWNER_ID, SECOND_APPROVER_ID]:
        await update.message.reply_text(
            "🚫 <b>Access Denied!</b>\n\nOnly bot owner can restore tournament data.",
            parse_mode=ParseMode.HTML
        )
        return

    # ── Must reply to a document ──
    if not update.message.reply_to_message or not update.message.reply_to_message.document:
        await update.message.reply_text(
            "📋 <b>How to Restore Tournament Data</b>\n"
            "─────────────────\n\n"
            "1️⃣ Upload or forward the tournament backup <code>.db</code> file\n"
            "2️⃣ Reply to that file with <code>/tourrestore</code>\n\n"
            "⚠️ <b>What gets restored:</b>\n"
            "• Registered players\n"
            "• Registration periods\n"
            "• Tournament groups & approvals\n"
            "• Auction results\n"
            "• Power users\n\n"
            "⚡ In-memory data is reloaded automatically after restore.\n"
            "💾 A safety backup of the current DB is saved before overwriting.\n"
            "─────────────────",
            parse_mode=ParseMode.HTML
        )
        return

    doc = update.message.reply_to_message.document

    # ── Validate extension ──
    if not doc.file_name.endswith(('.db', '.sqlite', '.sqlite3')):
        await update.message.reply_text(
            f"⚠️ <b>Invalid File Type!</b>\n\n"
            f"Only <code>.db</code>, <code>.sqlite</code>, or <code>.sqlite3</code> files are accepted.\n\n"
            f"Your file: <code>{doc.file_name}</code>",
            parse_mode=ParseMode.HTML
        )
        return

    status = await update.message.reply_text(
        "⏳ <b>Downloading tournament backup...</b>",
        parse_mode=ParseMode.HTML
    )
    temp_path = f"temp_tourrestore_{int(time.time())}.db"

    try:
        # ── Download ──
        new_file = await doc.get_file()
        await new_file.download_to_drive(temp_path)

        # ── Validate: must be a real SQLite with expected tables ──
        required_tables = {"registered_players", "registration_periods", "tournament_groups"}
        try:
            conn_check = sqlite3.connect(temp_path)
            c_check = conn_check.cursor()
            c_check.execute("SELECT name FROM sqlite_master WHERE type='table'")
            found_tables = {row[0] for row in c_check.fetchall()}
            conn_check.close()
        except sqlite3.Error as e:
            if os.path.exists(temp_path):
                os.remove(temp_path)
            await status.edit_text(
                f"❌ <b>Invalid Database!</b>\n\n"
                f"Not a valid SQLite file or it is corrupted.\n"
                f"Error: <code>{str(e)}</code>",
                parse_mode=ParseMode.HTML
            )
            return

        missing = required_tables - found_tables
        if missing:
            os.remove(temp_path)
            await status.edit_text(
                f"❌ <b>Wrong Database File!</b>\n\n"
                f"This doesn\'t look like a tournament backup.\n"
                f"Missing tables: <code>{', '.join(missing)}</code>\n\n"
                f"Make sure you\'re uploading the <b>tournament</b> backup "
                f"(not the main game DB).",
                parse_mode=ParseMode.HTML
            )
            return

        await status.edit_text(
            "✅ <b>File validated!</b> Creating safety backup...",
            parse_mode=ParseMode.HTML
        )

        # ── Safety backup of current tournament.db ──
        safety_backup = f"pre_tourrestore_backup_{int(time.time())}.db"
        if os.path.exists(TOURNAMENT_DB_PATH):
            shutil.copy(TOURNAMENT_DB_PATH, safety_backup)
            # Count current data for summary
            try:
                conn_old = sqlite3.connect(safety_backup)
                c_old = conn_old.cursor()
                c_old.execute("SELECT COUNT(*) FROM registered_players")
                old_players = c_old.fetchone()[0]
                c_old.execute("SELECT COUNT(*) FROM tournament_groups")
                old_groups = c_old.fetchone()[0]
                conn_old.close()
            except Exception:
                old_players = old_groups = "?"
        else:
            old_players = old_groups = 0

        await status.edit_text(
            "🔄 <b>Restoring tournament database...</b>",
            parse_mode=ParseMode.HTML
        )

        # ── Replace tournament.db ──
        shutil.move(temp_path, TOURNAMENT_DB_PATH)

        # ── Reload in-memory tournament data ──
        TOURNAMENT_APPROVED_GROUPS.clear()
        REGISTRATION_ACTIVE.clear()
        TOURNAMENT_POWER_USERS.clear()
        load_tournament_data()

        # ── Count restored data ──
        try:
            conn_new= await asyncio.to_thread(db_connect, TOURNAMENT_DB_PATH)
            c_new = conn_new.cursor()
            c_new.execute("SELECT COUNT(*) FROM registered_players")
            new_players = c_new.fetchone()[0]
            c_new.execute("SELECT COUNT(*) FROM tournament_groups")
            new_groups = c_new.fetchone()[0]
            c_new.execute("SELECT COUNT(*) FROM registration_periods WHERE is_active = 1")
            active_regs = c_new.fetchone()[0]
            c_new.execute("SELECT COUNT(*) FROM auction_results")
            auction_results_count = c_new.fetchone()[0]
            c_new.execute("SELECT COUNT(*) FROM tournament_power_users")
            power_users_count = c_new.fetchone()[0]
            conn_new.close()
        except Exception:
            new_players = new_groups = active_regs = auction_results_count = power_users_count = "?"

        await status.edit_text(
            f"✅ <b>Tournament Restore Complete!</b>\n"
            f"─────────────────\n\n"
            f"📁 <b>File:</b> <code>{doc.file_name}</code>\n"
            f"💾 <b>Safety backup:</b> <code>{safety_backup}</code>\n\n"
            f"📊 <b>Restored Data:</b>\n"
            f"  👥 Registered Players: <b>{new_players}</b>\n"
            f"  🏘️ Tournament Groups: <b>{new_groups}</b>\n"
            f"  📋 Active Registrations: <b>{active_regs}</b>\n"
            f"  🏆 Auction Results: <b>{auction_results_count}</b>\n"
            f"  ⚡ Power Users: <b>{power_users_count}</b>\n\n"
            f"🔁 <b>Previous DB had:</b> {old_players} players · {old_groups} groups\n\n"
            f"✨ In-memory data reloaded. Bot is fully operational!\n"
            f"─────────────────",
            parse_mode=ParseMode.HTML
        )
        logger.info(f"✅ Tournament DB restored by user {user.id} from {doc.file_name}")

    except Exception as e:
        logger.error(f"tourrestore_command failed: {e}")
        if os.path.exists(temp_path):
            os.remove(temp_path)
        await status.edit_text(
            f"❌ <b>Tournament Restore Failed!</b>\n\n"
            f"Error: <code>{str(e)}</code>\n\n"
            f"Your current tournament data is unchanged.",
            parse_mode=ParseMode.HTML
        )


