async def fantasy_pick_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Toggle a player in/out of the tapping user's Fantasy Dream III."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # fpick_{group_id}_{player_user_id}

    try:
        _, gid_str, pid_str = data.split("_", 2)
        group_id = int(gid_str)
        player_id = int(pid_str)
    except Exception:
        await query.answer("⚠️ Invalid selection.", show_alert=True)
        return

    match = active_matches.get(group_id)
    if not match or match.game_mode not in ("TEAM", "TOURNAMENT"):
        await query.answer("⚠️ This fantasy window is no longer active.", show_alert=True)
        return

    if not getattr(match, "fantasy_window_open", False) or match.phase != GamePhase.FANTASY_PICK:
        await query.answer("⏰ Fantasy squad picks are locked — the toss has already started!", show_alert=True)
        return

    pool = match.team_x.players + match.team_y.players
    player_obj = next((p for p in pool if p.user_id == player_id), None)
    if not player_obj:
        await query.answer("⚠️ That player isn't part of this match.", show_alert=True)
        return

    cap = get_fantasy_squad_cap(match)
    squad = match.fantasy_squads.setdefault(user.id, {
        "name": user.first_name, "players": [], "match_points": 0, "log": []
    })
    squad["name"] = user.first_name

    if player_id in squad["players"]:
        squad["players"].remove(player_id)
        await query.answer(f"➖ Removed {player_obj.first_name}. ({len(squad['players'])}/{cap})")
    else:
        if len(squad["players"]) >= cap:
            await query.answer(f"🚫 Your Dream III is full ({cap}/{cap})! Remove someone first.", show_alert=True)
            return
        squad["players"].append(player_id)
        await query.answer(f"✅ Added {player_obj.first_name}! ({len(squad['players'])}/{cap})")


async def fantasy_mysquad_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the tapping user their current Dream III picks via popup alert."""
    query = update.callback_query
    user = query.from_user
    data = query.data  # fmysquad_{group_id}
    try:
        group_id = int(data.split("_", 1)[1])
    except Exception:
        await query.answer()
        return

    match = active_matches.get(group_id)
    if not match:
        await query.answer("⚠️ No active match.", show_alert=True)
        return

    squad = match.fantasy_squads.get(user.id)
    if not squad or not squad.get("players"):
        await query.answer("📭 You haven't picked anyone yet! Tap player names to build your Dream III.", show_alert=True)
        return

    pool = match.team_x.players + match.team_y.players
    names = [p.first_name for p in pool if p.user_id in squad["players"]]
    cap = get_fantasy_squad_cap(match)
    await query.answer(f"Your Dream III ({len(names)}/{cap}): " + ", ".join(names), show_alert=True)


async def mysquad_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the caller's fantasy Dream III for the active match in this chat."""
    chat_id = update.effective_chat.id
    user = update.effective_user
    match = active_matches.get(chat_id)
    if not match or match.game_mode not in ("TEAM", "TOURNAMENT"):
        await update.message.reply_text("⚠️ No Team/Tournament match with fantasy squads active here.")
        return

    squad = getattr(match, "fantasy_squads", {}).get(user.id)
    if not squad or not squad.get("players"):
        await update.message.reply_text("📭 You haven't picked your Fantasy Dream III yet! Tap a player in the fantasy message above to build your squad.")
        return

    pool = match.team_x.players + match.team_y.players
    picked = [p for p in pool if p.user_id in squad["players"]]
    cap = get_fantasy_squad_cap(match)

    def _pad(s, w):
        s = html.escape(str(s))
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    def _rpad(s, w):
        # 🔧 FIX: was undefined here — every /mysquad call crashed with NameError
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s

    header = f"{_pad('Rank', 5)}{_pad('Player', 14)}{_pad('Role', 12)}{_rpad('Points', 8)}\n"
    table = header + ("─" * 31) + "\n"
    for i, p in enumerate(picked, 1):
        role = compute_player_role(p.user_id)
        pts = squad.get("match_points", 0)
        table += f"{_pad(i, 5)}{_pad(p.first_name, 14)}{_pad(role, 12)}{_rpad(pts, 8)}\n"

    msg = "🏆 <b>YOUR FANTASY DREAM XI</b>\n─────────────────\n"
    msg += f"<pre>{table}</pre>"
    msg += f"📊 Squad Size: {len(picked)}/{cap}\n"
    if getattr(match, "fantasy_window_open", False) and match.phase == GamePhase.TOSS:
        msg += "🔓 Picks are still OPEN — tap more players above!"
    else:
        msg += f"🔒 Picks are LOCKED · <b>{squad.get('match_points', 0)}</b> pts so far this match"
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)


async def fantasylb_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the global, all-time Fantasy Dream III leaderboard as a table."""
    ranked = sorted(fantasy_data.items(), key=lambda kv: kv[1].get("points", 0), reverse=True)
    ranked = [r for r in ranked if r[1].get("points", 0) > 0][:15]

    if not ranked:
        await update.message.reply_text(
            "📭 No fantasy points on the board yet!\nPlay a Team or Tournament match and pick your Dream III before it starts."
        )
        return

    def _pad(s, w):
        s = html.escape(str(s))
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else s + (" " * (w - len(s)))

    def _rpad(s, w):
        s = str(s)
        return (s[: max(w - 1, 1)] + "…") if len(s) > w else (" " * (w - len(s))) + s

    header = f"{_pad('Rank', 5)}{_pad('Player', 15)}{_pad('Role', 12)}{_rpad('Points', 8)}\n"
    table = header + ("─" * 40) + "\n"
    for i, (uid, d) in enumerate(ranked):
        title_key = d.get("title")
        title_info = get_fantasy_title_info(title_key) if title_key else None
        role = title_info['name'] if title_info else "Manager"
        table += f"{_pad(i + 1, 5)}{_pad(d.get('first_name', 'Player'), 15)}{_pad(role, 12)}{_rpad(d.get('points', 0), 8)}\n"

    msg = "🏆 <b>FANTASY DREAM XI — GLOBAL LEADERBOARD</b>\n─────────────────\n"
    msg += f"<pre>{table}</pre>"
    msg += "🛍️ <code>/fantasyshop</code> → spend points on a title"
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML)


async def fantasydiscount_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """👑 Owner-only: /fantasydiscount <percent> <hours> — run a limited-time Fantasy Shop sale.
    /fantasydiscount off — cancel an active sale early."""
    user = update.effective_user
    if user.id != OWNER_ID:
        await update.message.reply_text("🚫 Owner only command!")
        return

    if not context.args:
        active = get_active_discount_percent()
        if active > 0:
            remaining = int(FANTASY_DISCOUNT["expires_at"] - time.time())
            hrs, mins = divmod(max(remaining, 0) // 60, 60)
            await update.message.reply_text(
                f"🔥 Active sale: <b>{active}% OFF</b>, ends in {hrs}h {mins}m.\n"
                f"Usage: <code>/fantasydiscount [percent] [hours]</code> or <code>/fantasydiscount off</code>",
                parse_mode=ParseMode.HTML
            )
        else:
            await update.message.reply_text(
                "ℹ️ No active sale.\n"
                "Usage: <code>/fantasydiscount [percent] [hours]</code>\n"
                "Example: <code>/fantasydiscount 20 24</code> → 20% off for 24 hours",
                parse_mode=ParseMode.HTML
            )
        return

    if context.args[0].lower() == "off":
        FANTASY_DISCOUNT["percent"] = 0
        FANTASY_DISCOUNT["expires_at"] = 0
        await update.message.reply_text("🛑 Fantasy Shop sale cancelled.")
        return

    try:
        percent = int(context.args[0])
        hours = float(context.args[1]) if len(context.args) > 1 else 24
    except (ValueError, IndexError):
        await update.message.reply_text("❌ Usage: <code>/fantasydiscount [percent] [hours]</code>", parse_mode=ParseMode.HTML)
        return

    if not (1 <= percent <= 90):
        await update.message.reply_text("❌ Percent must be between 1 and 90.")
        return
    if hours <= 0:
        await update.message.reply_text("❌ Hours must be greater than 0.")
        return

    FANTASY_DISCOUNT["percent"] = percent
    FANTASY_DISCOUNT["expires_at"] = time.time() + hours * 3600

    await update.message.reply_text(
        f"🔥 <b>Fantasy Shop Sale Activated!</b>\n"
        f"─────────────────\n"
        f"🏷️ <b>{percent}% OFF</b> all titles\n"
        f"⏱️ Ends in <b>{hours:g} hours</b>\n"
        f"─────────────────\n"
        f"Use /fantasyshop to grab the deal!",
        parse_mode=ParseMode.HTML
    )


async def fantasyshop_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show the fantasy title shop — buy titles using accumulated fantasy points."""
    user = update.effective_user
    init_fantasy_data(user.id, user.first_name, user.username or "")
    save_data()
    profile = fantasy_data[user.id]
    bal = profile["points"]
    owned = profile.get("titles_owned", [])
    equipped = profile.get("title")

    lines = [f"💰 <b>Your Balance:</b> {bal:,} pts\n"]
    discount_pct = get_active_discount_percent()
    if discount_pct > 0:
        remaining = int(FANTASY_DISCOUNT["expires_at"] - time.time())
        hrs, mins = divmod(max(remaining, 0) // 60, 60)
        lines.append(f"🔥 <b>{discount_pct}% OFF</b> everything — ends in {hrs}h {mins}m!\n")
    keyboard = []
    for t in FANTASY_TITLES:
        tag = " ✅ Owned" if t["key"] in owned else ""
        equip_tag = " 🟢 Equipped" if equipped == t["key"] else ""
        disc_price = get_discounted_price(t["price"])
        if discount_pct > 0:
            price_line = f"{t['name']} — <s>{t['price']:,}</s> <b>{disc_price:,}</b> pts{tag}{equip_tag}"
        else:
            price_line = f"{t['name']} — <b>{t['price']:,}</b> pts{tag}{equip_tag}"
        lines.append(price_line)
        if t["key"] not in owned:
            keyboard.append([styled_button(f"🛒 Buy {t['name']} ({disc_price:,})", callback_data=f"fbuytitle_{t['key']}")])
        elif equipped != t["key"]:
            keyboard.append([styled_button(f"🎽 Equip {t['name']}", callback_data=f"fequiptitle_{t['key']}")])

    msg = themed("🛍️ FANTASY TITLE SHOP", lines, "👑")
    reply_markup = InlineKeyboardMarkup(keyboard) if keyboard else None
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, reply_markup=reply_markup)


async def fantasy_buytitle_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Purchase a fantasy title with accumulated fantasy points."""
    query = update.callback_query
    user = query.from_user
    key = query.data.split("_", 1)[1]
    title = get_fantasy_title_info(key)
    if not title:
        await query.answer("⚠️ Unknown title.", show_alert=True)
        return

    init_fantasy_data(user.id, user.first_name)
    profile = fantasy_data[user.id]

    if key in profile.get("titles_owned", []):
        await query.answer("✅ You already own this title!", show_alert=True)
        return
    final_price = get_discounted_price(title["price"])
    if profile.get("points", 0) < final_price:
        short = final_price - profile.get("points", 0)
        await query.answer(f"🚫 Not enough points! You need {short:,} more.", show_alert=True)
        return

    profile["points"] -= final_price
    profile.setdefault("titles_owned", []).append(key)
    profile["title"] = key  # auto-equip the newest purchase
    save_data()

    await query.answer(f"🎉 Purchased {title['name']}!", show_alert=True)
    try:
        await query.edit_message_text(
            f"🎉 <b>{html.escape(user.first_name)}</b> just bought <b>{title['name']}</b> for {final_price:,} fantasy points!\n\nUse /fantasyshop to see what's next.",
            parse_mode=ParseMode.HTML
        )
    except Exception:
        pass


async def fantasy_equiptitle_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Equip an already-owned fantasy title so it shows on /fantasylb."""
    query = update.callback_query
    user = query.from_user
    key = query.data.split("_", 1)[1]
    init_fantasy_data(user.id, user.first_name)
    profile = fantasy_data[user.id]
    if key not in profile.get("titles_owned", []):
        await query.answer("⚠️ You don't own this title yet.", show_alert=True)
        return
    profile["title"] = key
    save_data()
    title = get_fantasy_title_info(key)
    await query.answer(f"🎽 Equipped {title['name']}!", show_alert=True)



# ═══════════════════════════════════════════════════════════════
# CCC RATING & RANKING SYSTEM
# ═══════════════════════════════════════════════════════════════
CCC_MIN_MATCHES = 5

def classify_player_category(runs: int, wickets: int, matches: int, balls_faced: int, balls_bowled: int) -> str:
    """Classify a player as Batsman, Bowler, or All-Rounder based on per-match stats."""
    if matches < CCC_MIN_MATCHES:
        return "Batsman"  # default for unqualified
    runs_per_match = runs / max(matches, 1)
    wickets_per_match = wickets / max(matches, 1)
    # Thresholds
    BAT_THRESHOLD = 8    # avg 8+ runs/match = batting contributor
    BOWL_THRESHOLD = 0.5  # avg 0.5+ wickets/match = bowling contributor
    is_bat = runs_per_match >= BAT_THRESHOLD
    is_bowl = wickets_per_match >= BOWL_THRESHOLD
    if is_bat and is_bowl:
        return "All-Rounder"
    elif is_bowl and not is_bat:
        return "Bowler"
    return "Batsman"

def sync_legacy_player_stats_to_ccc():
    """🔧 FIX: 'purane stats' (old solo/team stats stored only in the
    JSON-backed player_stats dict, from before per-match SQL sync existed
    or from matches that only ever updated player_stats) were invisible to
    CCC ranking because get_ccc_rankings_with_trend()/_lb_query() read only
    the user_stats SQL table. This walks player_stats once and folds each
    user's solo+team totals into user_stats, taking the MAX of existing vs
    legacy values per column so it only ever backfills gaps — it never
    overwrites newer/larger numbers already recorded in SQL."""
    if not player_stats:
        return
    try:
        conn = db_connect(DB_PATH)
        c = conn.cursor()
        for uid, stats in player_stats.items():
            solo = stats.get("solo", {}) or {}
            team = stats.get("team", {}) or {}

            legacy = {
                "matches_played": solo.get("matches", 0),
                "matches_won": solo.get("wins", 0),
                "total_runs": solo.get("runs", 0),
                "total_balls_faced": solo.get("balls", 0),
                "total_wickets": solo.get("wickets", 0),
                "total_sixes": solo.get("sixes", 0),
                "total_fours": solo.get("fours", 0),
                "total_ducks": solo.get("ducks", 0),
                "highest_score": solo.get("highest", solo.get("high_score", 0)),
                "total_hundreds": solo.get("centuries", 0),
                "total_fifties": solo.get("fifties", 0),
                "team_matches_played": team.get("matches_played", team.get("matches", 0)),
                "team_matches_won": team.get("wins", 0),
                "team_total_runs": team.get("runs", 0),
                "team_total_wickets": team.get("wickets", 0),
                "team_total_sixes": team.get("sixes", 0),
                "team_total_fours": team.get("fours", 0),
                "team_total_ducks": team.get("ducks", 0),
                "team_highest_score": team.get("highest", 0),
                "team_total_hundreds": team.get("centuries", 0),
                "team_total_fifties": team.get("fifties", 0),
            }

            if not any(legacy.values()):
                continue

            c.execute("SELECT user_id FROM user_stats WHERE user_id = ?", (uid,))
            if not c.fetchone():
                c.execute("INSERT INTO user_stats (user_id) VALUES (?)", (uid,))

            for col, val in legacy.items():
                c.execute(f"UPDATE user_stats SET {col} = MAX(COALESCE({col},0), ?) WHERE user_id = ?", (val, uid))

        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"sync_legacy_player_stats_to_ccc failed: {e}")


def ensure_ccc_rank_table():
    """Create the CCC Ranking snapshot table if it doesn't exist yet (idempotent)."""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS ccc_rank_snapshot (
        user_id INTEGER PRIMARY KEY,
        rank INTEGER,
        rating REAL,
        category TEXT DEFAULT 'Batsman',
        snapshot_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    try:
        c.execute("ALTER TABLE ccc_rank_snapshot ADD COLUMN category TEXT DEFAULT 'Batsman'")
    except Exception:
        pass  # Column already exists
    conn.commit()
    conn.close()


def _compute_ccc_ranking_rows():
    """
    🏅 CCC RANKING — CricoVerse's overall player rating, ICC-style.
    Combines batting, bowling, wins and match-winning impact into a single rating,
    averaged per match so grinders don't automatically outrank sharper performers.
    Returns a strictly-ordered list (no ties) of dicts, richest performer first:
    [{user_id, first_name, matches, wins, rating, rank}, ...]
    """
    ensure_ccc_rank_table()
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("""
        SELECT user_id, first_name,
            (COALESCE(matches_played,0) + COALESCE(team_matches_played,0)) AS matches,
            (COALESCE(matches_won,0) + COALESCE(team_matches_won,0)) AS wins,
            (COALESCE(total_runs,0) + COALESCE(team_total_runs,0)) AS runs,
            (COALESCE(total_wickets,0) + COALESCE(team_total_wickets,0)) AS wickets,
            (COALESCE(total_sixes,0) + COALESCE(team_total_sixes,0)) AS sixes,
            (COALESCE(total_fours,0) + COALESCE(team_total_fours,0)) AS fours,
            (COALESCE(total_hundreds,0) + COALESCE(team_total_hundreds,0)) AS hundreds,
            (COALESCE(total_fifties,0) + COALESCE(team_total_fifties,0)) AS fifties,
            (COALESCE(total_ducks,0) + COALESCE(team_total_ducks,0)) AS ducks,
            COALESCE(player_of_match_count,0) AS mom,
            (COALESCE(total_balls_faced,0) + COALESCE(team_total_balls_faced,0)) AS balls_faced,
            (COALESCE(total_balls_bowled,0) + COALESCE(team_total_balls_bowled,0)) AS balls_bowled
        FROM user_stats
    """)
    all_rows = c.fetchall()
    conn.close()

    # First pass: gather raw points-per-match for every qualified player so we can
    # compute a league-average baseline. A *pure* per-match average (old formula)
    # rewards a handful of lucky matches over sustained volume, since one bad game
    # drags a small sample down just as hard as a big one — so grinders who keep
    # playing (and inevitably rack up a few average/bad games too) end up looking
    # worse than someone who played the bare minimum and got lucky. We fix this
    # two ways:
    #   1. Bayesian smoothing — shrink each player's average toward the league
    #      baseline by a fixed number of "phantom" matches (K). This tames small
    #      sample swings without capping anyone's ceiling once they have real volume.
    #   2. Explicit experience bonus — a small flat bonus per matches played
    #      (capped) so consistent grinders get real credit for volume rather than
    #      being purely at the mercy of an average.
    prelim = []
    for (user_id, first_name, matches, wins, runs, wickets, sixes, fours,
         hundreds, fifties, ducks, mom, balls_faced, balls_bowled) in all_rows:
        if matches < CCC_MIN_MATCHES:
            continue

        win_rate = (wins / matches) * 100 if matches else 0

        # Weighted point system (total career points, not yet normalized)
        points = (
            runs * 1.0 +
            wickets * 20 +
            wins * 15 +
            sixes * 2 +
            fours * 1 +
            hundreds * 50 +
            fifties * 20 +
            mom * 25 +
            win_rate * matches * 0.5 -
            ducks * 5
        )

        prelim.append({
            "user_id": user_id,
            "first_name": first_name or "Player",
            "matches": matches,
            "wins": wins,
            "points": points,
            "category": classify_player_category(runs, wickets, matches, balls_faced, balls_bowled),
        })

    if not prelim:
        return []

    # League baseline = average points-per-match across all qualified players
    baseline = sum(p["points"] / p["matches"] for p in prelim) / len(prelim)

    K = 15          # regularization strength (in "phantom" matches) — bigger K = more shrinkage for low-volume players
    EXP_BONUS_PER_MATCH = 0.25   # flat reward per real match played, rewarding volume/experience
    EXP_BONUS_CAP_MATCHES = 300  # bonus stops growing past this many matches

    scored = []
    for p in prelim:
        matches = p["matches"]
        points = p["points"]

        # Bayesian-smoothed average: pulls low-sample players toward the baseline
        # instead of letting a handful of great matches rocket them to the top,
        # while barely affecting players who already have a lot of matches.
        smoothed_avg = (points + K * baseline) / (matches + K)

        experience_bonus = min(matches, EXP_BONUS_CAP_MATCHES) * EXP_BONUS_PER_MATCH

        rating = round(smoothed_avg + experience_bonus, 2)

        scored.append({
            "user_id": p["user_id"],
            "first_name": p["first_name"],
            "matches": matches,
            "wins": p["wins"],
            "rating": rating,
            "category": p["category"],
        })

    # Strict deterministic order → guarantees no two players ever share a rank
    scored.sort(key=lambda r: (-r["rating"], -r["matches"], r["user_id"]))
    for i, row in enumerate(scored):
        row["rank"] = i + 1

    return scored


CCC_TREND_WINDOW = timedelta(days=1)  # 🔧 trend arrows (🔼/🔽/🆕) only compare against
                                       # a snapshot taken within the last 1 day; an older
                                       # snapshot is treated as stale and ignored so trend
                                       # effectively resets/expires after 1 day.


def get_ccc_rankings_with_trend(limit: Optional[int] = None):
    """
    Returns the CCC ranking rows (optionally truncated to `limit`), each tagged with a
    'trend' field showing movement since the last snapshot **taken within the last 1 day**:
    '🆕' new entry (or snapshot older than 1 day / missing), '🔼N' climbed N spots,
    '🔽N' dropped N spots, '➖' unchanged.
    Also refreshes the snapshot table used for the next trend comparison.
    """
    rows = _compute_ccc_ranking_rows()

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT user_id, rank, snapshot_at FROM ccc_rank_snapshot")
    now = datetime.now()
    old_ranks = {}
    for uid, r, snap_at in c.fetchall():
        try:
            snap_dt = snap_at if isinstance(snap_at, datetime) else datetime.fromisoformat(str(snap_at))
        except (ValueError, TypeError):
            continue
        # Ignore snapshots older than the trend window — trend "expires" after 1 day
        if now - snap_dt <= CCC_TREND_WINDOW:
            old_ranks[uid] = r

    for row in rows:
        old_rank = old_ranks.get(row["user_id"])
        if old_rank is None:
            row["trend"] = "🆕"
        elif old_rank > row["rank"]:
            row["trend"] = f"🔼{old_rank - row['rank']}"
        elif old_rank < row["rank"]:
            row["trend"] = f"🔽{row['rank'] - old_rank}"
        else:
            row["trend"] = "➖"

        c.execute(
            "INSERT INTO ccc_rank_snapshot (user_id, rank, rating, category, snapshot_at) VALUES (?, ?, ?, ?, ?) "
            "ON CONFLICT(user_id) DO UPDATE SET rank=excluded.rank, rating=excluded.rating, category=excluded.category, snapshot_at=excluded.snapshot_at",
            (row["user_id"], row["rank"], row["rating"], row.get("category", "Batsman"), now)
        )

    conn.commit()
    conn.close()

    return rows[:limit] if limit else rows


def get_player_ccc_rank(user_id: int):
    """Returns this player's CCC ranking row with category-specific rank and trend, or None."""
    rows = get_ccc_rankings_with_trend()
    # Find player's category first
    player_row = None
    for row in rows:
        if row["user_id"] == user_id:
            player_row = row
            break
    if not player_row:
        return None
    # Compute rank within their category
    category = player_row.get("category", "Batsman")
    cat_rank = 1
    for row in rows:
        if row["category"] == category and row["rating"] > player_row["rating"]:
            cat_rank += 1
    player_row["cat_rank"] = cat_rank
    return player_row


def get_ccc_rankings_by_category(category: str, limit: int = 10):
    """Returns CCC rankings filtered to a specific category, re-ranked within that category."""
    all_rows = get_ccc_rankings_with_trend()
    filtered = [r for r in all_rows if r.get("category") == category]
    # Re-rank within category
    for i, row in enumerate(filtered):
        row["cat_rank"] = i + 1
    return filtered[:limit] if limit else filtered


def _build_ccc_rich_html() -> str:
    """Build sendRichMessage HTML for CCC rankings with expandable <h3> dropdowns."""
    rows = get_ccc_rankings_with_trend()
    batsmen = [r for r in rows if r.get("category") == "Batsman"][:10]
    bowlers = [r for r in rows if r.get("category") == "Bowler"][:10]
    allrounders = [r for r in rows if r.get("category") == "All-Rounder"][:10]

    def _cat_table(players):
        if not players:
            return "<p><i>No qualified players yet</i></p>"
        trs = ""
        for i, p in enumerate(players):
            name = html.escape((p.get("first_name") or "Player")[:16])
            trs += (
                f"<tr><td align='center'>{i+1}</td>"
                f"<td>{name}</td>"
                f"<td align='right'>{p['rating']}</td>"
                f"<td align='right'>{p['matches']}</td>"
                f"<td align='center'>{p.get('trend', '🆕')}</td></tr>"
            )
        return (
            "<table bordered striped>"
            "<tr><th>#️⃣</th><th>🧢 Name</th><th>⭐ Rating</th><th>🎮 Matches</th><th>📈 Trend</th></tr>"
            f"{trs}</table>"
        )

    return (
        f"<h3>🏅 CCC RANKING — CricoVerse Career Rating</h3>"
        f"<p>Players auto-classified by stats · min {CCC_MIN_MATCHES} matches</p>"
        f"<h3>🏏 Top 10 Batsmen</h3>"
        f"{_cat_table(batsmen)}"
        f"<h3>⚾ Top 10 Bowlers</h3>"
        f"{_cat_table(bowlers)}"
        f"<h3>🏏⚾ Top 10 All-Rounders</h3>"
        f"{_cat_table(allrounders)}"
        f"<footer>🏅 CRICOVERSE CCC RANKING 🎮</footer>"
    )


def _build_ccc_fallback_text() -> str:
    """Fallback HTML text for CCC when sendRichMessage is not supported."""
    rows = get_ccc_rankings_with_trend()
    batsmen = [r for r in rows if r.get("category") == "Batsman"][:10]
    bowlers = [r for r in rows if r.get("category") == "Bowler"][:10]
    allrounders = [r for r in rows if r.get("category") == "All-Rounder"][:10]

    def _section(title, emoji, players):
        text = f"\n{emoji} <b>{title}</b>\n─────────────────\n"
        if not players:
            text += f"<i>No qualified players yet → play {CCC_MIN_MATCHES}+ matches!</i>\n"
            return text
        for i, p in enumerate(players):
            name = html.escape((p.get('first_name') or 'Player')[:16])
            text += (
                f"{i+1}. <b>{name}</b> · "
                f"⭐ {p['rating']} · {p['matches']}M · {p.get('trend', '🆕')}\n"
            )
        return text

    text = "🏅 <b>CCC RANKING</b> · CricoVerse Career Rating\n"
    text += "═══════════════════\n"
    text += f"Players auto-classified by stats · min {CCC_MIN_MATCHES} matches\n"
    text += _section("Top 10 Batsmen", "🏏", batsmen)
    text += _section("Top 10 Bowlers", "⚾", bowlers)
    text += _section("Top 10 All-Rounders", "🏏⚾", allrounders)
    text += "\n─────────────────\n🏅 CRICOVERSE CCC RANKING 🎮"
    return text


async def ccc_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🏅 /ccc — CCC Career Rating Rankings by category (expandable native tables)"""
    chat_id = update.effective_chat.id

    html_content = await asyncio.to_thread(_build_ccc_rich_html)
    ok = await _tg_send_rich_message(chat_id, html_content)

    if not ok:
        fallback = await asyncio.to_thread(_build_ccc_fallback_text)
        await update.message.reply_text(fallback, parse_mode=ParseMode.HTML)



