async def setup_public_bot_commands(application: Application):
    """Keep Telegram's command menu focused on user-facing commands."""
    # ✅ FIX: Make sure no webhook is left active before we start polling.
    # If a webhook was ever set (e.g. from a previous deployment) and we then
    # call run_polling() / getUpdates(), Telegram raises:
    #   "Conflict: can't use getUpdates method while webhook is active"
    # Deleting the webhook here (it runs once, right before polling starts)
    # makes startup self-healing regardless of how the bot was run before.
    try:
        for attempt in range(5):
            try:
                await application.bot.delete_webhook(drop_pending_updates=True)
                logger.info("✅ Webhook cleared (if any) — safe to start polling.")
                break
            except Exception as e:
                logger.warning(f"delete_webhook attempt {attempt+1}/5 failed: {e}")
                if attempt < 4:
                    await asyncio.sleep(3)
    except Exception as e:
        logger.warning(f"Could not delete webhook (continuing anyway): {e}")

    commands = [
        BotCommand("game", "Start a cricket match"),
        BotCommand("help", "Rules, modes, and quick guide"),
        BotCommand("mystats", "Your profile card and stats"),
        BotCommand("h2h", "Head-to-Head: compare 2 players"),
        BotCommand("scorecard", "Live scorecard and worm graph"),
        BotCommand("players", "Current squads and player status"),
        BotCommand("momentum", "Momentum dashboard image"),
        BotCommand("lb", "Global leaderboard"),
        BotCommand("ccc", "CCC Career Rankings by category"),
        BotCommand("fantasylb", "Fantasy Dream III leaderboard"),
        BotCommand("gcsettings", "Group settings for admins"),
        BotCommand("endmatch", "End the current match"),
    ]
    try:
        await application.bot.set_my_commands(commands)
    except Exception as e:
        logger.warning(f"Could not set public bot commands: {e}")


async def ccc_weekly_dm_job(context: ContextTypes.DEFAULT_TYPE):
    """🏅 Weekly CCC Ranking DM — sends CCC rankings to all players via DM.
    Uses sendRichMessage for native expandable tables, with fallback to HTML text."""
    try:
        html_content = _build_ccc_rich_html()
        fallback = _build_ccc_fallback_text()
    except Exception as e:
        logger.error(f"CCC weekly DM build error: {e}")
        return

    sent = 0
    failed = 0
    for uid in list(user_data.keys()):
        try:
            uid_int = int(uid)
        except (ValueError, TypeError):
            continue
        try:
            ok = await _tg_send_rich_message(uid_int, html_content)
            if not ok:
                await context.bot.send_message(
                    chat_id=uid_int,
                    text=fallback,
                    parse_mode=ParseMode.HTML
                )
            sent += 1
        except (Forbidden, TelegramError):
            failed += 1
        except Exception:
            failed += 1
        await asyncio.sleep(0.5)  # Rate limiting

    logger.info(f"🏅 CCC Weekly DM: sent={sent}, failed={failed}")


def main():
    """Start the bot"""

    # 🔧 GLITCH FIX: single-instance lock. If another cric.py process is
    # already running (e.g. systemd restarted us but the old process hadn't
    # fully died yet, or someone launched a second copy manually in
    # screen/tmux), refuse to start. Two live processes on the same bot token
    # each keep their own separate `active_matches` memory — Telegram's
    # polling flip-flops between them, which is exactly what causes
    # "2 games running in parallel" and "/endsolo only ends one of them".
    import fcntl
    _lock_file_path = "/tmp/cricoverse_bot.lock"
    _lock_file = open(_lock_file_path, "w")
    try:
        fcntl.flock(_lock_file, fcntl.LOCK_EX | fcntl.LOCK_NB)
        _lock_file.write(str(os.getpid()))
        _lock_file.flush()
    except (IOError, OSError):
        logger.error(
            f"❌ Another instance of this bot is already running (lock held on {_lock_file_path}). "
            "Exiting to avoid duplicate-process match glitches. "
            "Run `ps aux | grep cric.py` to find and kill the stale process."
        )
        raise SystemExit(1)

    # Load data on startup
    load_data()
    sync_legacy_player_stats_to_ccc()  # 🔧 FIX: fold old JSON-only stats into CCC ranking
    ensure_fonts()

    # 🌊 Flood-control protection: auto-retry-with-backoff on Telegram rate limits.
    # Falls back to no rate limiter if the optional extra isn't installed
    # (pip install "python-telegram-bot[rate-limiter]").
    _rate_limiter = None
    try:
        from telegram.ext import AIORateLimiter
        _rate_limiter = AIORateLimiter(max_retries=3)
    except ImportError:
        logger.warning("AIORateLimiter unavailable — install python-telegram-bot[rate-limiter] for automatic flood-control retries.")

    # Create application
    _builder = (
        Application.builder()
        .token(BOT_TOKEN)
        .post_init(setup_public_bot_commands)
        .read_timeout(60)
        .write_timeout(60)
        .connect_timeout(60)
        .concurrent_updates(256)
    )
    if _rate_limiter:
        _builder = _builder.rate_limiter(_rate_limiter)
    application = _builder.build()

    # --- JOBS (Scheduled Tasks) ---
    if application.job_queue:
        # Cleanup inactive matches every 60 seconds
        application.job_queue.run_repeating(
            cleanup_inactive_matches, interval=60, first=60
        )

        # Auto Backup every 1 hour
        application.job_queue.run_repeating(
            auto_backup_job, interval=3600, first=10
        )
        
        # Approval expiry checker - runs every 24 hours
        application.job_queue.run_repeating(
            approval_expiry_checker_job, interval=86400, first=60
        )

        # Clone expiry checker - runs every 24 hours
        application.job_queue.run_repeating(
            clone_expiry_checker_job, interval=86400, first=120
        )
        application.job_queue.run_repeating(
            resumable_cleanup_job, interval=1800, first=60
        )

        # Registration expiry + daily reminder checker - runs every hour
        application.job_queue.run_repeating(
            registration_expiry_checker_job, interval=3600, first=300
        )

        # 🎽 Jersey inactivity checker (warn @60 days, release @90 days) - runs every 24 hours
        application.job_queue.run_repeating(
            jersey_inactivity_job, interval=86400, first=180
        )

        # 🎽 /rmjersey activity-check releaser - runs every hour, releases after 2 unanswered days
        application.job_queue.run_repeating(
            jersey_owner_check_job, interval=3600, first=240
        )

        # 🏅 Weekly CCC Ranking DM (every 7 days at 4 AM IST = 22:30 UTC prev day)
        # Calculate first run to align with 4:00 AM IST
        _now_utc = datetime.utcnow()
        _target_ist_hour = 4  # 4 AM IST = 22:30 UTC previous day
        _ist_offset = timedelta(hours=5, minutes=30)
        _now_ist = _now_utc + _ist_offset
        _next_4am_ist = _now_ist.replace(hour=_target_ist_hour, minute=0, second=0, microsecond=0)
        if _next_4am_ist <= _now_ist:
            _next_4am_ist += timedelta(days=1)
        _first_run_secs = (_next_4am_ist - _now_ist).total_seconds()
        application.job_queue.run_repeating(
            ccc_weekly_dm_job, interval=604800, first=_first_run_secs
        )

    # ================== BASIC COMMANDS ==================
    application.add_handler(CommandHandler("start", start_command))
    application.add_handler(CommandHandler("help", help_command))

    # ================== MATCH COMMANDS ==================
    application.add_handler(CommandHandler("game", game_command))
